# Enhanced error handling system
class AudioExtractorError(Exception):
    """Base exception for audio extractor errors"""
    def __init__(self, message: str, error_type: str = "GENERAL", context: Optional[Dict[str, Any]] = None):
        super().__init__(message)
        self.error_type = error_type
        self.context = context or {}
        self.traceback = traceback.format_exc()
        self.timestamp = datetime.utcnow().isoformat()

class ValidationError(AudioExtractorError):
    """Validation-specific errors"""
    def __init__(self, message: str, field_name: str, value: Any, rule: Dict[str, Any]):
        super().__init__(message, "VALIDATION", {"field": field_name, "value": value, "rule": rule})
        self.field_name = field_name
        self.value = value
        self.rule = rule

class FileAccessError(AudioExtractorError):
    """File access-specific errors"""
    def __init__(self, message: str, file_path: str, operation: str):
        super().__init__(message, "FILE_ACCESS", {"file_path": file_path, "operation": operation})
        self.file_path = file_path
        self.operation = operation

class CacheError(AudioExtractorError):
    """Cache-specific errors"""
    def __init__(self, message: str, cache_key: str, operation: str):
        super().__init__(message, "CACHE", {"cache_key": cache_key, "operation": operation})
        self.cache_key = cache_key
        self.operation = operation

class ConcurrencyError(AudioExtractorError):
    """Concurrency-specific errors"""
    def __init__(self, message: str, resource: str, operation: str):
        super().__init__(message, "CONCURRENCY", {"resource": resource, "operation": operation})
        self.resource = resource
        self.operation = operation

class MetricsError(AudioExtractorError):
    """Metrics calculation errors"""
    def __init__(self, message: str, metric_name: str, calculation_context: Dict[str, Any]):
        super().__init__(message, "METRICS", {"metric": metric_name, "context": calculation_context})
        self.metric_name = metric_name
        self.calculation_context = calculation_context


# Enhanced error handling decorator
def handle_errors(error_type: str = "GENERAL", log_traceback: bool = True, reraise: bool = False):
    """Decorator for enhanced error handling with traceback logging"""
    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                # Create enhanced error with full context
                error_context = {
                    'function': func.__name__,
                    'module': func.__module__,
                    'args_count': len(args),
                    'kwargs_keys': list(kwargs.keys()) if kwargs else [],
                    'timestamp': datetime.utcnow().isoformat()
                }
                
                # Determine specific error type
                if isinstance(e, (FileNotFoundError, PermissionError, OSError)):
                    enhanced_error = FileAccessError(str(e), "unknown", func.__name__)
                elif isinstance(e, (ValueError, TypeError)):
                    enhanced_error = ValidationError(str(e), "unknown", None, {})
                elif isinstance(e, KeyError):
                    enhanced_error = CacheError(str(e), "unknown", func.__name__)
                elif isinstance(e, (RuntimeError, threading.ThreadError)):
                    enhanced_error = ConcurrencyError(str(e), "unknown", func.__name__)
                else:
                    enhanced_error = AudioExtractorError(str(e), error_type, error_context)
                
                # Log full traceback if enabled
                if log_traceback:
                    logger = logging.getLogger(func.__module__)
                    logger.error(f"Enhanced error in {func.__name__}: {enhanced_error.message}")
                    logger.error(f"Full traceback: {enhanced_error.traceback}")
                    logger.error(f"Error context: {error_context}")
                
                # Reraise if requested
                if reraise:
                    raise enhanced_error from e
                
                # Return error result for non-void functions
                if hasattr(func, '__annotations__') and 'return' in func.__annotations__:
                    return {'success': False, 'error': enhanced_error.message, 'error_type': enhanced_error.error_type}
                
                return None
        
        return wrapper
    return decorator


# Thread-safe validation rules manager
class ThreadSafeValidationRules:
    """Thread-safe validation rules manager with proper locking"""
    
    def __init__(self):
        self._rules: Dict[str, Dict[str, Any]] = {}
        self._lock = threading.RLock()  # Reentrant lock for nested access
        self._rule_version = 0
        self._last_modified = datetime.utcnow()
        self._access_stats = {
            'reads': 0,
            'writes': 0,
            'locks_acquired': 0,
            'lock_contentions': 0
        }
    
    @handle_errors("RULES_ACCESS", log_traceback=True)
    def get_rule(self, field_name: str) -> Optional[Dict[str, Any]]:
        """Get validation rule with thread safety"""
        start_time = time.time()
        
        with self._lock:
            self._access_stats['reads'] += 1
            self._access_stats['locks_acquired'] += 1
            
            # Check for lock contention
            lock_wait_time = time.time() - start_time
            if lock_wait_time > 0.001:  # 1ms threshold
                self._access_stats['lock_contentions'] += 1
            
            rule = self._rules.get(field_name)
            
            # Return a copy to prevent external mutation
            if rule:
                return rule.copy()
            return None
    
    @handle_errors("RULES_MODIFY", log_traceback=True)
    def set_rule(self, field_name: str, rule: Dict[str, Any]) -> None:
        """Set validation rule with thread safety"""
        start_time = time.time()
        
        with self._lock:
            self._access_stats['writes'] += 1
            self._access_stats['locks_acquired'] += 1
            
            # Check for lock contention
            lock_wait_time = time.time() - start_time
            if lock_wait_time > 0.001:
                self._access_stats['lock_contentions'] += 1
            
            # Validate rule structure
            self._validate_rule_structure(rule)
            
            # Store rule (make a copy to prevent external mutation)
            self._rules[field_name] = rule.copy()
            self._rule_version += 1
            self._last_modified = datetime.utcnow()
    
    @handle_errors("RULES_REMOVE", log_traceback=True)
    def remove_rule(self, field_name: str) -> bool:
        """Remove validation rule with thread safety"""
        start_time = time.time()
        
        with self._lock:
            self._access_stats['writes'] += 1
            self._access_stats['locks_acquired'] += 1
            
            # Check for lock contention
            lock_wait_time = time.time() - start_time
            if lock_wait_time > 0.001:
                self._access_stats['lock_contentions'] += 1
            
            if field_name in self._rules:
                del self._rules[field_name]
                self._rule_version += 1
                self._last_modified = datetime.utcnow()
                return True
            return False
    
    @handle_errors("RULES_BATCH", log_traceback=True)
    def get_all_rules(self) -> Dict[str, Dict[str, Any]]:
        """Get all rules with thread safety"""
        with self._lock:
            self._access_stats['reads'] += 1
            self._access_stats['locks_acquired'] += 1
            
            # Return deep copy to prevent external mutation
            return {k: v.copy() for k, v in self._rules.items()}
    
    @handle_errors("RULES_BATCH", log_traceback=True)
    def update_rules(self, rules: Dict[str, Dict[str, Any]]) -> None:
        """Batch update rules with thread safety"""
        start_time = time.time()
        
        with self._lock:
            self._access_stats['writes'] += 1
            self._access_stats['locks_acquired'] += 1
            
            # Check for lock contention
            lock_wait_time = time.time() - start_time
            if lock_wait_time > 0.001:
                self._access_stats['lock_contentions'] += 1
            
            # Validate all rules
            for field_name, rule in rules.items():
                self._validate_rule_structure(rule)
            
            # Update all rules
            self._rules.update({k: v.copy() for k, v in rules.items()})
            self._rule_version += 1
            self._last_modified = datetime.utcnow()
    
    def _validate_rule_structure(self, rule: Dict[str, Any]) -> None:
        """Validate rule structure"""
        required_fields = ['field_name']
        for field in required_fields:
            if field not in rule:
                raise ValidationError(f"Missing required field '{field}' in validation rule", 
                                 rule.get('field_name', 'unknown'), rule, rule)
    
    def get_access_stats(self) -> Dict[str, Any]:
        """Get access statistics"""
        with self._lock:
            return {
                'rule_count': len(self._rules),
                'rule_version': self._rule_version,
                'last_modified': self._last_modified.isoformat(),
                'access_stats': self._access_stats.copy(),
                'lock_contention_rate': (
                    self._access_stats['lock_contentions'] / 
                    max(self._access_stats['locks_acquired'], 1) * 100
                )
            }


# Enhanced metrics calculation with robust edge-case handling
class RobustMetricsCalculator:
    """Robust metrics calculator with comprehensive edge-case handling"""
    
    def __init__(self):
        self.calculation_errors = []
        self.edge_case_handlers = {
            'decimal_places': self._handle_decimal_places_edge_case,
            'scientific_notation': self._handle_scientific_notation_edge_case,
            'infinite_values': self._handle_infinite_values_edge_case,
            'nan_values': self._handle_nan_values_edge_case,
            'zero_division': self._handle_zero_division_edge_case,
            'precision_loss': self._handle_precision_loss_edge_case
        }
    
    @handle_errors("METRICS_CALCULATION", log_traceback=True)
    def calculate_decimal_places(self, value: Union[str, float, int]) -> int:
        """Calculate decimal places with robust edge-case handling"""
        try:
            # Handle different input types
            if isinstance(value, int):
                return 0
            elif isinstance(value, float):
                return self._calculate_float_decimal_places(value)
            elif isinstance(value, str):
                return self._calculate_string_decimal_places(value)
            else:
                raise MetricsError(f"Unsupported type for decimal places calculation: {type(value)}", 
                                  "decimal_places", {"value": value, "type": str(type(value))})
        
        except Exception as e:
            # Use edge-case handler
            return self.edge_case_handlers['decimal_places'](value, e)
    
    def _calculate_float_decimal_places(self, value: float) -> int:
        """Calculate decimal places for float values"""
        # Handle special cases first
        if math.isnan(value) or math.isinf(value):
            raise MetricsError(f"Cannot calculate decimal places for {value}", 
                              "decimal_places", {"value": value})
        
        # Convert to string and analyze
        str_value = f"{value:.15f}".rstrip('0').rstrip('.')
        
        if '.' in str_value:
            return len(str_value.split('.')[1])
        else:
            return 0
    
    def _calculate_string_decimal_places(self, value: str) -> int:
        """Calculate decimal places for string values"""
        # Handle scientific notation
        if 'e' in value.lower():
            return self._handle_scientific_notation_edge_case(value, None)
        
        # Remove sign and handle decimal point
        clean_value = value.lstrip('-+')
        
        if '.' in clean_value:
            decimal_part = clean_value.split('.')[1]
            # Remove trailing zeros
            decimal_part = decimal_part.rstrip('0')
            return len(decimal_part)
        else:
            return 0
    
    def _handle_decimal_places_edge_case(self, value: Any, error: Exception) -> int:
        """Handle edge cases for decimal places calculation"""
        try:
            # Try string conversion as fallback
            str_value = str(value)
            
            # Handle scientific notation
            if 'e' in str_value.lower():
                return self._handle_scientific_notation_edge_case(str_value, error)
            
            # Simple fallback: count digits after decimal point
            if '.' in str_value:
                return len(str_value.split('.')[1].rstrip('0'))
            else:
                return 0
                
        except Exception:
            # Ultimate fallback
            self.calculation_errors.append({
                'timestamp': datetime.utcnow().isoformat(),
                'operation': 'decimal_places',
                'value': str(value),
                'error': str(error),
                'fallback_used': True
            })
            return 0
    
    def _handle_scientific_notation_edge_case(self, value: Any, error: Optional[Exception]) -> int:
        """Handle scientific notation edge case"""
        try:
            str_value = str(value).lower()
            
            if 'e' in str_value:
                # Parse scientific notation: 1.23e-6
                parts = str_value.split('e')
                if len(parts) == 2:
                    mantissa = parts[0]
                    exponent = int(parts[1])
                    
                    # Calculate decimal places in mantissa
                    if '.' in mantissa:
                        mantissa_decimal_places = len(mantissa.split('.')[1].rstrip('0'))
                    else:
                        mantissa_decimal_places = 0
                    
                    # Adjust for exponent
                    if exponent < 0:
                        return mantissa_decimal_places + abs(exponent)
                    else:
                        return max(0, mantissa_decimal_places - exponent)
            
            return 0
            
        except Exception as e:
            self.calculation_errors.append({
                'timestamp': datetime.utcnow().isoformat(),
                'operation': 'scientific_notation',
                'value': str(value),
                'error': str(e),
                'fallback_used': True
            })
            return 0
    
    def _handle_infinite_values_edge_case(self, value: Any, error: Optional[Exception]) -> Any:
        """Handle infinite values edge case"""
        self.calculation_errors.append({
            'timestamp': datetime.utcnow().isoformat(),
            'operation': 'infinite_values',
            'value': str(value),
            'error': str(error) if error else 'Infinite value encountered',
            'fallback_used': True
        })
        return None
    
    def _handle_nan_values_edge_case(self, value: Any, error: Optional[Exception]) -> Any:
        """Handle NaN values edge case"""
        self.calculation_errors.append({
            'timestamp': datetime.utcnow().isoformat(),
            'operation': 'nan_values',
            'value': str(value),
            'error': str(error) if error else 'NaN value encountered',
            'fallback_used': True
        })
        return None
    
    def _handle_zero_division_edge_case(self, value: Any, error: Optional[Exception]) -> Any:
        """Handle zero division edge case"""
        self.calculation_errors.append({
            'timestamp': datetime.utcnow().isoformat(),
            'operation': 'zero_division',
            'value': str(value),
            'error': str(error) if error else 'Zero division encountered',
            'fallback_used': True
        })
        return None
    
    def _handle_precision_loss_edge_case(self, value: Any, error: Optional[Exception]) -> Any:
        """Handle precision loss edge case"""
        self.calculation_errors.append({
            'timestamp': datetime.utcnow().isoformat(),
            'operation': 'precision_loss',
            'value': str(value),
            'error': str(error) if error else 'Precision loss detected',
            'fallback_used': True
        })
        return None
    
    @handle_errors("METRICS_CALCULATION", log_traceback=True)
    def calculate_statistics(self, values: List[Union[int, float]]) -> Dict[str, Any]:
        """Calculate comprehensive statistics with edge-case handling"""
        if not values:
            return {
                'count': 0,
                'mean': None,
                'median': None,
                'std_dev': None,
                'min': None,
                'max': None,
                'sum': None,
                'decimal_places_avg': None,
                'error': 'Empty dataset'
            }
        
        try:
            # Filter out invalid values
            valid_values = []
            for v in values:
                if isinstance(v, (int, float)) and not math.isnan(v) and not math.isinf(v):
                    valid_values.append(v)
                else:
                    # Handle edge cases
                    if math.isnan(v):
                        self._handle_nan_values_edge_case(v, None)
                    elif math.isinf(v):
                        self._handle_infinite_values_edge_case(v, None)
            
            if not valid_values:
                return {
                    'count': len(values),
                    'mean': None,
                    'median': None,
                    'std_dev': None,
                    'min': None,
                    'max': None,
                    'sum': None,
                    'decimal_places_avg': None,
                    'error': 'No valid values'
                }
            
            # Calculate statistics
            count = len(valid_values)
            mean_val = sum(valid_values) / count
            sorted_values = sorted(valid_values)
            median_val = sorted_values[count // 2] if count % 2 == 1 else (sorted_values[count // 2 - 1] + sorted_values[count // 2]) / 2
            
            # Calculate standard deviation
            variance = sum((x - mean_val) ** 2 for x in valid_values) / count
            std_dev_val = variance ** 0.5
            
            # Calculate average decimal places
            decimal_places_list = [self.calculate_decimal_places(v) for v in valid_values]
            avg_decimal_places = sum(decimal_places_list) / len(decimal_places_list)
            
            return {
                'count': count,
                'mean': mean_val,
                'median': median_val,
                'std_dev': std_dev_val,
                'min': min(valid_values),
                'max': max(valid_values),
                'sum': sum(valid_values),
                'decimal_places_avg': avg_decimal_places,
                'decimal_places_distribution': {
                    'min': min(decimal_places_list),
                    'max': max(decimal_places_list),
                    'mode': max(set(decimal_places_list), key=decimal_places_list.count)
                }
            }
            
        except Exception as e:
            return {
                'count': len(values),
                'mean': None,
                'median': None,
                'std_dev': None,
                'min': None,
                'max': None,
                'sum': None,
                'decimal_places_avg': None,
                'error': str(e),
                'error_type': type(e).__name__
            }
    
    def get_calculation_errors(self) -> List[Dict[str, Any]]:
        """Get all calculation errors"""
        return self.calculation_errors.copy()
    
    def clear_calculation_errors(self) -> None:
        """Clear calculation errors"""
        self.calculation_errors.clear()


# Enhanced async validation with ThreadPoolExecutor for CPU-bound tasks
class AsyncValidationEngine:
    """Enhanced async validation engine with ThreadPoolExecutor for CPU-bound tasks"""
    
    def __init__(self, max_workers: Optional[int] = None):
        # Determine optimal worker count
        if max_workers is None:
            max_workers = min(32, (os.cpu_count() or 1) + 4)  # Based on asyncio recommendations
        
        self.max_workers = max_workers
        self.thread_pool = ThreadPoolExecutor(max_workers=max_workers)
        self.async_semaphore = asyncio.Semaphore(max_workers * 2)  # Allow more concurrent tasks
        self.validation_stats = {
            'total_validations': 0,
            'thread_pool_validations': 0,
            'async_validations': 0,
            'average_validation_time_ms': 0,
            'thread_pool_utilization': 0.0
        }
        self._shutdown = False
    
    @handle_errors("ASYNC_VALIDATION", log_traceback=True)
    async def validate_cpu_bound_batch(self, 
                                     validation_func: callable,
                                     items: List[Any],
                                     rules: Dict[str, Any]) -> List[Dict[str, Any]]:
        """Validate CPU-bound batch using ThreadPoolExecutor"""
        if self._shutdown:
            raise ConcurrencyError("Validation engine is shutdown", "ThreadPoolExecutor", "validate_cpu_bound_batch")
        
        start_time = time.time()
        
        # Use semaphore to limit concurrent tasks
        async with self.async_semaphore:
            # Submit CPU-bound tasks to thread pool
            loop = asyncio.get_event_loop()
            
            # Create tasks for thread pool
            tasks = []
            for item in items:
                task = loop.run_in_executor(
                    self.thread_pool,
                    self._validate_single_item_safe,
                    validation_func,
                    item,
                    rules
                )
                tasks.append(task)
            
            # Wait for all tasks to complete
            results = await asyncio.gather(*tasks, return_exceptions=True)
            
            # Process results
            processed_results = []
            for i, result in enumerate(results):
                if isinstance(result, Exception):
                    processed_results.append({
                        'success': False,
                        'error': str(result),
                        'error_type': type(result).__name__,
                        'item_index': i,
                        'traceback': traceback.format_exc()
                    })
                else:
                    processed_results.append(result)
            
            # Update statistics
            validation_time = (time.time() - start_time) * 1000
            self.validation_stats['total_validations'] += len(items)
            self.validation_stats['thread_pool_validations'] += len(items)
            self.validation_stats['thread_pool_utilization'] = (
                len(items) / self.max_workers
            )
            
            # Update average time
            total_time = self.validation_stats['average_validation_time_ms'] * (self.validation_stats['total_validations'] - len(items))
            current_time = validation_time
            self.validation_stats['average_validation_time_ms'] = (total_time + current_time) / self.validation_stats['total_validations']
            
            return processed_results
    
    def _validate_single_item_safe(self, validation_func: callable, item: Any, rules: Dict[str, Any]) -> Dict[str, Any]:
        """Safe single item validation with error handling"""
        try:
            return validation_func(item, rules)
        except Exception as e:
            return {
                'success': False,
                'error': str(e),
                'error_type': type(e).__name__,
                'traceback': traceback.format_exc(),
                'item': str(item)[:100]  # Limit item size for logging
            }
    
    @handle_errors("ASYNC_VALIDATION", log_traceback=True)
    async def validate_io_bound_batch(self, 
                                      validation_func: callable,
                                      items: List[Any],
                                      rules: Dict[str, Any]) -> List[Dict[str, Any]]:
        """Validate I/O-bound batch using asyncio (no thread pool)"""
        if self._shutdown:
            raise ConcurrencyError("Validation engine is shutdown", "asyncio", "validate_io_bound_batch")
        
        start_time = time.time()
        
        # Use semaphore to limit concurrent tasks
        async with self.async_semaphore:
            # Create async tasks
            tasks = []
            for item in items:
                task = asyncio.create_task(
                    self._validate_single_item_async_safe(validation_func, item, rules)
                )
                tasks.append(task)
            
            # Wait for all tasks to complete
            results = await asyncio.gather(*tasks, return_exceptions=True)
            
            # Process results
            processed_results = []
            for i, result in enumerate(results):
                if isinstance(result, Exception):
                    processed_results.append({
                        'success': False,
                        'error': str(result),
                        'error_type': type(result).__name__,
                        'item_index': i,
                        'traceback': traceback.format_exc()
                    })
                else:
                    processed_results.append(result)
            
            # Update statistics
            validation_time = (time.time() - start_time) * 1000
            self.validation_stats['total_validations'] += len(items)
            self.validation_stats['async_validations'] += len(items)
            
            # Update average time
            total_time = self.validation_stats['average_validation_time_ms'] * (self.validation_stats['total_validations'] - len(items))
            current_time = validation_time
            self.validation_stats['average_validation_time_ms'] = (total_time + current_time) / self.validation_stats['total_validations']
            
            return processed_results
    
    async def _validate_single_item_async_safe(self, validation_func: callable, item: Any, rules: Dict[str, Any]) -> Dict[str, Any]:
        """Safe single item async validation with error handling"""
        try:
            # If validation function is async, await it directly
            if asyncio.iscoroutinefunction(validation_func):
                return await validation_func(item, rules)
            else:
                # For sync functions, run in thread pool
                loop = asyncio.get_event_loop()
                return await loop.run_in_executor(self.thread_pool, validation_func, item, rules)
        except Exception as e:
            return {
                'success': False,
                'error': str(e),
                'error_type': type(e).__name__,
                'traceback': traceback.format_exc(),
                'item': str(item)[:100]
            }
    
    def get_validation_stats(self) -> Dict[str, Any]:
        """Get validation statistics"""
        return {
            'timestamp': datetime.utcnow().isoformat(),
            'max_workers': self.max_workers,
            'validation_stats': self.validation_stats.copy(),
            'thread_pool_info': {
                'active_threads': threading.active_count(),
                'cpu_count': os.cpu_count(),
                'shutdown': self._shutdown
            }
        }
    
    async def shutdown(self) -> None:
        """Shutdown the validation engine"""
        self._shutdown = True
        
        # Shutdown thread pool
        self.thread_pool.shutdown(wait=True)
        
        # Clear semaphore
        self.async_semaphore = None


# Global instances for production-ready components
