# Production-ready validation pipeline integration
class ProductionValidationPipeline:
    """Production-ready validation pipeline with all enhancements"""
    
    def __init__(self, config: Optional[ProductionConfig] = None):
        self.config = config or production_config
        
        # Initialize enhanced components
        self.enhanced_validator = enhanced_async_validator
        self.tiered_rules = tiered_validation_rules
        self.thread_safe_rules = thread_safe_rules
        self.robust_metrics = robust_metrics
        self.async_engine = async_validation_engine
        
        # Performance monitoring
        self.pipeline_stats = {
            'total_validations': 0,
            'successful_validations': 0,
            'failed_validations': 0,
            'average_processing_time_ms': 0,
            'cpu_bound_validations': 0,
            'io_bound_validations': 0,
            'thread_safe_operations': 0,
            'edge_case_handlings': 0
        }
        
        # Health monitoring
        self.health_status = {
            'overall_health': 'HEALTHY',
            'component_health': {
                'enhanced_validator': 'HEALTHY',
                'tiered_rules': 'HEALTHY',
                'thread_safe_rules': 'HEALTHY',
                'robust_metrics': 'HEALTHY',
                'async_engine': 'HEALTHY'
            },
            'last_health_check': datetime.utcnow().isoformat(),
            'alerts': []
        }
        
        enhanced_logger.info("Production validation pipeline initialized")
    
    @handle_errors("PIPELINE_VALIDATION", log_traceback=True)
    async def validate_production_batch(self, 
                                      dataset: Dict[str, List[Any]], 
                                      validation_rules: Dict[str, Any],
                                      tolerance_tier: str = 'standard') -> Dict[str, Any]:
        """Production-ready batch validation with all enhancements"""
        
        pipeline_start = time.time()
        
        try:
            # Update thread-safe rules
            self.thread_safe_rules.update_rules(validation_rules.get('numeric_rules', {}))
            
            # Determine validation strategy
            total_items = sum(len(values) for values in dataset.values())
            
            results = {
                'success': True,
                'method': 'production_pipeline',
                'field_results': {},
                'pipeline_metrics': {
                    'total_items': total_items,
                    'processing_time_ms': 0,
                    'tolerance_tier': tolerance_tier,
                    'enhancements_used': []
                }
            }
            
            # Process each field with production enhancements
            for field_name, values in dataset.items():
                field_start = time.time()
                
                try:
                    # Get tiered rule
                    tiered_rule = self.tiered_rules.get_tiered_rule(field_name, tolerance_tier)
                    if not tiered_rule:
                        results['field_results'][field_name] = {
                            'success': False,
                            'error': f'No validation rule found for field: {field_name}'
                        }
                        results['success'] = False
                        continue
                    
                    # Choose validation method based on data characteristics
                    if len(values) >= self.config.performance['batch_size_threshold']:
                        # Use enhanced async validation for large batches
                        field_result = await self._validate_large_batch_enhanced(
                            field_name, values, tiered_rule
                        )
                        results['pipeline_metrics']['enhancements_used'].append('enhanced_async_validation')
                    else:
                        # Use thread-safe validation for small batches
                        field_result = await self._validate_small_batch_thread_safe(
                            field_name, values, tiered_rule
                        )
                        results['pipeline_metrics']['enhancements_used'].append('thread_safe_validation')
                    
                    # Update historical metrics
                    field_processing_time = (time.time() - field_start) * 1000
                    self.tiered_rules.update_historical_metrics(field_name, field_result, field_processing_time)
                    
                    results['field_results'][field_name] = field_result
                    
                    if not field_result.get('success', True):
                        results['success'] = False
                
                except Exception as e:
                    # Enhanced error handling
                    error_result = {
                        'success': False,
                        'error': str(e),
                        'error_type': type(e).__name__,
                        'traceback': traceback.format_exc(),
                        'field_name': field_name
                    }
                    
                    results['field_results'][field_name] = error_result
                    results['success'] = False
                    
                    # Log enhanced error
                    enhanced_logger.error(f"Production validation error for field {field_name}: {e}")
                    enhanced_logger.error(f"Full traceback: {traceback.format_exc()}")
            
            # Update pipeline statistics
            processing_time = (time.time() - pipeline_start) * 1000
            results['pipeline_metrics']['processing_time_ms'] = processing_time
            
            self._update_pipeline_stats(results, processing_time)
            
            # Perform health check
            await self._perform_health_check()
            
            results['pipeline_metrics']['health_status'] = self.health_status
            
            return results
            
        except Exception as e:
            # Pipeline-level error handling
            enhanced_logger.critical(f"Production pipeline failure: {e}")
            enhanced_logger.critical(f"Full traceback: {traceback.format_exc()}")
            
            return {
                'success': False,
                'error': str(e),
                'error_type': type(e).__name__,
                'traceback': traceback.format_exc(),
                'pipeline_metrics': {
                    'processing_time_ms': (time.time() - pipeline_start) * 1000,
                    'health_status': 'CRITICAL'
                }
            }
    
    async def _validate_large_batch_enhanced(self, 
                                           field_name: str, 
                                           values: List[Any], 
                                           rule: Dict[str, Any]) -> Dict[str, Any]:
        """Validate large batch using enhanced async validation"""
        
        self.pipeline_stats['cpu_bound_validations'] += 1
        
        # Use enhanced async validator with ThreadPoolExecutor
        if rule.get('validation_type') == 'numeric':
            return await self.enhanced_validator.validate_numeric_batch_async(
                values, [rule], [field_name]
            )
        elif rule.get('validation_type') == 'timing':
            return await self.enhanced_validator.validate_timing_batch_async(
                values, [rule], [field_name]
            )
        else:
            # Default to standard validation
            return await self.enhanced_validator.validate_with_thread_safety(
                rule.get('validation_type', 'unknown'), field_name, values[0], rule
            )
    
    async def _validate_small_batch_thread_safe(self, 
                                               field_name: str, 
                                               values: List[Any], 
                                               rule: Dict[str, Any]) -> Dict[str, Any]:
        """Validate small batch using thread-safe validation"""
        
        self.pipeline_stats['thread_safe_operations'] += 1
        
        # Process each item with thread safety
        results = []
        for value in values:
            result = await self.enhanced_validator.validate_with_thread_safety(
                rule.get('validation_type', 'unknown'), field_name, value, rule
            )
            results.append(result)
        
        # Aggregate results
        success_count = sum(1 for r in results if r.get('success', False))
        
        return {
            'success': success_count == len(results),
            'success_count': success_count,
            'failure_count': len(results) - success_count,
            'individual_results': results[:10],  # Limit for memory
            'method': 'thread_safe_batch'
        }
    
    def _update_pipeline_stats(self, results: Dict[str, Any], processing_time: float) -> None:
        """Update pipeline statistics"""
        
        self.pipeline_stats['total_validations'] += 1
        
        if results.get('success', True):
            self.pipeline_stats['successful_validations'] += 1
        else:
            self.pipeline_stats['failed_validations'] += 1
        
        # Update average processing time
        total_time = self.pipeline_stats['average_processing_time_ms'] * (self.pipeline_stats['total_validations'] - 1)
        current_time = processing_time
        self.pipeline_stats['average_processing_time_ms'] = (total_time + current_time) / self.pipeline_stats['total_validations']
    
    async def _perform_health_check(self) -> None:
        """Perform comprehensive health check"""
        
        try:
            # Get production readiness report
            health_report = await self.enhanced_validator.get_production_readiness_report()
            
            # Update health status
            self.health_status['overall_health'] = health_report['health_status']
            self.health_status['last_health_check'] = datetime.utcnow().isoformat()
            
            # Check component health
            self.health_status['component_health']['enhanced_validator'] = health_report['health_status']
            self.health_status['component_health']['thread_safe_rules'] = (
                'HEALTHY' if health_report['thread_safe_rules']['lock_contention_rate'] < 10 else 'WARNING'
            )
            self.health_status['component_health']['robust_metrics'] = (
                'HEALTHY' if health_report['robust_metrics']['error_count'] < 50 else 'WARNING'
            )
            
            # Generate alerts
            self.health_status['alerts'] = health_report['recommendations']
            
            # Log health status
            if self.health_status['overall_health'] != 'HEALTHY':
                enhanced_logger.warning(f"Pipeline health status: {self.health_status['overall_health']}")
                for alert in self.health_status['alerts']:
                    enhanced_logger.warning(f"Health alert: {alert}")
            
        except Exception as e:
            enhanced_logger.error(f"Health check failed: {e}")
            self.health_status['overall_health'] = 'UNKNOWN'
    
    def get_pipeline_status(self) -> Dict[str, Any]:
        """Get comprehensive pipeline status"""
        
        return {
            'timestamp': datetime.utcnow().isoformat(),
            'pipeline_stats': self.pipeline_stats.copy(),
            'health_status': self.health_status.copy(),
            'config_summary': self.config.get_config_summary(),
            'component_stats': {
                'thread_safe_rules': self.thread_safe_rules.get_access_stats(),
                'robust_metrics_errors': len(self.robust_metrics.get_calculation_errors()),
                'async_validation': self.async_engine.get_validation_stats()
            }
        }
    
    async def shutdown_pipeline(self) -> None:
        """Shutdown production pipeline gracefully"""
        
        enhanced_logger.info("Shutting down production validation pipeline")
        
        try:
            # Shutdown enhanced validator
            await self.enhanced_validator.shutdown_async()
            
            # Clear calculation errors
            self.robust_metrics.clear_calculation_errors()
            
            enhanced_logger.info("Production validation pipeline shutdown complete")
            
        except Exception as e:
            enhanced_logger.error(f"Error during pipeline shutdown: {e}")
            enhanced_logger.error(f"Full traceback: {traceback.format_exc()}")


