# Audio data structures
@dataclass
class AudioBuffer:
    """High-precision audio buffer with nanosecond timing"""
    samples: np.ndarray
    sample_rate: int
    channels: int
    bit_depth: int
    duration_seconds: float
    nanosecond_timestamps: Optional[np.ndarray] = None
    format: str = 'float32'
    
    def __post_init__(self):
        if self.nanosecond_timestamps is None:
            # Generate nanosecond timestamps
            sample_interval_ns = 1_000_000_000 // self.sample_rate
            self.nanosecond_timestamps = np.arange(
                len(self.samples), 
                dtype=np.int64
            ) * sample_interval_ns
    
    @property
    def shape(self) -> Tuple[int, ...]:
        return self.samples.shape
    
    @property
    def total_samples(self) -> int:
        return len(self.samples)
    
    def get_channel(self, channel: int) -> 'AudioBuffer':
        """Extract single channel"""
        if self.channels == 1:
            return self
        
        return AudioBuffer(
            samples=self.samples[:, channel] if self.channels > 1 else self.samples,
            sample_rate=self.sample_rate,
            channels=1,
            bit_depth=self.bit_depth,
            duration_seconds=self.duration_seconds,
            nanosecond_timestamps=self.nanosecond_timestamps,
            format=self.format
        )

@dataclass
class AudioMetadata:
    """Comprehensive audio metadata"""
    file_path: str
    format: str
    sample_rate: int
    channels: int
    bit_depth: int
    duration_seconds: float
    file_size_bytes: int
    bitrate: Optional[int] = None
    codec: Optional[str] = None
    created_time: Optional[datetime] = None
    modified_time: Optional[datetime] = None
    
@dataclass
class SpectralData:
    """Spectral analysis results"""
    frequencies: np.ndarray
    magnitudes: np.ndarray
    phases: np.ndarray
    sample_rate: int
    fft_size: int
    window_type: str
    
@dataclass
class EnvelopeData:
    """Audio envelope analysis"""
    envelope: np.ndarray
    attack_times: np.ndarray
    decay_times: np.ndarray
    sustain_level: float
