nanosecond_timing_analyzer = NanosecondTimingAnalyzer()

# ============================================================================
# AUDIO PREPROCESSOR - GOOGLE-LEVEL AUDIO PROCESSING
# ============================================================================

class AudioPreprocessor:
    """Production-grade audio preprocessing with advanced algorithms"""
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        
        # Preprocessing parameters
        self.resample_method = self.config.get('resample_method', 'kaiser_best')
        self.normalize_method = self.config.get('normalize_method', 'peak')
        self.target_level_dbfs = self.config.get('target_level_dbfs', -1.0)
        self.denoise_method = self.config.get('denoise_method', 'spectral_subtraction')
        self.silence_threshold_db = self.config.get('silence_threshold_db', -40)
        self.fade_duration_ms = self.config.get('fade_duration_ms', 10)
        
    @handle_errors("AUDIO_PREPROCESSING", log_traceback=True)
    def resample(self, audio_buffer: AudioBuffer, target_sample_rate: int) -> AudioBuffer:
        """Resample audio to target sample rate with high quality"""
        
        if audio_buffer.sample_rate == target_sample_rate:
            return audio_buffer
        
        try:
            # Use librosa for high-quality resampling
            resampled_samples = librosa.resample(
                audio_buffer.samples.T,  # librosa expects (channels, samples)
                orig_sr=audio_buffer.sample_rate,
                target_sr=target_sample_rate,
                res_type=self.resample_method
            ).T  # Transpose back to (samples, channels)
            
            # Calculate new duration
            new_duration_seconds = len(resampled_samples) / target_sample_rate
            
            return AudioBuffer(
                samples=resampled_samples,
                sample_rate=target_sample_rate,
                channels=audio_buffer.channels,
                bit_depth=audio_buffer.bit_depth,
                duration_seconds=new_duration_seconds,
                format=audio_buffer.format
            )
            
        except Exception as e:
            raise AudioExtractionError(f"Failed to resample audio: {str(e)}")
    
    @handle_errors("AUDIO_PREPROCESSING", log_traceback=True)
    def normalize(self, audio_buffer: AudioBuffer, method: Optional[str] = None) -> AudioBuffer:
        """Normalize audio with multiple methods"""
        
        method = method or self.normalize_method
        normalized_samples = audio_buffer.samples.copy()
        
        try:
            if method == 'peak':
                # Peak normalization to target level
                max_amplitude = np.max(np.abs(normalized_samples))
                if max_amplitude > 0:
                    target_amplitude = 10 ** (self.target_level_dbfs / 20)
                    scale_factor = target_amplitude / max_amplitude
                    normalized_samples *= scale_factor
                    
            elif method == 'rms':
                # RMS normalization
                rms = np.sqrt(np.mean(normalized_samples ** 2))
                if rms > 0:
                    target_rms = 10 ** (self.target_level_dbfs / 20)
                    scale_factor = target_rms / rms
                    normalized_samples *= scale_factor
                    
            elif method == 'lufs':
                # LUFS normalization (simplified implementation)
                # This would require pyln for true LUFS measurement
                # For now, use RMS as approximation
                rms = np.sqrt(np.mean(normalized_samples ** 2))
                if rms > 0:
                    target_rms = 0.23  # Approximate LUFS target
                    scale_factor = target_rms / rms
                    normalized_samples *= scale_factor
                    
            else:
                raise AudioExtractionError(f"Unknown normalization method: {method}")
            
            return AudioBuffer(
                samples=normalized_samples,
                sample_rate=audio_buffer.sample_rate,
                channels=audio_buffer.channels,
                bit_depth=audio_buffer.bit_depth,
                duration_seconds=audio_buffer.duration_seconds,
                format=audio_buffer.format
            )
            
        except Exception as e:
            raise AudioExtractionError(f"Failed to normalize audio: {str(e)}")
    
    @handle_errors("AUDIO_PREPROCESSING", log_traceback=True)
    def denoise(self, audio_buffer: AudioBuffer) -> AudioBuffer:
        """Apply denoising using spectral subtraction"""
        
        try:
            # Use first channel for denoising
            if audio_buffer.channels > 1:
                samples = audio_buffer.samples[:, 0]
            else:
                samples = audio_buffer.samples.flatten()
            
            # Simple spectral subtraction denoising
            # Estimate noise spectrum from first few frames
            noise_frames = 10
            fft_size = 2048
            
            # Calculate noise spectrum
            noise_spectrum = np.zeros(fft_size // 2 + 1)
            for i in range(noise_frames):
                start_idx = i * fft_size // 2
                if start_idx + fft_size < len(samples):
                    noise_frame = samples[start_idx:start_idx + fft_size]
                    windowed = noise_frame * signal.get_window('hann', fft_size)
                    noise_fft = np.abs(fft(windowed))[:fft_size // 2 + 1]
                    noise_spectrum += noise_fft
            
            noise_spectrum /= noise_frames
            
            # Apply spectral subtraction
            denoised_samples = np.zeros_like(samples)
            overlap = fft_size // 2
            
            for i in range(0, len(samples) - fft_size, overlap):
                frame = samples[i:i + fft_size]
                windowed = frame * signal.get_window('hann', fft_size)
                frame_fft = fft(windowed)
                
                # Spectral subtraction
                magnitude = np.abs(frame_fft)
                phase = np.angle(frame_fft)
                
                # Subtract noise (with over-subtraction factor)
                alpha = 2.0  # Over-subtraction factor
                beta = 0.1   # Spectral floor
                
                subtracted_magnitude = magnitude - alpha * noise_spectrum
                subtracted_magnitude = np.maximum(subtracted_magnitude, beta * magnitude)
                
                # Reconstruct signal
                clean_fft = subtracted_magnitude * np.exp(1j * phase)
                clean_frame = np.real(np.fft.ifft(clean_fft))
                
                # Overlap-add
                denoised_samples[i:i + fft_size] += clean_frame * signal.get_window('hann', fft_size)
            
            # Apply to all channels
            if audio_buffer.channels > 1:
                denoised_samples_multi = np.zeros_like(audio_buffer.samples)
                for ch in range(audio_buffer.channels):
                    denoised_samples_multi[:, ch] = denoised_samples
                final_samples = denoised_samples_multi
            else:
                final_samples = denoised_samples.reshape(-1, 1)
            
            return AudioBuffer(
                samples=final_samples,
                sample_rate=audio_buffer.sample_rate,
                channels=audio_buffer.channels,
                bit_depth=audio_buffer.bit_depth,
                duration_seconds=audio_buffer.duration_seconds,
                format=audio_buffer.format
            )
            
        except Exception as e:
            raise AudioExtractionError(f"Failed to denoise audio: {str(e)}")
    
    @handle_errors("AUDIO_PREPROCESSING", log_traceback=True)
    def trim_silence(self, audio_buffer: AudioBuffer) -> AudioBuffer:
        """Trim silence from beginning and end of audio"""
        
        try:
            # Use first channel for silence detection
            if audio_buffer.channels > 1:
                samples = audio_buffer.samples[:, 0]
            else:
                samples = audio_buffer.samples.flatten()
            
            # Calculate RMS in windows
            window_size = 1024
            hop_size = 512
            
            rms_values = []
            for i in range(0, len(samples) - window_size, hop_size):
                window = samples[i:i + window_size]
                rms = np.sqrt(np.mean(window ** 2))
                rms_db = 20 * np.log10(rms + 1e-10)
                rms_values.append(rms_db)
            
            rms_values = np.array(rms_values)
            
            # Find silence threshold
            noise_floor_db = np.percentile(rms_values, 5)
            silence_threshold = noise_floor_db + 6  # 6dB above noise floor
            
            # Find start and end of non-silence
            non_silent_frames = np.where(rms_values > silence_threshold)[0]
            
            if len(non_silent_frames) == 0:
                # Entire file is silence
                return audio_buffer
            
            start_frame = non_silent_frames[0] * hop_size
            end_frame = (non_silent_frames[-1] + 1) * hop_size
            
            # Ensure we don't go out of bounds
            start_frame = max(0, start_frame)
            end_frame = min(len(samples), end_frame)
            
            # Trim all channels
            trimmed_samples = audio_buffer.samples[start_frame:end_frame]
            
            # Calculate new duration
            new_duration_seconds = len(trimmed_samples) / audio_buffer.sample_rate
            
            return AudioBuffer(
                samples=trimmed_samples,
                sample_rate=audio_buffer.sample_rate,
                channels=audio_buffer.channels,
                bit_depth=audio_buffer.bit_depth,
                duration_seconds=new_duration_seconds,
                format=audio_buffer.format
            )
            
        except Exception as e:
            raise AudioExtractionError(f"Failed to trim silence: {str(e)}")
    
    @handle_errors("AUDIO_PREPROCESSING", log_traceback=True)
    def apply_fade(self, audio_buffer: AudioBuffer, fade_type: str = 'linear', 
                   fade_in_samples: Optional[int] = None, fade_out_samples: Optional[int] = None) -> AudioBuffer:
        """Apply fade in/out to audio"""
        
        try:
            samples = audio_buffer.samples.copy()
            
            # Calculate fade durations if not provided
            fade_in_samples = fade_in_samples or int(audio_buffer.sample_rate * self.fade_duration_ms / 1000)
            fade_out_samples = fade_out_samples or int(audio_buffer.sample_rate * self.fade_duration_ms / 1000)
            
            # Ensure fade durations don't exceed audio length
            fade_in_samples = min(fade_in_samples, len(samples) // 2)
            fade_out_samples = min(fade_out_samples, len(samples) // 2)
            
            # Apply fade in
            if fade_type == 'linear':
                fade_in_curve = np.linspace(0, 1, fade_in_samples)
            elif fade_type == 'exponential':
                fade_in_curve = np.exp(np.linspace(-5, 0, fade_in_samples))
                fade_in_curve = fade_in_curve / np.max(fade_in_curve)
            elif fade_type == 'logarithmic':
                fade_in_curve = np.log10(np.linspace(1, 10, fade_in_samples))
                fade_in_curve = fade_in_curve / np.max(fade_in_curve)
            else:
                raise AudioExtractionError(f"Unknown fade type: {fade_type}")
            
            # Apply fade in to all channels
            for ch in range(audio_buffer.channels):
                samples[:fade_in_samples, ch] *= fade_in_curve
            
            # Apply fade out
            if fade_type == 'linear':
                fade_out_curve = np.linspace(1, 0, fade_out_samples)
            elif fade_type == 'exponential':
                fade_out_curve = np.exp(np.linspace(0, -5, fade_out_samples))
            elif fade_type == 'logarithmic':
                fade_out_curve = np.log10(np.linspace(10, 1, fade_out_samples))
                fade_out_curve = fade_out_curve / np.max(fade_out_curve)
            
            # Apply fade out to all channels
            for ch in range(audio_buffer.channels):
                samples[-fade_out_samples:, ch] *= fade_out_curve
            
            return AudioBuffer(
                samples=samples,
                sample_rate=audio_buffer.sample_rate,
                channels=audio_buffer.channels,
                bit_depth=audio_buffer.bit_depth,
                duration_seconds=audio_buffer.duration_seconds,
                format=audio_buffer.format
            )
            
        except Exception as e:
            raise AudioExtractionError(f"Failed to apply fade: {str(e)}")


# ============================================================================
# DECISION ENGINE - INTELLIGENT AUDIO PROCESSING DECISIONS
# ============================================================================

class DecisionEngine:
    """Google-level decision engine for optimal audio processing points"""
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        
        # Decision parameters
        self.min_segment_duration = self.config.get('min_segment_duration', 1.0)  # seconds
        self.max_segment_duration = self.config.get('max_segment_duration', 30.0)  # seconds
        self.energy_threshold = self.config.get('energy_threshold', 0.1)
        self.transient_weight = self.config.get('transient_weight', 0.3)
        self.energy_weight = self.config.get('energy_weight', 0.4)
        self.spectral_weight = self.config.get('spectral_weight', 0.3)
        
    @handle_errors("DECISION_ENGINE", log_traceback=True)
    def find_best_extraction_point(self, audio_buffer: AudioBuffer, 
                                  analysis: Optional[Dict[str, Any]] = None) -> ExtractionPoint:
        """Find optimal point for audio extraction"""
        
        try:
            # Get analysis if not provided
            if analysis is None:
                analysis = self._get_comprehensive_analysis(audio_buffer)
            
            # Calculate quality scores for each potential extraction point
            scores = []
            
            # Analyze in segments
            segment_samples = int(self.min_segment_duration * audio_buffer.sample_rate)
            
            for i in range(0, len(audio_buffer.samples) - segment_samples, segment_samples // 4):
                segment_end = min(i + segment_samples, len(audio_buffer.samples))
                segment = audio_buffer.samples[i:segment_end]
                
                # Calculate quality score for this segment
                score = self._calculate_segment_quality_score(segment, audio_buffer.sample_rate, analysis)
                
                scores.append({
                    'start_sample': i,
                    'score': score,
                    'reasoning': self._generate_score_reasoning(score, analysis)
                })
            
            # Find best segment
            if not scores:
                # Fallback to middle of audio
                best_sample = len(audio_buffer.samples) // 2
                reasoning = "No suitable segments found, using middle of audio"
            else:
                best_segment = max(scores, key=lambda x: x['score'])
                best_sample = best_segment['start_sample']
                reasoning = best_segment['reasoning']
            
            return ExtractionPoint(
                sample_index=best_sample,
                timestamp_ns=audio_buffer.nanosecond_timestamps[best_sample],
                confidence=min(1.0, max(scores, key=lambda x: x['score'])['score'] / 100 if scores else 0.5),
                reasoning=reasoning,
                surrounding_context={
                    'total_samples': len(audio_buffer.samples),
                    'sample_rate': audio_buffer.sample_rate,
                    'duration_seconds': audio_buffer.duration_seconds,
                    'segments_analyzed': len(scores)
                }
            )
            
        except Exception as e:
            raise AudioExtractionError(f"Failed to find extraction point: {str(e)}")
    
    @handle_errors("DECISION_ENGINE", log_traceback=True)
    def determine_optimal_fade_points(self, audio_buffer: AudioBuffer) -> FadePoints:
        """Determine optimal fade in/out points"""
        
        try:
            # Get comprehensive analysis
            analysis = self._get_comprehensive_analysis(audio_buffer)
            
            # Find best fade in point (early in audio with good energy)
            fade_in_point = self._find_optimal_fade_in_point(audio_buffer, analysis)
            
            # Find best fade out point (late in audio with good energy)
            fade_out_point = self._find_optimal_fade_out_point(audio_buffer, analysis)
            
            # Determine fade duration based on audio characteristics
            fade_duration_samples = self._calculate_optimal_fade_duration(audio_buffer, analysis)
            
            # Recommend fade curve based on content
            fade_curve = self._recommend_fade_curve(audio_buffer, analysis)
            
            return FadePoints(
                fade_in_point=fade_in_point,
                fade_out_point=fade_out_point,
                fade_duration_samples=fade_duration_samples,
                recommended_curve=fade_curve
            )
            
        except Exception as e:
            raise AudioExtractionError(f"Failed to determine fade points: {str(e)}")
    
    @handle_errors("DECISION_ENGINE", log_traceback=True)
    def recommend_processing_strategy(self, audio_buffer: AudioBuffer, 
                                     features: AudioFeatures) -> Dict[str, Any]:
        """Recommend optimal processing strategy based on audio characteristics"""
        
        try:
            strategy = {
                'normalization_method': 'peak',
                'denoising_needed': False,
                'resampling_needed': False,
                'target_sample_rate': audio_buffer.sample_rate,
                'quality_issues': [],
                'recommendations': []
            }
            
            # Analyze features for recommendations
            if features.rms_energy.size > 0:
                avg_rms = np.mean(features.rms_energy)
                max_rms = np.max(features.rms_energy)
                
                # Check if normalization is needed
                if max_rms < 0.5:
                    strategy['normalization_method'] = 'peak'
                    strategy['recommendations'].append("Low peak level detected, recommend peak normalization")
                elif avg_rms > 0.8:
                    strategy['normalization_method'] = 'rms'
                    strategy['recommendations'].append("High average level detected, recommend RMS normalization")
            
            # Check zero crossing rate for noise
            if features.zero_crossing_rate > 0.15:
                strategy['denoising_needed'] = True
                strategy['quality_issues'].append("High zero crossing rate suggests noise presence")
                strategy['recommendations'].append("Consider denoising to reduce noise")
            
            # Check spectral characteristics
            if features.spectral_centroid.size > 0:
                avg_centroid = np.mean(features.spectral_centroid)
                
                if avg_centroid < 2000:  # Low frequency content
                    strategy['recommendations'].append("Low frequency content detected, consider bass enhancement")
                elif avg_centroid > 8000:  # High frequency content
                    strategy['recommendations'].append("High frequency content detected, consider high-frequency enhancement")
            
            # Check sample rate
            if audio_buffer.sample_rate < 44100:
                strategy['resampling_needed'] = True
                strategy['target_sample_rate'] = 44100
                strategy['recommendations'].append("Low sample rate detected, recommend upsampling to 44.1kHz")
            
            # Check duration
            if audio_buffer.duration_seconds < 1.0:
                strategy['quality_issues'].append("Very short duration may limit analysis accuracy")
            elif audio_buffer.duration_seconds > 300:  # 5 minutes
                strategy['recommendations'].append("Long duration detected, consider segmenting for processing")
            
            return strategy
            
        except Exception as e:
            raise AudioExtractionError(f"Failed to recommend processing strategy: {str(e)}")
    
    @handle_errors("DECISION_ENGINE", log_traceback=True)
    def detect_audio_quality_issues(self, audio_buffer: AudioBuffer, 
                                    analysis: Optional[Dict[str, Any]] = None) -> List[QualityIssue]:
        """Detect audio quality issues with detailed analysis"""
        
        try:
            if analysis is None:
                analysis = self._get_comprehensive_analysis(audio_buffer)
            
            issues = []
            
            # Check for clipping
            if analysis.get('peak_dbfs', 0) > -0.1:
                issues.append(QualityIssue(
                    issue_type='clipping',
                    severity='high',
                    location=(0, len(audio_buffer.samples)),
                    description="Peak levels near or above 0 dBFS indicate clipping",
                    suggested_fix="Apply peak normalization or reduce gain",
                    confidence=0.9
                ))
            
            # Check for low signal level
            if analysis.get('rms_dbfs', -60) < -40:
                issues.append(QualityIssue(
                    issue_type='low_level',
                    severity='medium',
                    location=(0, len(audio_buffer.samples)),
                    description="Low RMS level may indicate weak signal",
                    suggested_fix="Apply normalization to increase level",
                    confidence=0.8
                ))
            
            # Check for excessive silence
            silence_ratio = analysis.get('silence_ratio', 0)
            if silence_ratio > 0.5:
                issues.append(QualityIssue(
                    issue_type='excessive_silence',
                    severity='medium',
                    location=(0, len(audio_buffer.samples)),
                    description=f"High silence ratio ({silence_ratio:.1%}) detected",
                    suggested_fix="Trim silence or check audio source",
                    confidence=0.7
                ))
            
            # Check for noise
            if analysis.get('zero_crossing_rate', 0) > 0.2:
                issues.append(QualityIssue(
                    issue_type='noise',
                    severity='medium',
                    location=(0, len(audio_buffer.samples)),
                    description="High zero crossing rate suggests noise presence",
                    suggested_fix="Apply denoising or check recording environment",
                    confidence=0.6
                ))
            
            # Check for frequency issues
            if 'spectral_centroid' in analysis:
                centroid = analysis['spectral_centroid']
                if centroid < 1000:
                    issues.append(QualityIssue(
                        issue_type='low_frequency_content',
                        severity='low',
                        location=(0, len(audio_buffer.samples)),
                        description="Low frequency content may lack clarity",
                        suggested_fix="Consider high-frequency enhancement",
                        confidence=0.5
                    ))
                elif centroid > 10000:
                    issues.append(QualityIssue(
                        issue_type='high_frequency_content',
                        severity='low',
                        location=(0, len(audio_buffer.samples)),
                        description="High frequency content may be harsh",
                        suggested_fix="Consider low-pass filtering",
                        confidence=0.5
                    ))
            
            return issues
            
        except Exception as e:
            raise AudioExtractionError(f"Failed to detect quality issues: {str(e)}")
    
    def _get_comprehensive_analysis(self, audio_buffer: AudioBuffer) -> Dict[str, Any]:
        """Get comprehensive audio analysis for decision making"""
        
        analysis = {}
        
        # Basic signal analysis
        analysis['rms'] = signal_analyzer.calculate_rms(audio_buffer)
        analysis['peak_dbfs'] = signal_analyzer.calculate_peak_dbfs(audio_buffer)
        
        # Spectral analysis
        spectral_data = signal_analyzer.analyze_spectrum(audio_buffer)
        analysis['spectral_centroid'] = np.mean(spectral_data.frequencies * spectral_data.magnitudes) / np.sum(spectral_data.magnitudes)
        
        # Envelope analysis
        envelope_data = signal_analyzer.extract_envelope(audio_buffer)
        analysis['envelope_peak'] = np.max(envelope_data.envelope)
        analysis['envelope_dynamic_range'] = np.max(envelope_data.envelope) - np.min(envelope_data.envelope)
        
        # Silence detection
        silence_regions = signal_analyzer.detect_silence(audio_buffer)
        total_silence_samples = sum(region.end_sample - region.start_sample for region in silence_regions)
        analysis['silence_ratio'] = total_silence_samples / len(audio_buffer.samples)
        
        # Transient detection
        transients = signal_analyzer.detect_transients(audio_buffer)
        analysis['transient_count'] = len(transients)
        analysis['transient_density'] = len(transients) / audio_buffer.duration_seconds
        
        # Zero crossing rate
        analysis['zero_crossing_rate'] = feature_extractor.extract_zero_crossing_rate(audio_buffer)
        
        # RMS in dBFS
        if len(analysis['rms']) > 0:
            analysis['rms_dbfs'] = 20 * np.log10(np.mean(analysis['rms']) + 1e-10)
        else:
            analysis['rms_dbfs'] = -60
        
        return analysis
    
    def _calculate_segment_quality_score(self, segment: np.ndarray, sample_rate: int, 
                                        analysis: Dict[str, Any]) -> float:
        """Calculate quality score for audio segment"""
        
        score = 0.0
        
        # Energy score (40% weight)
        segment_rms = np.sqrt(np.mean(segment ** 2))
        energy_score = min(100, segment_rms * 100)  # Normalize to 0-100
        score += energy_score * self.energy_weight
        
        # Transient score (30% weight)
        # Simple transient detection in segment
        diff = np.abs(np.diff(segment))
        transient_score = min(100, np.mean(diff) * 1000)
        score += transient_score * self.transient_weight
        
        # Spectral score (30% weight)
        # Simple spectral balance check
        if len(segment) > 1024:
            segment_fft = np.abs(fft(segment[:1024] * signal.get_window('hann', 1024)))
            spectral_balance = np.sum(segment_fft[:256]) / np.sum(segment_fft[256:])  # Low vs high frequency balance
            spectral_score = 100 - abs(spectral_balance - 1.0) * 50  # Prefer balanced spectrum
            score += spectral_score * self.spectral_weight
        
        return score
    
    def _generate_score_reasoning(self, score: float, analysis: Dict[str, Any]) -> str:
        """Generate reasoning for quality score"""
        
        if score > 80:
            return f"Excellent quality score ({score:.1f}/100) with good energy and spectral balance"
        elif score > 60:
            return f"Good quality score ({score:.1f}/100) with moderate characteristics"
        elif score > 40:
            return f"Fair quality score ({score:.1f}/100) with some limitations"
        else:
            return f"Poor quality score ({score:.1f}/100) with significant issues"
    
    def _find_optimal_fade_in_point(self, audio_buffer: AudioBuffer, analysis: Dict[str, Any]) -> ExtractionPoint:
        """Find optimal fade in point"""
        
        # Look for early segment with good energy
        search_samples = int(audio_buffer.sample_rate * 2)  # Search first 2 seconds
        best_sample = 0
        best_score = 0
        
        segment_size = int(audio_buffer.sample_rate * 0.1)  # 100ms segments
        
        for i in range(0, min(search_samples, len(audio_buffer.samples) - segment_size), segment_size // 2):
            segment = audio_buffer.samples[i:i + segment_size]
            score = self._calculate_segment_quality_score(segment, audio_buffer.sample_rate, analysis)
            
            if score > best_score:
                best_score = score
                best_sample = i
        
        return ExtractionPoint(
            sample_index=best_sample,
            timestamp_ns=audio_buffer.nanosecond_timestamps[best_sample],
            confidence=min(1.0, best_score / 100),
            reasoning=f"Optimal fade-in point with quality score {best_score:.1f}/100",
            surrounding_context={'search_duration': 2.0, 'best_score': best_score}
        )
    
    def _find_optimal_fade_out_point(self, audio_buffer: AudioBuffer, analysis: Dict[str, Any]) -> ExtractionPoint:
        """Find optimal fade out point"""
        
        # Look for late segment with good energy
        search_samples = int(audio_buffer.sample_rate * 2)  # Search last 2 seconds
        start_search = max(0, len(audio_buffer.samples) - search_samples)
        
        best_sample = len(audio_buffer.samples) - 1
        best_score = 0
        
        segment_size = int(audio_buffer.sample_rate * 0.1)  # 100ms segments
        
        for i in range(start_search, len(audio_buffer.samples) - segment_size, segment_size // 2):
            segment = audio_buffer.samples[i:i + segment_size]
            score = self._calculate_segment_quality_score(segment, audio_buffer.sample_rate, analysis)
            
            if score > best_score:
                best_score = score
                best_sample = i
        
        return ExtractionPoint(
            sample_index=best_sample,
            timestamp_ns=audio_buffer.nanosecond_timestamps[best_sample],
            confidence=min(1.0, best_score / 100),
            reasoning=f"Optimal fade-out point with quality score {best_score:.1f}/100",
            surrounding_context={'search_duration': 2.0, 'best_score': best_score}
        )
    
    def _calculate_optimal_fade_duration(self, audio_buffer: AudioBuffer, analysis: Dict[str, Any]) -> int:
        """Calculate optimal fade duration in samples"""
        
        # Base fade duration on tempo and characteristics
        base_duration_ms = self.fade_duration_ms
        
        # Adjust based on tempo (if available)
        if 'tempo' in analysis:
            tempo = analysis['tempo']
            if tempo > 120:
                base_duration_ms *= 0.8  # Shorter fade for fast tempo
            elif tempo < 60:
                base_duration_ms *= 1.2  # Longer fade for slow tempo
        
        # Adjust based on duration
        if audio_buffer.duration_seconds < 2:
            base_duration_ms *= 0.5  # Shorter fade for short audio
        elif audio_buffer.duration_seconds > 10:
            base_duration_ms *= 1.5  # Longer fade for long audio
        
        return int(base_duration_ms * audio_buffer.sample_rate / 1000)
    
    def _recommend_fade_curve(self, audio_buffer: AudioBuffer, analysis: Dict[str, Any]) -> str:
        """Recommend optimal fade curve type"""
        
        # Analyze content characteristics
        if analysis.get('transient_density', 0) > 10:
            return 'exponential'  # Smooth fade for percussive content
        elif analysis.get('spectral_centroid', 4000) < 2000:
            return 'logarithmic'  # Gentle fade for bass-heavy content
        else:
            return 'linear'  # Standard fade for general content


# Global instances for preprocessing and decision engine
audio_preprocessor = AudioPreprocessor()
decision_engine = DecisionEngine()

