class AudioExtractor:
    """Google-level audio extractor with nanosecond precision, full observability, and production readiness"""
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        
        # Initialize all components
        self.audio_io = audio_io_handler
        self.preprocessor = audio_preprocessor
        self.signal_analyzer = signal_analyzer
        self.feature_extractor = feature_extractor
        self.timing_analyzer = nanosecond_timing_analyzer
        self.decision_engine = decision_engine
        
        # Production pipeline integration
        self.production_pipeline = production_pipeline
        
        # Performance tracking
        self.extraction_stats = {
            'total_extractions': 0,
            'successful_extractions': 0,
            'failed_extractions': 0,
            'average_processing_time_ms': 0,
            'total_processing_time_ms': 0,
            'files_processed': [],
            'quality_issues_detected': 0,
            'preprocessing_applied': 0
        }
        
        # Configuration
        self.enable_streaming = self.config.get('enable_streaming', True)
        self.enable_preprocessing = self.config.get('enable_preprocessing', True)
        self.enable_feature_extraction = self.config.get('enable_feature_extraction', True)
        self.enable_timing_analysis = self.config.get('enable_timing_analysis', True)
        self.enable_decision_engine = self.config.get('enable_decision_engine', True)
        
        enhanced_logger.info("Google-level AudioExtractor initialized with all components")
    
    @handle_errors("AUDIO_EXTRACTOR", log_traceback=True)
    async def process_file(self, file_path: str, 
                          output_path: Optional[str] = None,
                          processing_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Process audio file with Google-level analysis and extraction"""
        
        extraction_start = time.time()
        
        try:
            # Validate file format
            format_validation = self.audio_io.validate_format_support(file_path)
            if not format_validation['supported']:
                return {
                    'success': False,
                    'error': f"Unsupported format: {format_validation['reason']}",
                    'file_path': file_path
                }
            
            # Read audio file
            audio_buffer, metadata = self.audio_io.read_audio_file(file_path)
            
            # Process with streaming if enabled and file is large
            if self.enable_streaming and audio_buffer.duration_seconds > 60:  # Stream files > 1 minute
                return await self._process_streaming(file_path, audio_buffer, metadata, processing_options)
            else:
                return await self._process_standard(audio_buffer, metadata, processing_options)
            
        except Exception as e:
            # Update failure statistics
            self.extraction_stats['failed_extractions'] += 1
            processing_time = (time.time() - extraction_start) * 1000
            self._update_processing_stats(processing_time)
            
            enhanced_logger.error(f"Audio extraction failed: {str(e)}")
            enhanced_logger.error(f"Full traceback: {traceback.format_exc()}")
            
            return {
                'success': False,
                'error': str(e),
                'error_type': type(e).__name__,
                'file_path': file_path,
                'processing_time_ms': processing_time
            }
    
    async def _process_standard(self, audio_buffer: AudioBuffer, 
                               metadata: AudioMetadata,
                               processing_options: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        """Standard processing for smaller files"""
        
        results = {
            'success': True,
            'method': 'standard',
            'file_path': metadata.file_path,
            'metadata': asdict(metadata),
            'processing_steps': [],
            'analysis_results': {},
            'features': {},
            'timing_analysis': {},
            'decisions': {},
            'quality_issues': [],
            'preprocessing_applied': [],
            'performance_metrics': {}
        }
        
        # Step 1: Signal Analysis
        if self.enable_timing_analysis or self.enable_decision_engine:
            analysis_start = time.time()
            
            # Basic signal analysis
            rms = self.signal_analyzer.calculate_rms(audio_buffer)
            peak_dbfs = self.signal_analyzer.calculate_peak_dbfs(audio_buffer)
            spectral_data = self.signal_analyzer.analyze_spectrum(audio_buffer)
            envelope_data = self.signal_analyzer.extract_envelope(audio_buffer)
            transients = self.signal_analyzer.detect_transients(audio_buffer)
            silence_regions = self.signal_analyzer.detect_silence(audio_buffer)
            
            results['analysis_results'] = {
                'rms': rms.tolist() if hasattr(rms, 'tolist') else rms,
                'peak_dbfs': peak_dbfs.tolist() if hasattr(peak_dbfs, 'tolist') else peak_dbfs,
                'spectral_data': {
                    'peak_frequency': float(spectral_data.frequencies[np.argmax(spectral_data.magnitudes)]),
                    'spectral_centroid': float(np.mean(spectral_data.frequencies * spectral_data.magnitudes) / np.sum(spectral_data.magnitudes)),
                    'fft_size': spectral_data.fft_size
                },
                'envelope': {
                    'peak': float(envelope_data.envelope_peak),
                    'sustain_level': float(envelope_data.sustain_level),
                    'attack_count': len(envelope_data.attack_times),
                    'decay_count': len(envelope_data.decay_times)
                },
                'transients': {
                    'count': len(transients),
                    'density': len(transients) / audio_buffer.duration_seconds,
                    'average_confidence': np.mean([t.confidence for t in transients]) if transients else 0
                },
                'silence': {
                    'regions': len(silence_regions),
                    'total_duration': sum(r.duration_seconds for r in silence_regions),
                    'ratio': sum(r.end_sample - r.start_sample for r in silence_regions) / len(audio_buffer.samples)
                }
            }
            
            analysis_time = (time.time() - analysis_start) * 1000
            results['performance_metrics']['signal_analysis_ms'] = analysis_time
            results['processing_steps'].append('signal_analysis')
        
        # Step 2: Nanosecond Timing Analysis
        if self.enable_timing_analysis:
            timing_start = time.time()
            
            timing_report = self.timing_analyzer.get_timing_report(audio_buffer)
            results['timing_analysis'] = timing_report
            
            timing_time = (time.time() - timing_start) * 1000
            results['performance_metrics']['timing_analysis_ms'] = timing_time
            results['processing_steps'].append('timing_analysis')
        
        # Step 3: Feature Extraction
        if self.enable_feature_extraction:
            features_start = time.time()
            
            features = self.feature_extractor.extract_all_features(audio_buffer)
            feature_stats = self.feature_extractor.get_feature_statistics(features)
            
            results['features'] = {
                'mfcc_shape': features.mfcc.shape,
                'chroma_shape': features.chroma.shape,
                'spectral_centroid_mean': float(np.mean(features.spectral_centroid)) if features.spectral_centroid.size > 0 else 0,
                'zero_crossing_rate': features.zero_crossing_rate,
                'rms_energy_mean': float(np.mean(features.rms_energy)) if features.rms_energy.size > 0 else 0,
                'statistics': feature_stats
            }
            
            features_time = (time.time() - features_start) * 1000
            results['performance_metrics']['feature_extraction_ms'] = features_time
            results['processing_steps'].append('feature_extraction')
        
        # Step 4: Quality Issue Detection
        quality_start = time.time()
        
        quality_issues = self.decision_engine.detect_audio_quality_issues(audio_buffer, results['analysis_results'])
        results['quality_issues'] = [
            {
                'type': issue.issue_type,
                'severity': issue.severity,
                'description': issue.description,
                'suggested_fix': issue.suggested_fix,
                'confidence': issue.confidence
            }
            for issue in quality_issues
        ]
        
        quality_time = (time.time() - quality_start) * 1000
        results['performance_metrics']['quality_analysis_ms'] = quality_time
        results['processing_steps'].append('quality_analysis')
        
        # Step 5: Decision Engine
        if self.enable_decision_engine:
            decision_start = time.time()
            
            # Get features for decision engine
            if self.enable_feature_extraction:
                features = self.feature_extractor.extract_all_features(audio_buffer)
            else:
                features = AudioFeatures(
                    mfcc=np.array([]), chroma=np.array([]), spectral_centroid=np.array([]),
                    spectral_bandwidth=np.array([]), spectral_rolloff=np.array([]),
                    zero_crossing_rate=0, rms_energy=np.array([]),
                    spectral_contrast=np.array([]), tonnetz=np.array([]), tempogram=np.array([])
                )
            
            # Get processing recommendations
            strategy = self.decision_engine.recommend_processing_strategy(audio_buffer, features)
            results['decisions'] = {
                'processing_strategy': strategy,
                'extraction_point': asdict(self.decision_engine.find_best_extraction_point(audio_buffer)),
                'fade_points': asdict(self.decision_engine.determine_optimal_fade_points(audio_buffer))
            }
            
            decision_time = (time.time() - decision_start) * 1000
            results['performance_metrics']['decision_engine_ms'] = decision_time
            results['processing_steps'].append('decision_engine')
        
        # Step 6: Preprocessing (if needed)
        if self.enable_preprocessing:
            preprocessing_start = time.time()
            processed_buffer = audio_buffer
            
            # Apply recommended preprocessing
            if strategy.get('resampling_needed', False):
                processed_buffer = self.preprocessor.resample(processed_buffer, strategy['target_sample_rate'])
                results['preprocessing_applied'].append('resampling')
            
            if strategy.get('denoising_needed', False):
                processed_buffer = self.preprocessor.denoise(processed_buffer)
                results['preprocessing_applied'].append('denoising')
            
            if strategy.get('normalization_method'):
                processed_buffer = self.preprocessor.normalize(processed_buffer, strategy['normalization_method'])
                results['preprocessing_applied'].append(f"normalization_{strategy['normalization_method']}")
            
            # Update audio buffer reference
            audio_buffer = processed_buffer
            preprocessing_time = (time.time() - preprocessing_start) * 1000
            results['performance_metrics']['preprocessing_ms'] = preprocessing_time
            results['processing_steps'].append('preprocessing')
        
        # Calculate total processing time
        total_time = sum(results['performance_metrics'].values())
        results['performance_metrics']['total_processing_time_ms'] = total_time
        
        # Update statistics
        self.extraction_stats['successful_extractions'] += 1
        self.extraction_stats['total_processing_time_ms'] += total_time
        self.extraction_stats['files_processed'].append(metadata.file_path)
        self.extraction_stats['quality_issues_detected'] += len(results['quality_issues'])
        if results['preprocessing_applied']:
            self.extraction_stats['preprocessing_applied'] += 1
        
        return results
    
    async def _process_streaming(self, file_path: str, audio_buffer: AudioBuffer,
                                metadata: AudioMetadata,
                                processing_options: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        """Streaming processing for large files"""
        
        results = {
            'success': True,
            'method': 'streaming',
            'file_path': file_path,
            'metadata': asdict(metadata),
            'chunks_processed': 0,
            'total_chunks': 0,
            'chunk_results': [],
            'aggregated_analysis': {},
            'performance_metrics': {}
        }
        
        # Calculate chunk size
        chunk_size = processing_options.get('chunk_size', 1024 * 64) if processing_options else 1024 * 64
        total_chunks = (len(audio_buffer.samples) + chunk_size - 1) // chunk_size
        results['total_chunks'] = total_chunks
        
        # Process chunks
        chunk_start = time.time()
        
        async for chunk_buffer in self.audio_io.stream_audio(file_path, chunk_size):
            chunk_result = await self._process_chunk(chunk_buffer, len(results['chunk_results']))
            results['chunk_results'].append(chunk_result)
            results['chunks_processed'] += 1
            
            # Small delay to prevent overwhelming
            await asyncio.sleep(0.001)
        
        # Aggregate results
        results['performance_metrics']['total_streaming_time_ms'] = (time.time() - chunk_start) * 1000
        results['performance_metrics']['average_chunk_time_ms'] = results['performance_metrics']['total_streaming_time_ms'] / total_chunks
        
        # Update statistics
        self.extraction_stats['successful_extractions'] += 1
        self.extraction_stats['files_processed'].append(file_path)
        
        return results
    
    async def _process_chunk(self, chunk_buffer: AudioBuffer, chunk_index: int) -> Dict[str, Any]:
        """Process individual chunk"""
        
        chunk_start = time.time()
        
        # Basic analysis for chunk
        rms = self.signal_analyzer.calculate_rms(chunk_buffer)
        peak_dbfs = self.signal_analyzer.calculate_peak_dbfs(chunk_buffer)
        
        # Feature extraction for chunk (simplified)
        zcr = self.feature_extractor.extract_zero_crossing_rate(chunk_buffer)
        
        return {
            'chunk_index': chunk_index,
            'duration_seconds': chunk_buffer.duration_seconds,
            'sample_count': len(chunk_buffer.samples),
            'rms': rms.tolist() if hasattr(rms, 'tolist') else rms,
            'peak_dbfs': peak_dbfs.tolist() if hasattr(peak_dbfs, 'tolist') else peak_dbfs,
            'zero_crossing_rate': zcr,
            'processing_time_ms': (time.time() - chunk_start) * 1000
        }
    
    @handle_errors("AUDIO_EXTRACTOR", log_traceback=True)
    def extract_audio_segment(self, file_path: str, 
                             start_seconds: float,
                             duration_seconds: float,
                             output_path: str) -> Dict[str, Any]:
        """Extract specific audio segment with nanosecond precision"""
        
        try:
            # Read audio file
            audio_buffer, metadata = self.audio_io.read_audio_file(file_path)
            
            # Calculate sample indices
            start_sample = int(start_seconds * audio_buffer.sample_rate)
            end_sample = int((start_seconds + duration_seconds) * audio_buffer.sample_rate)
            
            # Validate bounds
            if start_sample >= len(audio_buffer.samples):
                return {
                    'success': False,
                    'error': f"Start time {start_seconds}s exceeds audio duration {audio_buffer.duration_seconds}s"
                }
            
            if end_sample > len(audio_buffer.samples):
                end_sample = len(audio_buffer.samples)
                actual_duration = (end_sample - start_sample) / audio_buffer.sample_rate
            else:
                actual_duration = duration_seconds
            
            # Extract segment
            segment_samples = audio_buffer.samples[start_sample:end_sample]
            
            # Create new audio buffer
            segment_buffer = AudioBuffer(
                samples=segment_samples,
                sample_rate=audio_buffer.sample_rate,
                channels=audio_buffer.channels,
                bit_depth=audio_buffer.bit_depth,
                duration_seconds=actual_duration,
                nanosecond_timestamps=audio_buffer.nanosecond_timestamps[start_sample:end_sample],
                format=audio_buffer.format
            )
            
            # Write segment
            success = self.audio_io.write_audio_file(segment_buffer, output_path)
            
            return {
                'success': success,
                'file_path': output_path,
                'original_file': file_path,
                'start_seconds': start_seconds,
                'duration_seconds': actual_duration,
                'start_sample': start_sample,
                'end_sample': end_sample,
                'sample_count': len(segment_samples),
                'sample_rate': audio_buffer.sample_rate,
                'channels': audio_buffer.channels
            }
            
        except Exception as e:
            enhanced_logger.error(f"Audio segment extraction failed: {str(e)}")
            enhanced_logger.error(f"Full traceback: {traceback.format_exc()}")
            
            return {
                'success': False,
                'error': str(e),
                'error_type': type(e).__name__,
                'file_path': file_path,
                'start_seconds': start_seconds,
                'duration_seconds': duration_seconds
            }
    
    def get_extraction_statistics(self) -> Dict[str, Any]:
        """Get comprehensive extraction statistics"""
        
        stats = self.extraction_stats.copy()
        
        # Calculate averages
        if stats['total_extractions'] > 0:
            stats['success_rate'] = stats['successful_extractions'] / stats['total_extractions']
            stats['failure_rate'] = stats['failed_extractions'] / stats['total_extractions']
            stats['average_processing_time_ms'] = stats['total_processing_time_ms'] / stats['total_extractions']
        else:
            stats['success_rate'] = 0.0
            stats['failure_rate'] = 0.0
            stats['average_processing_time_ms'] = 0.0
        
        # Add component status
        stats['component_status'] = {
            'audio_io': 'active',
            'preprocessor': 'active',
            'signal_analyzer': 'active',
            'feature_extractor': 'active',
            'timing_analyzer': 'active',
            'decision_engine': 'active',
            'production_pipeline': 'active'
        }
        
        return stats
    
    def _update_processing_stats(self, processing_time_ms: float) -> None:
        """Update processing statistics"""
        
        self.extraction_stats['total_extractions'] += 1
        self.extraction_stats['total_processing_time_ms'] += processing_time_ms
        
        # Calculate average
        if self.extraction_stats['total_extractions'] > 0:
            self.extraction_stats['average_processing_time_ms'] = (
                self.extraction_stats['total_processing_time_ms'] / self.extraction_stats['total_extractions']
            )
    
    @handle_errors("AUDIO_EXTRACTOR", log_traceback=True)
    async def batch_process_files(self, file_paths: List[str],
                                 output_directory: str,
                                 processing_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Batch process multiple audio files"""
        
        batch_start = time.time()
        results = {
            'success': True,
            'total_files': len(file_paths),
            'successful_files': 0,
            'failed_files': 0,
            'file_results': [],
            'batch_performance': {},
            'errors': []
        }
        
        # Process files in parallel with semaphore control
        semaphore = asyncio.Semaphore(4)  # Process up to 4 files concurrently
        
        async def process_single_file(file_path: str):
            async with semaphore:
                try:
                    # Generate output path
                    file_path_obj = Path(file_path)
                    output_path = Path(output_directory) / f"processed_{file_path_obj.stem}.wav"
                    
                    # Process file
                    result = await self.process_file(str(file_path), str(output_path), processing_options)
                    
                    if result['success']:
                        results['successful_files'] += 1
                    else:
                        results['failed_files'] += 1
                        results['errors'].append(f"{file_path}: {result.get('error', 'Unknown error')}")
                    
                    return result
                    
                except Exception as e:
                    results['failed_files'] += 1
                    results['errors'].append(f"{file_path}: {str(e)}")
                    return {
                        'success': False,
                        'file_path': file_path,
                        'error': str(e),
                        'error_type': type(e).__name__
                    }
        
        # Process all files
        tasks = [process_single_file(file_path) for file_path in file_paths]
        file_results = await asyncio.gather(*tasks, return_exceptions=True)
        
        # Process results
        for result in file_results:
            if isinstance(result, Exception):
                results['failed_files'] += 1
                results['errors'].append(f"Exception: {str(result)}")
            else:
                results['file_results'].append(result)
        
        # Calculate batch performance
        batch_time = (time.time() - batch_start) * 1000
        results['batch_performance'] = {
            'total_batch_time_ms': batch_time,
            'average_time_per_file_ms': batch_time / len(file_paths),
            'files_per_second': len(file_paths) / (batch_time / 1000),
            'success_rate': results['successful_files'] / len(file_paths)
        }
        
        return results


