# GOOGLE-LEVEL: FFMPEG PATH CONFIGURATION
# ============================================================================

class FFmpegPathManager:
    """Configurable FFmpeg binary path management with validation"""
    
    def __init__(self):
        # Load configurable FFmpeg paths with validation
        self.ffmpeg_path = self._get_validated_ffmpeg_path(
            'AUDIO_EXTRACTOR_FFMPEG_PATH', 
            'ffmpeg',
            required=True
        )
        
        self.ffprobe_path = self._get_validated_ffmpeg_path(
            'AUDIO_EXTRACTOR_FFPROBE_PATH', 
            'ffprobe',
            required=True
        )
        
        # Optional additional tools
        self.ffmpeg_filters_path = self._get_validated_ffmpeg_path(
            'AUDIO_EXTRACTOR_FFMPEG_FILTERS_PATH', 
            None,
            required=False
        )
        
        # Path validation cache
        self._validated_paths = {}
        self._path_validation_cache_ttl = 300  # 5 minutes
        
        logger.info(f"FFmpeg paths configured: ffmpeg={self.ffmpeg_path}, ffprobe={self.ffprobe_path}")
    
    def _get_validated_ffmpeg_path(self, env_var: str, default: Optional[str], required: bool = True) -> Optional[Path]:
        """Get and validate FFmpeg binary path"""
        try:
            # Get path from environment or default
            path_str = EnvironmentParser.get_env_var(env_var, default, required=required)
            
            if not path_str:
                if required:
                    raise ValueError(f"Required FFmpeg path not specified for {env_var}")
                return None
            
            # Convert to Path object
            ffmpeg_path = Path(path_str)
            
            # Validate path exists and is executable
            if not ffmpeg_path.exists():
                # Try to find in system PATH
                system_path = self._find_in_system_path(ffmpeg_path.name)
                if system_path:
                    ffmpeg_path = system_path
                    logger.info(f"Found {ffmpeg_path.name} in system PATH: {ffmpeg_path}")
                else:
                    raise FileNotFoundError(f"FFmpeg binary not found: {ffmpeg_path}")
            
            # Validate it's executable
            if not ffmpeg_path.is_file():
                raise ValueError(f"FFmpeg path is not a file: {ffmpeg_path}")
            
            # Check if executable (Unix-like systems)
            if os.name != 'nt':  # Not Windows
                if not os.access(ffmpeg_path, os.X_OK):
                    raise PermissionError(f"FFmpeg binary is not executable: {ffmpeg_path}")
            
            # Validate it's actually FFmpeg/FFprobe
            self._validate_ffmpeg_binary(ffmpeg_path, ffmpeg_path.name)
            
            # Cache validation result
            self._validated_paths[str(ffmpeg_path)] = {
                'validated_at': time.time(),
                'path': ffmpeg_path,
                'version': self._get_ffmpeg_version(ffmpeg_path)
            }
            
            return ffmpeg_path
            
        except Exception as e:
            error_msg = f"Failed to configure FFmpeg path for {env_var}: {e}"
            if required:
                logger.error(error_msg)
                raise
            else:
                logger.warning(error_msg)
                return None
    
    def _find_in_system_path(self, binary_name: str) -> Optional[Path]:
        """Find binary in system PATH"""
        try:
            # Use shutil.which to find binary in PATH
            import shutil
            system_path = shutil.which(binary_name)
            if system_path:
                return Path(system_path)
        except Exception:
            pass
        
        return None
    
    def _validate_ffmpeg_binary(self, binary_path: Path, binary_name: str) -> None:
        """Validate that the binary is actually FFmpeg/FFprobe"""
        try:
            # Run version check to validate binary
            result = subprocess.run(
                [str(binary_path), '-version'],
                capture_output=True,
                text=True,
                timeout=10
            )
            
            if result.returncode != 0:
                raise ValueError(f"Binary failed version check: {binary_path}")
            
            # Check output contains expected FFmpeg/FFprobe identifiers
            output = result.stdout.lower()
            
            if 'ffmpeg' in binary_name.lower():
                if 'ffmpeg' not in output:
                    raise ValueError(f"Binary does not appear to be FFmpeg: {binary_path}")
            elif 'ffprobe' in binary_name.lower():
                if 'ffprobe' not in output:
                    raise ValueError(f"Binary does not appear to be FFprobe: {binary_path}")
            
        except subprocess.TimeoutExpired:
            raise ValueError(f"Binary validation timeout: {binary_path}")
        except Exception as e:
            raise ValueError(f"Binary validation failed: {e}")
    
    def _get_ffmpeg_version(self, binary_path: Path) -> str:
        """Get FFmpeg version string"""
        try:
            result = subprocess.run(
                [str(binary_path), '-version'],
                capture_output=True,
                text=True,
                timeout=10
            )
            
            if result.returncode == 0:
                # Extract version from first line
                first_line = result.stdout.split('\n')[0]
                return first_line.strip()
            
        except Exception:
            pass
        
        return "unknown"
    
    def get_ffmpeg_path(self) -> Path:
        """Get validated FFmpeg path"""
        return self.ffmpeg_path
    
    def get_ffprobe_path(self) -> Path:
        """Get validated FFprobe path"""
        return self.ffprobe_path
    
    def get_ffmpeg_filters_path(self) -> Optional[Path]:
        """Get optional FFmpeg filters path"""
        return self.ffmpeg_filters_path
    
    def validate_paths(self) -> Dict[str, Any]:
        """Validate all configured paths"""
        validation_results = {
            'ffmpeg': self._validate_single_path(self.ffmpeg_path, 'ffmpeg'),
            'ffprobe': self._validate_single_path(self.ffprobe_path, 'ffprobe'),
            'ffmpeg_filters': self._validate_single_path(self.ffmpeg_filters_path, 'ffmpeg_filters') if self.ffmpeg_filters_path else {'valid': True, 'message': 'Not configured'}
        }
        
        # Overall status
        all_valid = all(result['valid'] for result in validation_results.values())
        validation_results['overall_valid'] = all_valid
        
        return validation_results
    
    def _validate_single_path(self, path: Optional[Path], path_type: str) -> Dict[str, Any]:
        """Validate a single path"""
        if not path:
            return {'valid': False, 'message': f'{path_type} path is None'}
        
        try:
            # Check cache
            cache_key = str(path)
            if cache_key in self._validated_paths:
                cached = self._validated_paths[cache_key]
                if time.time() - cached['validated_at'] < self._path_validation_cache_ttl:
                    return {'valid': True, 'message': f'Cached validation for {path_type}', 'version': cached['version']}
            
            # Re-validate
            self._validate_ffmpeg_binary(path, path_type)
            version = self._get_ffmpeg_version(path)
            
            # Update cache
            self._validated_paths[cache_key] = {
                'validated_at': time.time(),
                'path': path,
                'version': version
            }
            
            return {'valid': True, 'message': f'{path_type} path valid', 'version': version}
            
        except Exception as e:
            return {'valid': False, 'message': f'{path_type} validation failed: {e}'}
    
    def get_path_info(self) -> Dict[str, Any]:
        """Get comprehensive path information"""
        return {
            'ffmpeg_path': str(self.ffmpeg_path),
            'ffprobe_path': str(self.ffprobe_path),
            'ffmpeg_filters_path': str(self.ffmpeg_filters_path) if self.ffmpeg_filters_path else None,
            'validation_results': self.validate_paths(),
            'cache_size': len(self._validated_paths),
            'cache_ttl': self._path_validation_cache_ttl
        }

