# ============================================================================
# GOOGLE-LEVEL: JSON SERIALIZATION SAFETY
# ============================================================================

class JSONSerializationError(Exception):
    """Raised when JSON serialization safety check fails"""
    pass

class JSONSerializationSafety:
    """Safe JSON serialization for platform-specific data with security controls"""
    
    def __init__(self):
        # Serialization safety configuration
        self.safety_config = {
            'max_depth': 100,           # Maximum nesting depth
            'max_string_length': 10000, # Maximum string length
            'max_object_size': 1000000, # Maximum object size (1MB)
            'max_array_length': 10000,  # Maximum array length
            'allowed_types': [str, int, float, bool, type(None), dict, list],
            'forbidden_keys': ['__import__', '__builtins__', 'eval', 'exec', 'open', 'file'],
            'sanitize_strings': True,    # Sanitize string content
            'validate_utf8': True,       # Validate UTF-8 encoding
            'prevent_injection': True   # Prevent code injection
        }
        
        # Serialization statistics
        self.serialization_stats = {
            'total_serializations': 0,
            'successful_serializations': 0,
            'failed_serializations': 0,
            'sanitized_objects': 0,
            'blocked_objects': 0,
            'size_violations': 0,
            'depth_violations': 0,
            'type_violations': 0
        }
    
    def safe_serialize_json(self, 
                          data: Any, 
                          context: Optional[Dict[str, Any]] = None,
                          platform: Optional[str] = None) -> Dict[str, Any]:
        """Safely serialize data to JSON with comprehensive security checks
        
        Args:
            data: Data to serialize
            context: Additional context for serialization
            platform: Platform name for platform-specific rules
            
        Returns:
            Serialization result with JSON string and safety metadata
        """
        serialization_result = {
            'timestamp': datetime.utcnow().isoformat(),
            'platform': platform,
            'status': 'passed',
            'severity': 'info',
            'json_string': None,
            'errors': [],
            'warnings': [],
            'safety_checks': {},
            'metadata': {},
            'context': context or {}
        }
        
        # Update statistics
        self.serialization_stats['total_serializations'] += 1
        
        try:
            # Pre-serialization safety checks
            safety_result = self._perform_safety_checks(data, platform)
            serialization_result['safety_checks'] = safety_result
            
            if not safety_result['passed']:
                serialization_result['status'] = 'blocked'
                serialization_result['severity'] = 'error'
                serialization_result['errors'].extend(safety_result['errors'])
                self.serialization_stats['blocked_objects'] += 1
                return serialization_result
            
            # Sanitize data if needed
            sanitized_data = self._sanitize_data(data, platform)
            if sanitized_data != data:
                serialization_result['warnings'].append("Data sanitized for safety")
                self.serialization_stats['sanitized_objects'] += 1
            
            # Perform serialization
            json_string = json.dumps(sanitized_data, 
                                     ensure_ascii=False,
                                     separators=(',', ':'),
                                     sort_keys=True,
                                     default=self._json_serializer_default)
            
            # Post-serialization validation
            post_result = self._validate_serialized_json(json_string)
            serialization_result['metadata'].update(post_result)
            
            if not post_result['passed']:
                serialization_result['status'] = 'failed'
                serialization_result['severity'] = 'error'
                serialization_result['errors'].extend(post_result['errors'])
                self.serialization_stats['failed_serializations'] += 1
                return serialization_result
            
            # Success
            serialization_result['json_string'] = json_string
            serialization_result['metadata']['serialized_size'] = len(json_string.encode('utf-8'))
            self.serialization_stats['successful_serializations'] += 1
            
        except Exception as e:
            serialization_result['status'] = 'error'
            serialization_result['severity'] = 'error'
            serialization_result['errors'].append(f"Serialization error: {e}")
            self.serialization_stats['failed_serializations'] += 1
        
        return serialization_result
    
    def safe_deserialize_json(self, 
                            json_string: str, 
                            context: Optional[Dict[str, Any]] = None,
                            platform: Optional[str] = None) -> Dict[str, Any]:
        """Safely deserialize JSON string with security validation
        
        Args:
            json_string: JSON string to deserialize
            context: Additional context for deserialization
            platform: Platform name for platform-specific rules
            
        Returns:
            Deserialization result with parsed data and safety metadata
        """
        deserialization_result = {
            'timestamp': datetime.utcnow().isoformat(),
            'platform': platform,
            'status': 'passed',
            'severity': 'info',
            'data': None,
            'errors': [],
            'warnings': [],
            'safety_checks': {},
            'metadata': {},
            'context': context or {}
        }
        
        try:
            # Pre-deserialization validation
            validation_result = self._validate_json_string(json_string)
            deserialization_result['safety_checks'] = validation_result
            
            if not validation_result['passed']:
                deserialization_result['status'] = 'blocked'
                deserialization_result['severity'] = 'error'
                deserialization_result['errors'].extend(validation_result['errors'])
                return deserialization_result
            
            # Perform deserialization
            data = json.loads(json_string, object_hook=self._json_deserializer_object_hook)
            
            # Post-deserialization safety checks
            post_result = self._perform_safety_checks(data, platform)
            deserialization_result['metadata'].update(post_result)
            
            if not post_result['passed']:
                deserialization_result['status'] = 'blocked'
                deserialization_result['severity'] = 'error'
                deserialization_result['errors'].extend(post_result['errors'])
                return deserialization_result
            
            # Success
            deserialization_result['data'] = data
            deserialization_result['metadata']['deserialized_size'] = len(json_string)
            
        except json.JSONDecodeError as e:
            deserialization_result['status'] = 'failed'
            deserialization_result['severity'] = 'error'
            deserialization_result['errors'].append(f"JSON decode error: {e}")
        except Exception as e:
            deserialization_result['status'] = 'error'
            deserialization_result['severity'] = 'error'
            deserialization_result['errors'].append(f"Deserialization error: {e}")
        
        return deserialization_result
    
    def _perform_safety_checks(self, data: Any, platform: Optional[str] = None) -> Dict[str, Any]:
        """Perform comprehensive safety checks on data"""
        result = {
            'passed': True,
            'errors': [],
            'warnings': [],
            'checks': {}
        }
        
        # Depth check
        depth_result = self._check_depth(data)
        result['checks']['depth'] = depth_result
        if not depth_result['passed']:
            result['passed'] = False
            result['errors'].extend(depth_result['errors'])
            self.serialization_stats['depth_violations'] += 1
        
        # Size check
        size_result = self._check_size(data)
        result['checks']['size'] = size_result
        if not size_result['passed']:
            result['passed'] = False
            result['errors'].extend(size_result['errors'])
            self.serialization_stats['size_violations'] += 1
        
        # Type check
        type_result = self._check_types(data)
        result['checks']['types'] = type_result
        if not type_result['passed']:
            result['passed'] = False
            result['errors'].extend(type_result['errors'])
            self.serialization_stats['type_violations'] += 1
        
        # Key check
        key_result = self._check_keys(data)
        result['checks']['keys'] = key_result
        if not key_result['passed']:
            result['passed'] = False
            result['errors'].extend(key_result['errors'])
        
        # Platform-specific checks
        if platform:
            platform_result = self._check_platform_specific(data, platform)
            result['checks']['platform_specific'] = platform_result
            if not platform_result['passed']:
                result['passed'] = False
                result['errors'].extend(platform_result['errors'])
        
        return result
    
    def _check_depth(self, data: Any, current_depth: int = 0) -> Dict[str, Any]:
        """Check maximum nesting depth"""
        result = {'passed': True, 'errors': [], 'max_depth': current_depth}
        
        if current_depth > self.safety_config['max_depth']:
            result['passed'] = False
            result['errors'].append(f"Maximum depth exceeded: {current_depth} > {self.safety_config['max_depth']}")
            return result
        
        if isinstance(data, dict):
            for value in data.values():
                if isinstance(value, (dict, list)):
                    sub_result = self._check_depth(value, current_depth + 1)
                    if not sub_result['passed']:
                        return sub_result
                    result['max_depth'] = max(result['max_depth'], sub_result['max_depth'])
        elif isinstance(data, list):
            for item in data:
                if isinstance(item, (dict, list)):
                    sub_result = self._check_depth(item, current_depth + 1)
                    if not sub_result['passed']:
                        return sub_result
                    result['max_depth'] = max(result['max_depth'], sub_result['max_depth'])
        
        return result
    
    def _check_size(self, data: Any) -> Dict[str, Any]:
        """Check object size limits"""
        result = {'passed': True, 'errors': [], 'estimated_size': 0}
        
        try:
            # Estimate size by serializing to bytes
            json_bytes = json.dumps(data, default=str).encode('utf-8')
            size = len(json_bytes)
            result['estimated_size'] = size
            
            if size > self.safety_config['max_object_size']:
                result['passed'] = False
                result['errors'].append(f"Object size exceeded: {size} > {self.safety_config['max_object_size']} bytes")
            
            # Check array length
            if isinstance(data, list) and len(data) > self.safety_config['max_array_length']:
                result['passed'] = False
                result['errors'].append(f"Array length exceeded: {len(data)} > {self.safety_config['max_array_length']}")
            
        except Exception as e:
            result['passed'] = False
            result['errors'].append(f"Size check error: {e}")
        
        return result
    
    def _check_types(self, data: Any) -> Dict[str, Any]:
        """Check for disallowed types"""
        result = {'passed': True, 'errors': [], 'found_types': []}
        
        def check_recursive(obj):
            obj_type = type(obj)
            
            if obj_type not in self.safety_config['allowed_types']:
                result['passed'] = False
                result['errors'].append(f"Disallowed type found: {obj_type.__name__}")
                result['found_types'].append(obj_type.__name__)
                return
            
            if isinstance(obj, dict):
                for value in obj.values():
                    check_recursive(value)
            elif isinstance(obj, list):
                for item in obj:
                    check_recursive(item)
        
        check_recursive(data)
        return result
    
    def _check_keys(self, data: Any) -> Dict[str, Any]:
        """Check for forbidden keys"""
        result = {'passed': True, 'errors': [], 'found_forbidden_keys': []}
        
        def check_recursive(obj):
            if isinstance(obj, dict):
                for key in obj.keys():
                    if isinstance(key, str):
                        key_lower = key.lower()
                        if any(forbidden in key_lower for forbidden in self.safety_config['forbidden_keys']):
                            result['passed'] = False
                            result['errors'].append(f"Forbidden key found: {key}")
                            result['found_forbidden_keys'].append(key)
                
                    # Recursively check nested objects
                    check_recursive(obj[key])
            elif isinstance(obj, list):
                for item in obj:
                    check_recursive(item)
        
        check_recursive(data)
        return result
    
    def _check_platform_specific(self, data: Any, platform: str) -> Dict[str, Any]:
        """Check platform-specific rules"""
        result = {'passed': True, 'errors': [], 'warnings': []}
        
        # Platform-specific validation rules
        platform_rules = {
            'tiktok': {
                'max_video_length': 1800,  # 30 minutes
                'allowed_formats': ['mp4', 'mov'],
                'forbidden_fields': ['private_key', 'access_token']
            },
            'youtube_shorts': {
                'max_video_length': 60,    # 60 seconds
                'allowed_formats': ['mp4'],
                'forbidden_fields': ['api_key', 'client_secret']
            },
            'instagram_reels': {
                'max_video_length': 90,    # 90 seconds
                'allowed_formats': ['mp4'],
                'forbidden_fields': ['session_token', 'csrf_token']
            }
        }
        
        if platform in platform_rules:
            rules = platform_rules[platform]
            
            # Check for forbidden fields
            if isinstance(data, dict):
                for forbidden_field in rules['forbidden_fields']:
                    if forbidden_field in data:
                        result['warnings'].append(f"Platform-specific forbidden field found: {forbidden_field}")
        
        return result
    
    def _sanitize_data(self, data: Any, platform: Optional[str] = None) -> Any:
        """Sanitize data for safe serialization"""
        if not self.safety_config['sanitize_strings']:
            return data
        
        def sanitize_recursive(obj):
            if isinstance(obj, str):
                # Sanitize string content
                sanitized = obj
                if self.safety_config['prevent_injection']:
                    # Remove potential code injection patterns
                    sanitized = re.sub(r'<script.*?>.*?</script>', '', sanitized, flags=re.IGNORECASE | re.DOTALL)
                    sanitized = re.sub(r'javascript:', '', sanitized, flags=re.IGNORECASE)
                    sanitized = re.sub(r'eval\(', '', sanitized, flags=re.IGNORECASE)
                
                # Limit string length
                if len(sanitized) > self.safety_config['max_string_length']:
                    sanitized = sanitized[:self.safety_config['max_string_length']] + '...'
                
                return sanitized
            elif isinstance(obj, dict):
                return {sanitize_recursive(k): sanitize_recursive(v) for k, v in obj.items()}
            elif isinstance(obj, list):
                return [sanitize_recursive(item) for item in obj]
            else:
                return obj
        
        return sanitize_recursive(data)
    
    def _validate_json_string(self, json_string: str) -> Dict[str, Any]:
        """Validate JSON string before deserialization"""
        result = {'passed': True, 'errors': [], 'metadata': {}}
        
        # Check string length
        if len(json_string) > self.safety_config['max_object_size']:
            result['passed'] = False
            result['errors'].append(f"JSON string too long: {len(json_string)} bytes")
            return result
        
        # Check for UTF-8 validity
        if self.safety_config['validate_utf8']:
            try:
                json_string.encode('utf-8')
            except UnicodeEncodeError as e:
                result['passed'] = False
                result['errors'].append(f"Invalid UTF-8 encoding: {e}")
                return result
        
        # Check for suspicious patterns
        if self.safety_config['prevent_injection']:
            suspicious_patterns = [
                r'<script.*?>.*?</script>',
                r'javascript:',
                r'eval\(',
                r'__import__',
                r'__builtins__'
            ]
            
            for pattern in suspicious_patterns:
                if re.search(pattern, json_string, flags=re.IGNORECASE):
                    result['passed'] = False
                    result['errors'].append(f"Suspicious pattern detected: {pattern}")
                    return result
        
        result['metadata']['string_length'] = len(json_string)
        result['metadata']['is_valid_utf8'] = True
        
        return result
    
    def _validate_serialized_json(self, json_string: str) -> Dict[str, Any]:
        """Validate serialized JSON string"""
        result = {'passed': True, 'errors': [], 'metadata': {}}
        
        try:
            # Try to parse back to ensure valid JSON
            parsed = json.loads(json_string)
            result['metadata']['parsed_successfully'] = True
            result['metadata']['parsed_type'] = type(parsed).__name__
        except json.JSONDecodeError as e:
            result['passed'] = False
            result['errors'].append(f"Invalid JSON: {e}")
        
        return result
    
    def _json_serializer_default(self, obj: Any) -> str:
        """Default serializer for unsupported types"""
        if hasattr(obj, '__dict__'):
            return f"<{obj.__class__.__name__} object>"
        return str(obj)
    
    def _json_deserializer_object_hook(self, obj: dict) -> Any:
        """Object hook for safe deserialization"""
        # Check for suspicious keys
        for key in obj.keys():
            if isinstance(key, str) and any(forbidden in key.lower() for forbidden in self.safety_config['forbidden_keys']):
                raise JSONSerializationError(f"Forbidden key in JSON: {key}")
        
        return obj
    
    def get_safety_summary(self) -> Dict[str, Any]:
        """Get comprehensive safety summary"""
        total = self.serialization_stats['total_serializations']
        
        if total == 0:
            return {
                'total_serializations': 0,
                'success_rate': 0.0,
                'message': 'No serializations performed yet'
            }
        
        return {
            'total_serializations': total,
            'successful_serializations': self.serialization_stats['successful_serializations'],
            'failed_serializations': self.serialization_stats['failed_serializations'],
            'success_rate': (self.serialization_stats['successful_serializations'] / total) * 100,
            'sanitized_objects': self.serialization_stats['sanitized_objects'],
            'blocked_objects': self.serialization_stats['blocked_objects'],
            'size_violations': self.serialization_stats['size_violations'],
            'depth_violations': self.serialization_stats['depth_violations'],
            'type_violations': self.serialization_stats['type_violations'],
            'safety_config': self.safety_config
        }
    
    def update_safety_config(self, config_updates: Dict[str, Any]) -> None:
        """Update safety configuration"""
        self.safety_config.update(config_updates)
        logger.info(f"Updated safety configuration: {list(config_updates.keys())}")

