class StructuredLogger:
    """Structured logging system with JSON outputs for observability systems"""
    
    def __init__(self, logger_name: str = "audio_extractor"):
        self.logger_name = logger_name
        self.logger = logging.getLogger(logger_name)
        
        # Logging configuration
        self.logging_config = {
            'structured_output': True,
            'json_output': True,
            'include_timestamps': True,
            'include_level': True,
            'include_logger_name': True,
            'include_module': True,
            'include_function': True,
            'include_line_number': True,
            'include_thread_id': True,
            'include_process_id': True,
            'pretty_print': False,  # For development
            'field_separator': ',',
            'array_separator': ';'
        }
        
        # Unique ID generation
        self.validation_id_counter = 0
        self.session_id = self._generate_session_id()
        
        # Correlation tracking
        self.correlation_context = {}
        self.validation_chains = {}  # validation_id -> chain of related validations
        
        # Metrics collection
        self.metrics_collector = MetricsCollector()
        
        # Configure structured logging
        self._configure_structured_logging()
    
    def _generate_session_id(self) -> str:
        """Generate unique session ID"""
        import uuid
        return str(uuid.uuid4())
    
    def _generate_validation_id(self) -> str:
        """Generate unique validation ID"""
        self.validation_id_counter += 1
        timestamp = int(time.time() * 1000)  # Millisecond precision
        return f"val_{timestamp}_{self.validation_id_counter:04d}"
    
    def _configure_structured_logging(self) -> None:
        """Configure structured logging with JSON formatter"""
        
        # Remove existing handlers
        for handler in self.logger.handlers[:]:
            self.logger.removeHandler(handler)
        
        # Set logging level
        self.logger.setLevel(logging.INFO)
        
        # Create structured formatter
        formatter = StructuredFormatter(self.logging_config)
        
        # Create console handler
        console_handler = logging.StreamHandler()
        console_handler.setFormatter(formatter)
        self.logger.addHandler(console_handler)
        
        # Create file handler for production logs
        try:
            file_handler = logging.FileHandler('audio_extractor_structured.log')
            file_handler.setFormatter(formatter)
            self.logger.addHandler(file_handler)
        except Exception as e:
            self.logger.error(f"Failed to create file handler: {e}")
    
    def log_validation_start(self, 
                            validation_type: str,
                            file_path: str,
                            metadata: Optional[Dict[str, Any]] = None) -> str:
        """Log validation start with unique ID"""
        
        validation_id = self._generate_validation_id()
        
        # Create correlation context
        correlation_context = {
            'validation_id': validation_id,
            'validation_type': validation_type,
            'file_path': file_path,
            'session_id': self.session_id,
            'timestamp': datetime.utcnow().isoformat(),
            'phase': 'start',
            'metadata': metadata or {}
        }
        
        # Store correlation context
        self.correlation_context[validation_id] = correlation_context
        
        # Log structured event
        self._log_structured_event(
            level='INFO',
            event_type='validation_start',
            message=f"Validation started: {validation_type} for {file_path}",
            correlation_context=correlation_context
        )
        
        return validation_id
    
    def log_validation_complete(self, 
                              validation_id: str,
                              success: bool,
                              result: Dict[str, Any],
                              metrics: Optional[Dict[str, Any]] = None) -> None:
        """Log validation completion"""
        
        correlation_context = self.correlation_context.get(validation_id, {})
        
        # Update correlation context
        correlation_context.update({
            'phase': 'complete',
            'success': success,
            'result': result,
            'metrics': metrics or {},
            'completion_timestamp': datetime.utcnow().isoformat()
        })
        
        # Calculate duration
        if 'timestamp' in correlation_context:
            start_time = datetime.fromisoformat(correlation_context['timestamp'])
            duration_ms = (datetime.utcnow() - start_time).total_seconds() * 1000
            correlation_context['duration_ms'] = duration_ms
        
        # Log structured event
        level = 'INFO' if success else 'ERROR'
        event_type = 'validation_complete' if success else 'validation_failed'
        message = f"Validation {'completed' if success else 'failed'}: {correlation_context.get('validation_type')} for {correlation_context.get('file_path')}"
        
        self._log_structured_event(
            level=level,
            event_type=event_type,
            message=message,
            correlation_context=correlation_context
        )
        
        # Collect metrics
        self.metrics_collector.record_validation_metrics(correlation_context)
    
    def log_numeric_validation(self, 
                             validation_id: str,
                             field_name: str,
                             value: Any,
                             rule: Dict[str, Any],
                             result: Dict[str, Any]) -> None:
        """Log numeric validation with correlation"""
        
        correlation_context = self.correlation_context.get(validation_id, {})
        
        numeric_context = {
            'validation_id': validation_id,
            'field_name': field_name,
            'value': value,
            'rule': rule,
            'result': result,
            'validation_type': 'numeric',
            'timestamp': datetime.utcnow().isoformat(),
            'session_id': self.session_id
        }
        
        # Log structured event
        level = 'INFO' if result.get('success', False) else 'WARNING'
        event_type = 'numeric_validation'
        message = f"Numeric validation: {field_name} = {value} ({'PASS' if result.get('success') else 'FAIL'})"
        
        self._log_structured_event(
            level=level,
            event_type=event_type,
            message=message,
            correlation_context=numeric_context
        )
    
    def log_timing_validation(self, 
                            validation_id: str,
                            field_name: str,
                            value: Any,
                            rule: Dict[str, Any],
                            result: Dict[str, Any]) -> None:
        """Log timing validation with correlation"""
        
        correlation_context = self.correlation_context.get(validation_id, {})
        
        timing_context = {
            'validation_id': validation_id,
            'field_name': field_name,
            'value': value,
            'rule': rule,
            'result': result,
            'validation_type': 'timing',
            'timestamp': datetime.utcnow().isoformat(),
            'session_id': self.session_id
        }
        
        # Log structured event
        level = 'INFO' if result.get('success', False) else 'WARNING'
        event_type = 'timing_validation'
        message = f"Timing validation: {field_name} = {value} ({'PASS' if result.get('success') else 'FAIL'})"
        
        self._log_structured_event(
            level=level,
            event_type=event_type,
            message=message,
            correlation_context=timing_context
        )
    
    def log_output_verification(self, 
                             validation_id: str,
                             verification_type: str,
                             result: Dict[str, Any],
                             metrics: Optional[Dict[str, Any]] = None) -> None:
        """Log output verification with correlation"""
        
        correlation_context = self.correlation_context.get(validation_id, {})
        
        output_context = {
            'validation_id': validation_id,
            'verification_type': verification_type,
            'result': result,
            'metrics': metrics or {},
            'validation_type': 'output',
            'timestamp': datetime.utcnow().isoformat(),
            'session_id': self.session_id
        }
        
        # Log structured event
        level = 'INFO' if result.get('success', False) else 'ERROR'
        event_type = 'output_verification'
        message = f"Output verification: {verification_type} ({'PASS' if result.get('success') else 'FAIL'})"
        
        self._log_structured_event(
            level=level,
            event_type=event_type,
            message=message,
            correlation_context=output_context
        )
    
    def log_error(self, 
                  validation_id: Optional[str],
                  error_type: str,
                  error_message: str,
                  error_details: Optional[Dict[str, Any]] = None,
                  exception: Optional[Exception] = None) -> None:
        """Log error with correlation"""
        
        error_context = {
            'validation_id': validation_id,
            'error_type': error_type,
            'error_message': error_message,
            'error_details': error_details or {},
            'timestamp': datetime.utcnow().isoformat(),
            'session_id': self.session_id
        }
        
        # Add exception details if provided
        if exception:
            error_context['exception'] = {
                'type': type(exception).__name__,
                'message': str(exception),
                'traceback': traceback.format_exc()
            }
        
        # Log structured event
        self._log_structured_event(
            level='ERROR',
            event_type='error',
            message=f"Error: {error_type} - {error_message}",
            correlation_context=error_context
        )
    
    def log_performance_metrics(self, 
                              validation_id: str,
                              metrics: Dict[str, Any]) -> None:
        """Log performance metrics with correlation"""
        
        correlation_context = self.correlation_context.get(validation_id, {})
        
        performance_context = {
            'validation_id': validation_id,
            'metrics': metrics,
            'timestamp': datetime.utcnow().isoformat(),
            'session_id': self.session_id
        }
        
        # Log structured event
        self._log_structured_event(
            level='INFO',
            event_type='performance_metrics',
            message="Performance metrics recorded",
            correlation_context=performance_context
        )
    
    def create_validation_chain(self, parent_validation_id: str, child_validation_type: str) -> str:
        """Create a validation chain for correlated validations"""
        
        child_validation_id = self._generate_validation_id()
        
        # Store chain relationship
        if parent_validation_id not in self.validation_chains:
            self.validation_chains[parent_validation_id] = []
        
        self.validation_chains[parent_validation_id].append({
            'child_validation_id': child_validation_id,
            'validation_type': child_validation_type,
            'created_at': datetime.utcnow().isoformat()
        })
        
        # Log chain creation
        chain_context = {
            'parent_validation_id': parent_validation_id,
            'child_validation_id': child_validation_id,
            'validation_type': child_validation_type,
            'session_id': self.session_id,
            'timestamp': datetime.utcnow().isoformat()
        }
        
        self._log_structured_event(
            level='DEBUG',
            event_type='validation_chain_created',
            message=f"Validation chain: {parent_validation_id} -> {child_validation_id}",
            correlation_context=chain_context
        )
        
        return child_validation_id
    
    def _log_structured_event(self, 
                            level: str,
                            event_type: str,
                            message: str,
                            correlation_context: Dict[str, Any]) -> None:
        """Log structured event with JSON output"""
        
        # Create log record
        log_record = {
            'timestamp': datetime.utcnow().isoformat(),
            'level': level,
            'logger': self.logger_name,
            'event_type': event_type,
            'message': message,
            'correlation_context': correlation_context
        }
        
        # Add system context
        log_record.update({
            'thread_id': threading.current_thread().ident,
            'process_id': os.getpid(),
            'hostname': socket.gethostname(),
            'session_id': self.session_id
        })
        
        # Add module and function info if available
        frame = inspect.currentframe()
        try:
            # Go up the call stack to find the actual caller
            for _ in range(3):
                frame = frame.f_back
                if frame and frame.f_code.co_filename != __file__:
                    break
            
            if frame:
                log_record.update({
                    'module': Path(frame.f_code.co_filename).stem,
                    'function': frame.f_code.co_name,
                    'line_number': frame.f_lineno
                })
        except Exception:
            pass
        
        # Log with appropriate level
        log_level = getattr(logging, level.upper(), logging.INFO)
        self.logger.log(log_level, self._format_log_record(log_record))
    
    def _format_log_record(self, log_record: Dict[str, Any]) -> str:
        """Format log record as JSON or pretty print"""
        
        if self.logging_config['json_output']:
            return json.dumps(log_record, default=str, separators=(',', ':'))
        else:
            # Pretty print for development
            return self._pretty_print_log_record(log_record)
    
    def _pretty_print_log_record(self, log_record: Dict[str, Any]) -> str:
        """Pretty print log record for development"""
        
        lines = []
        lines.append(f"[{log_record['timestamp']}] {log_record['level']} - {log_record['message']}")
        lines.append(f"  Event: {log_record['event_type']}")
        lines.append(f"  Session: {log_record['session_id']}")
        
        if 'validation_id' in log_record['correlation_context']:
            lines.append(f"  Validation ID: {log_record['correlation_context']['validation_id']}")
        
        # Add correlation context
        for key, value in log_record['correlation_context'].items():
            if key not in ['validation_id', 'timestamp', 'session_id']:
                lines.append(f"  {key}: {value}")
        
        return '\n'.join(lines)
    
    def get_validation_summary(self, validation_id: str) -> Dict[str, Any]:
        """Get summary of validation with all correlated events"""
        
        correlation_context = self.correlation_context.get(validation_id, {})
        
        summary = {
            'validation_id': validation_id,
            'session_id': self.session_id,
            'validation_type': correlation_context.get('validation_type'),
            'file_path': correlation_context.get('file_path'),
            'start_time': correlation_context.get('timestamp'),
            'completion_time': correlation_context.get('completion_timestamp'),
            'duration_ms': correlation_context.get('duration_ms'),
            'success': correlation_context.get('success'),
            'result': correlation_context.get('result'),
            'metrics': correlation_context.get('metrics'),
            'child_validations': self.validation_chains.get(validation_id, [])
        }
        
        return summary
    
    def get_session_summary(self) -> Dict[str, Any]:
        """Get comprehensive session summary"""
        
        return {
            'session_id': self.session_id,
            'session_start_time': datetime.utcnow().isoformat(),
            'total_validations': len(self.correlation_context),
            'validation_chains': len(self.validation_chains),
            'metrics': self.metrics_collector.get_session_metrics(),
            'validation_types': list(set(ctx.get('validation_type') for ctx in self.correlation_context.values())),
            'successful_validations': sum(1 for ctx in self.correlation_context.values() if ctx.get('success', False)),
            'failed_validations': sum(1 for ctx in self.correlation_context.values() if not ctx.get('success', False))
        }
    
    def update_logging_config(self, config_updates: Dict[str, Any]) -> None:
        """Update logging configuration"""
        self.logging_config.update(config_updates)
        self._configure_structured_logging()
        logger.info(f"Updated logging configuration: {list(config_updates.keys())}")


class MetricsCollector:
    """Metrics collector for production monitoring"""
    
    def __init__(self):
        self.session_metrics = {
            'validation_counts': defaultdict(int),
            'validation_types': defaultdict(int),
            'error_counts': defaultdict(int),
            'performance_metrics': [],
            'validation_durations': [],
            'success_rates': {}
        }
        
        self.start_time = datetime.utcnow()
    
    def record_validation_metrics(self, correlation_context: Dict[str, Any]) -> None:
        """Record validation metrics"""
        
        validation_type = correlation_context.get('validation_type', 'unknown')
        success = correlation_context.get('success', False)
        duration_ms = correlation_context.get('duration_ms', 0)
        
        # Update counts
        self.session_metrics['validation_counts'][validation_type] += 1
        if success:
            self.session_metrics['validation_types'][validation_type] += 1
        else:
            self.session_metrics['error_counts'][validation_type] += 1
        
        # Record performance metrics
        if duration_ms > 0:
            self.session_metrics['validation_durations'].append(duration_ms)
        
        # Record detailed metrics if available
        metrics = correlation_context.get('metrics', {})
        if metrics:
            metrics_record = {
                'timestamp': correlation_context.get('timestamp'),
                'validation_type': validation_type,
                'success': success,
                'duration_ms': duration_ms,
                'metrics': metrics
            }
            self.session_metrics['performance_metrics'].append(metrics_record)
    
    def get_session_metrics(self) -> Dict[str, Any]:
        """Get comprehensive session metrics"""
        
        total_validations = sum(self.session_metrics['validation_counts'].values())
        total_successful = sum(self.session_metrics['validation_types'].values())
        total_failed = sum(self.session_metrics['error_counts'].values())
        
        # Calculate success rates
        success_rates = {}
        for validation_type in self.session_metrics['validation_counts']:
            successful = self.session_metrics['validation_types'].get(validation_type, 0)
            total = self.session_metrics['validation_counts'][validation_type]
            success_rates[validation_type] = (successful / total * 100) if total > 0 else 0
        
        # Calculate performance statistics
        durations = self.session_metrics['validation_durations']
        performance_stats = {}
        if durations:
            performance_stats = {
                'avg_duration_ms': sum(durations) / len(durations),
                'min_duration_ms': min(durations),
                'max_duration_ms': max(durations),
                'median_duration_ms': sorted(durations)[len(durations) // 2],
                'p95_duration_ms': sorted(durations)[int(len(durations) * 0.95)],
                'p99_duration_ms': sorted(durations)[int(len(durations) * 0.99)]
            }
        
        return {
            'session_duration_seconds': (datetime.utcnow() - self.start_time).total_seconds(),
            'total_validations': total_validations,
            'successful_validations': total_successful,
            'failed_validations': total_failed,
            'overall_success_rate': (total_successful / total_validations * 100) if total_validations > 0 else 0,
            'validation_counts': dict(self.session_metrics['validation_counts']),
            'success_rates': success_rates,
            'performance_stats': performance_stats,
            'error_counts': dict(self.session_metrics['error_counts'])
        }


class StructuredFormatter(logging.Formatter):
    """Structured log formatter for JSON output"""
    
    def __init__(self, config: Dict[str, Any]):
        super().__init__()
        self.config = config
    
    def format(self, record: logging.LogRecord) -> str:
        """Format log record as structured JSON"""
        
        # Create structured log record
        structured_record = {
            'timestamp': datetime.fromtimestamp(record.created).isoformat(),
            'level': record.levelname,
            'logger': record.name,
            'message': record.getMessage(),
            'module': record.module,
            'function': record.funcName,
            'line_number': record.lineno,
            'thread_id': record.thread,
            'process_id': record.process
        }
        
        # Add extra fields if present
        if hasattr(record, 'event_type'):
            structured_record['event_type'] = record.event_type
        
        if hasattr(record, 'correlation_context'):
            structured_record['correlation_context'] = record.correlation_context
        
        # Format as JSON
        return json.dumps(structured_record, default=str, separators=(',', ':'))


# Global structured logger instance
structured_logger = StructuredLogger("audio_extractor")

class EnhancedNumericValidator:
    """Enhanced numeric validator with structured logging integration"""
    
    def __init__(self, structured_logger: StructuredLogger):
        self.base_validator = NumericValidator()
        self.structured_logger = structured_logger
        self.validation_chains = {}  # Track validation relationships
    
    def validate_numeric_field(self, 
                             field_name: str, 
                             value: Any, 
                             rule: Dict[str, Any],
                             parent_validation_id: Optional[str] = None) -> Dict[str, Any]:
        """Validate numeric field with structured logging"""
        
        # Create validation chain if parent provided
        if parent_validation_id:
            validation_id = self.structured_logger.create_validation_chain(
                parent_validation_id, 
                f"numeric_{field_name}"
            )
        else:
            validation_id = self.structured_logger.log_validation_start(
                validation_type="numeric",
                file_path=field_name,  # Use field name as identifier
                metadata={"rule": rule, "value": value}
            )
        
        try:
            # Perform validation
            result = self.base_validator.validate_numeric_field(field_name, value, rule)
            
            # Log numeric validation result
            self.structured_logger.log_numeric_validation(
                validation_id=validation_id,
                field_name=field_name,
                value=value,
                rule=rule,
                result=result
            )
            
            # Log validation completion
            self.structured_logger.log_validation_complete(
                validation_id=validation_id,
                success=result.get('success', False),
                result=result,
                metrics={"validation_type": "numeric"}
            )
            
            return result
            
        except Exception as e:
            # Log error
            self.structured_logger.log_error(
                validation_id=validation_id,
                error_type="numeric_validation_error",
                error_message=f"Numeric validation failed for {field_name}",
                error_details={"field_name": field_name, "value": value, "rule": rule},
                exception=e
            )
            
            # Log validation completion with failure
            self.structured_logger.log_validation_complete(
                validation_id=validation_id,
                success=False,
                result={"success": False, "error": str(e)},
                metrics={"validation_type": "numeric"}
            )
            
            return {"success": False, "error": str(e)}
    
    def validate_numeric_sequence(self, 
                                 field_name: str, 
                                 values: List[Any], 
                                 rule: Dict[str, Any],
                                 parent_validation_id: Optional[str] = None) -> Dict[str, Any]:
        """Validate numeric sequence with structured logging"""
        
        # Create validation chain if parent provided
        if parent_validation_id:
            validation_id = self.structured_logger.create_validation_chain(
                parent_validation_id, 
                f"numeric_sequence_{field_name}"
            )
        else:
            validation_id = self.structured_logger.log_validation_start(
                validation_type="numeric_sequence",
                file_path=field_name,
                metadata={"rule": rule, "sequence_length": len(values)}
            )
        
        try:
            # Perform validation
            result = self.base_validator.validate_numeric_sequence(field_name, values, rule)
            
            # Log sequence validation metrics
            self.structured_logger.log_performance_metrics(
                validation_id=validation_id,
                metrics={
                    "validation_type": "numeric_sequence",
                    "sequence_length": len(values),
                    "success_count": result.get('success_count', 0),
                    "failure_count": result.get('failure_count', 0)
                }
            )
            
            # Log validation completion
            self.structured_logger.log_validation_complete(
                validation_id=validation_id,
                success=result.get('overall_success', False),
                result=result,
                metrics={"validation_type": "numeric_sequence"}
            )
            
            return result
            
        except Exception as e:
            # Log error
            self.structured_logger.log_error(
                validation_id=validation_id,
                error_type="numeric_sequence_validation_error",
                error_message=f"Numeric sequence validation failed for {field_name}",
                error_details={"field_name": field_name, "sequence_length": len(values), "rule": rule},
                exception=e
            )
            
            # Log validation completion with failure
            self.structured_logger.log_validation_complete(
                validation_id=validation_id,
                success=False,
                result={"success": False, "error": str(e)},
                metrics={"validation_type": "numeric_sequence"}
            )
            
            return {"success": False, "error": str(e)}


