class IntegratedValidationPipeline:
    """Integrated validation pipeline with structured logging and correlation"""
    
    def __init__(self, structured_logger: Optional[StructuredLogger] = None):
        self.structured_logger = structured_logger or StructuredLogger("validation_pipeline")
        
        # Initialize enhanced validators
        self.numeric_validator = EnhancedNumericValidator(self.structured_logger)
        self.timing_validator = EnhancedTimingValidator(self.structured_logger)
        self.output_verifier = EnhancedOutputVerifier(self.structured_logger)
        
        # Validation configuration
        self.validation_config = {
            'enable_validation_chains': True,
            'log_performance_metrics': True,
            'collect_detailed_metrics': True,
            'correlate_validations': True
        }
    
    def validate_complete_pipeline(self, 
                                 file_path: Path,
                                 audio_data: Dict[str, Any],
                                 validation_rules: Dict[str, Any]) -> Dict[str, Any]:
        """Execute complete validation pipeline with correlation"""
        
        # Start main validation
        main_validation_id = self.structured_logger.log_validation_start(
            validation_type="complete_pipeline",
            file_path=str(file_path),
            metadata={
                "validation_rules": validation_rules,
                "audio_data_keys": list(audio_data.keys())
            }
        )
        
        pipeline_result = {
            'validation_id': main_validation_id,
            'success': False,
            'validation_results': {},
            'correlated_validations': [],
            'pipeline_metrics': {},
            'start_time': datetime.utcnow().isoformat()
        }
        
        try:
            # Step 1: Numeric validations
            numeric_results = {}
            numeric_validation_id = self.structured_logger.create_validation_chain(
                main_validation_id, 
                "numeric_validations"
            )
            
            for field_name, rule in validation_rules.get('numeric_rules', {}).items():
                if field_name in audio_data:
                    result = self.numeric_validator.validate_numeric_field(
                        field_name, 
                        audio_data[field_name], 
                        rule,
                        numeric_validation_id
                    )
                    numeric_results[field_name] = result
            
            pipeline_result['validation_results']['numeric'] = numeric_results
            
            # Step 2: Timing validations
            timing_results = {}
            timing_validation_id = self.structured_logger.create_validation_chain(
                main_validation_id, 
                "timing_validations"
            )
            
            for field_name, rule in validation_rules.get('timing_rules', {}).items():
                if field_name in audio_data:
                    result = self.timing_validator.validate_timing_field(
                        field_name, 
                        audio_data[field_name], 
                        rule,
                        timing_validation_id
                    )
                    timing_results[field_name] = result
            
            pipeline_result['validation_results']['timing'] = timing_results
            
            # Step 3: Output verification
            if validation_rules.get('output_verification', {}).get('enabled', False):
                output_validation_id = self.structured_logger.create_validation_chain(
                    main_validation_id, 
                    "output_verification"
                )
                
                expected_properties = validation_rules['output_verification'].get('expected_properties', {})
                output_result = self.output_verifier.verify_audio_output(
                    file_path, 
                    expected_properties,
                    output_validation_id
                )
                pipeline_result['validation_results']['output'] = output_result
            
            # Determine overall success
            all_results = []
            for validation_type in ['numeric', 'timing', 'output']:
                if validation_type in pipeline_result['validation_results']:
                    for field_result in pipeline_result['validation_results'][validation_type].values():
                        all_results.append(field_result.get('success', False))
            
            pipeline_result['success'] = all(all_results) if all_results else False
            
            # Log pipeline completion
            self.structured_logger.log_validation_complete(
                validation_id=main_validation_id,
                success=pipeline_result['success'],
                result=pipeline_result,
                metrics={
                    "validation_type": "complete_pipeline",
                    "numeric_validations": len(numeric_results),
                    "timing_validations": len(timing_results),
                    "output_verification": "output" in pipeline_result['validation_results']
                }
            )
            
            # Collect pipeline metrics
            pipeline_result['pipeline_metrics'] = {
                'total_validations': len(all_results),
                'successful_validations': sum(all_results),
                'failed_validations': len(all_results) - sum(all_results),
                'validation_types': list(pipeline_result['validation_results'].keys())
            }
            
            return pipeline_result
            
        except Exception as e:
            # Log pipeline error
            self.structured_logger.log_error(
                validation_id=main_validation_id,
                error_type="pipeline_validation_error",
                error_message=f"Complete validation pipeline failed for {file_path}",
                error_details={"file_path": str(file_path), "validation_rules": validation_rules},
                exception=e
            )
            
            # Log pipeline completion with failure
            self.structured_logger.log_validation_complete(
                validation_id=main_validation_id,
                success=False,
                result={"success": False, "error": str(e)},
                metrics={"validation_type": "complete_pipeline"}
            )
            
            pipeline_result['success'] = False
            pipeline_result['error'] = str(e)
            
            return pipeline_result
    
    def get_validation_summary(self, validation_id: str) -> Dict[str, Any]:
        """Get comprehensive validation summary"""
        
        # Get base summary
        summary = self.structured_logger.get_validation_summary(validation_id)
        
        # Add pipeline-specific details
        if 'validation_results' in summary.get('result', {}):
            summary['validation_breakdown'] = {
                validation_type: {
                    'total_fields': len(results),
                    'successful_fields': sum(1 for r in results.values() if r.get('success', False)),
                    'failed_fields': sum(1 for r in results.values() if not r.get('success', False)),
                    'field_results': results
                }
                for validation_type, results in summary['result']['validation_results'].items()
            }
        
        return summary
    
    def get_session_summary(self) -> Dict[str, Any]:
        """Get comprehensive session summary"""
        
        base_summary = self.structured_logger.get_session_summary()
        
        # Add pipeline-specific metrics
        base_summary.update({
            'pipeline_config': self.validation_config,
            'validator_status': {
                'numeric_validator': 'active',
                'timing_validator': 'active',
                'output_verifier': 'active'
            }
        })
        
        return base_summary


# Global integrated validation pipeline instance
integrated_validation_pipeline = IntegratedValidationPipeline(structured_logger)

