class ObservabilityManager:
    """Production observability manager for metrics export and monitoring"""
    
    def __init__(self, structured_logger: StructuredLogger):
        self.structured_logger = structured_logger
        self.metrics_collector = structured_logger.metrics_collector
        
        # Observability configuration
        self.observability_config = {
            'prometheus_enabled': True,
            'prometheus_port': 8080,
            'prometheus_endpoint': '/metrics',
            'statsd_enabled': False,
            'statsd_host': 'localhost',
            'statsd_port': 8125,
            'graphite_enabled': False,
            'graphite_host': 'localhost',
            'graphite_port': 2003,
            'export_interval_seconds': 30,
            'metrics_retention_hours': 24,
            'alert_thresholds': {
                'validation_failure_rate': 0.05,  # 5%
                'average_validation_time_ms': 1000,  # 1 second
                'memory_usage_percent': 80.0,  # 80%
                'error_rate_per_minute': 10
            }
        }
        
        # Metrics storage
        self.time_series_metrics = defaultdict(list)  # metric_name -> list of (timestamp, value)
        self.alert_history = deque(maxlen=1000)
        self.export_history = deque(maxlen=100)
        
        # Alert management
        self.alert_cooldowns = {}  # alert_type -> last_alert_timestamp
        self.alert_handlers = []
        
        # Export state
        self.export_running = False
        self.export_thread = None
        self.last_export_time = None
    
    def register_alert_handler(self, handler: callable) -> None:
        """Register alert handler for notifications"""
        self.alert_handlers.append(handler)
    
    def collect_validation_metrics(self, validation_id: str, metrics: Dict[str, Any]) -> None:
        """Collect validation metrics for observability"""
        
        timestamp = datetime.utcnow()
        
        # Extract key metrics
        validation_type = metrics.get('validation_type', 'unknown')
        success = metrics.get('success', False)
        duration_ms = metrics.get('duration_ms', 0)
        
        # Store time series metrics
        self.time_series_metrics['validation_total'].append((timestamp, 1))
        self.time_series_metrics['validation_success'].append((timestamp, 1 if success else 0))
        self.time_series_metrics['validation_failure'].append((timestamp, 0 if success else 1))
        self.time_series_metrics['validation_duration_ms'].append((timestamp, duration_ms))
        self.time_series_metrics[f'validation_{validation_type}'].append((timestamp, 1))
        
        # Check alert thresholds
        self._check_alert_thresholds(validation_type, metrics, timestamp)
        
        # Log metrics collection
        self.structured_logger.log_performance_metrics(
            validation_id=validation_id,
            metrics={
                'observability_metrics_collected': True,
                'validation_type': validation_type,
                'success': success,
                'duration_ms': duration_ms
            }
        )
    
    def _check_alert_thresholds(self, validation_type: str, metrics: Dict[str, Any], timestamp: datetime) -> None:
        """Check metrics against alert thresholds"""
        
        current_time = timestamp
        
        # Check validation failure rate
        failure_rate = self._calculate_failure_rate(window_minutes=5)
        if failure_rate > self.observability_config['alert_thresholds']['validation_failure_rate']:
            self._trigger_alert(
                alert_type='high_failure_rate',
                severity='warning',
                message=f"Validation failure rate: {failure_rate:.2%}",
                details={
                    'failure_rate': failure_rate,
                    'threshold': self.observability_config['alert_thresholds']['validation_failure_rate'],
                    'validation_type': validation_type
                },
                timestamp=current_time
            )
        
        # Check average validation time
        avg_duration = self._calculate_average_duration(window_minutes=5)
        if avg_duration > self.observability_config['alert_thresholds']['average_validation_time_ms']:
            self._trigger_alert(
                alert_type='slow_validation',
                severity='warning',
                message=f"Average validation time: {avg_duration:.2f}ms",
                details={
                    'average_duration_ms': avg_duration,
                    'threshold': self.observability_config['alert_thresholds']['average_validation_time_ms'],
                    'validation_type': validation_type
                },
                timestamp=current_time
            )
        
        # Check error rate
        error_rate = self._calculate_error_rate(window_minutes=1)
        if error_rate > self.observability_config['alert_thresholds']['error_rate_per_minute']:
            self._trigger_alert(
                alert_type='high_error_rate',
                severity='critical',
                message=f"Error rate: {error_rate} errors/minute",
                details={
                    'error_rate_per_minute': error_rate,
                    'threshold': self.observability_config['alert_thresholds']['error_rate_per_minute']
                },
                timestamp=current_time
            )
    
    def _calculate_failure_rate(self, window_minutes: int = 5) -> float:
        """Calculate validation failure rate over time window"""
        
        cutoff_time = datetime.utcnow() - timedelta(minutes=window_minutes)
        
        total_validations = 0
        failed_validations = 0
        
        for timestamp, value in self.time_series_metrics['validation_total']:
            if timestamp >= cutoff_time:
                total_validations += value
        
        for timestamp, value in self.time_series_metrics['validation_failure']:
            if timestamp >= cutoff_time:
                failed_validations += value
        
        return (failed_validations / total_validations) if total_validations > 0 else 0.0
    
    def _calculate_average_duration(self, window_minutes: int = 5) -> float:
        """Calculate average validation duration over time window"""
        
        cutoff_time = datetime.utcnow() - timedelta(minutes=window_minutes)
        
        durations = []
        for timestamp, value in self.time_series_metrics['validation_duration_ms']:
            if timestamp >= cutoff_time:
                durations.append(value)
        
        return sum(durations) / len(durations) if durations else 0.0
    
    def _calculate_error_rate(self, window_minutes: int = 1) -> float:
        """Calculate error rate per minute"""
        
        cutoff_time = datetime.utcnow() - timedelta(minutes=window_minutes)
        
        error_count = 0
        for timestamp, value in self.time_series_metrics.get('validation_errors', []):
            if timestamp >= cutoff_time:
                error_count += value
        
        return error_count / window_minutes
    
    def _trigger_alert(self, alert_type: str, severity: str, message: str, details: Dict[str, Any], timestamp: datetime) -> None:
        """Trigger alert with cooldown management"""
        
        # Check cooldown
        last_alert = self.alert_cooldowns.get(alert_type)
        if last_alert and (timestamp - last_alert).total_seconds() < 300:  # 5 minute cooldown
            return
        
        # Create alert
        alert = {
            'alert_id': f"alert_{alert_type}_{int(timestamp.timestamp())}",
            'alert_type': alert_type,
            'severity': severity,
            'message': message,
            'details': details,
            'timestamp': timestamp.isoformat(),
            'session_id': self.structured_logger.session_id
        }
        
        # Store alert
        self.alert_history.append(alert)
        self.alert_cooldowns[alert_type] = timestamp
        
        # Log alert
        self.structured_logger.log_error(
            validation_id=None,
            error_type=f"alert_{alert_type}",
            error_message=message,
            error_details=details
        )
        
        # Notify handlers
        for handler in self.alert_handlers:
            try:
                handler(alert)
            except Exception as e:
                logger.error(f"Alert handler failed: {e}")
    
    def export_prometheus_metrics(self) -> str:
        """Export metrics in Prometheus format"""
        
        metrics_output = []
        
        # Calculate current metrics
        current_time = datetime.utcnow()
        
        # Validation metrics
        total_validations = self._get_metric_sum('validation_total', window_minutes=60)
        success_validations = self._get_metric_sum('validation_success', window_minutes=60)
        failure_validations = self._get_metric_sum('validation_failure', window_minutes=60)
        avg_duration = self._calculate_average_duration(window_minutes=60)
        
        metrics_output.append(f"# HELP audio_extractor_validations_total Total number of validations")
        metrics_output.append(f"# TYPE audio_extractor_validations_total counter")
        metrics_output.append(f"audio_extractor_validations_total {total_validations}")
        
        metrics_output.append(f"# HELP audio_extractor_validations_success_total Total successful validations")
        metrics_output.append(f"# TYPE audio_extractor_validations_success_total counter")
        metrics_output.append(f"audio_extractor_validations_success_total {success_validations}")
        
        metrics_output.append(f"# HELP audio_extractor_validations_failure_total Total failed validations")
        metrics_output.append(f"# TYPE audio_extractor_validations_failure_total counter")
        metrics_output.append(f"audio_extractor_validations_failure_total {failure_validations}")
        
        metrics_output.append(f"# HELP audio_extractor_validation_duration_ms Average validation duration")
        metrics_output.append(f"# TYPE audio_extractor_validation_duration_ms gauge")
        metrics_output.append(f"audio_extractor_validation_duration_ms {avg_duration}")
        
        # Validation type metrics
        validation_types = set()
        for metric_name in self.time_series_metrics:
            if metric_name.startswith('validation_') and metric_name not in ['validation_total', 'validation_success', 'validation_failure', 'validation_duration_ms']:
                validation_type = metric_name.replace('validation_', '')
                validation_types.add(validation_type)
        
        for validation_type in validation_types:
            count = self._get_metric_sum(f'validation_{validation_type}', window_minutes=60)
            metrics_output.append(f"audio_extractor_validations_{validation_type}_total {count}")
        
        # System metrics
        memory_usage = self._get_memory_usage_percent()
        metrics_output.append(f"# HELP audio_extractor_memory_usage_percent Memory usage percentage")
        metrics_output.append(f"# TYPE audio_extractor_memory_usage_percent gauge")
        metrics_output.append(f"audio_extractor_memory_usage_percent {memory_usage}")
        
        # Alert metrics
        active_alerts = len([a for a in self.alert_history if (current_time - datetime.fromisoformat(a['timestamp'])).total_seconds() < 3600])
        metrics_output.append(f"# HELP audio_extractor_active_alerts Number of active alerts")
        metrics_output.append(f"# TYPE audio_extractor_active_alerts gauge")
        metrics_output.append(f"audio_extractor_active_alerts {active_alerts}")
        
        return '\n'.join(metrics_output)
    
    def _get_metric_sum(self, metric_name: str, window_minutes: int = 60) -> float:
        """Get metric sum over time window"""
        
        cutoff_time = datetime.utcnow() - timedelta(minutes=window_minutes)
        
        total = 0.0
        for timestamp, value in self.time_series_metrics.get(metric_name, []):
            if timestamp >= cutoff_time:
                total += value
        
        return total
    
    def _get_memory_usage_percent(self) -> float:
        """Get current memory usage percentage"""
        
        try:
            import psutil
            memory = psutil.virtual_memory()
            return memory.percent
        except ImportError:
            # Fallback to basic memory calculation
            try:
                import resource
                usage = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
                # Convert to MB (varies by system)
                if hasattr(resource, 'RUSAGE_SELF'):
                    # Linux: KB, macOS: bytes
                    if platform.system() == 'Darwin':
                        usage_mb = usage / (1024 * 1024)
                    else:
                        usage_mb = usage / 1024
                    
                    # Estimate total memory (rough approximation)
                    total_memory_mb = 8192  # 8GB assumption
                    return (usage_mb / total_memory_mb) * 100
            except:
                pass
        
        return 0.0
    
    def export_json_metrics(self) -> Dict[str, Any]:
        """Export metrics in JSON format"""
        
        current_time = datetime.utcnow()
        
        # Calculate metrics
        session_metrics = self.metrics_collector.get_session_metrics()
        
        # Time series metrics
        time_series = {}
        for metric_name, values in self.time_series_metrics.items():
            # Get recent values (last hour)
            cutoff_time = current_time - timedelta(hours=1)
            recent_values = [(timestamp.isoformat(), value) for timestamp, value in values if timestamp >= cutoff_time]
            time_series[metric_name] = recent_values
        
        # Alert summary
        recent_alerts = [
            {
                'alert_id': alert['alert_id'],
                'alert_type': alert['alert_type'],
                'severity': alert['severity'],
                'message': alert['message'],
                'timestamp': alert['timestamp']
            }
            for alert in self.alert_history 
            if (current_time - datetime.fromisoformat(alert['timestamp'])).total_seconds() < 3600
        ]
        
        return {
            'timestamp': current_time.isoformat(),
            'session_id': self.structured_logger.session_id,
            'session_metrics': session_metrics,
            'time_series_metrics': time_series,
            'recent_alerts': recent_alerts,
            'system_metrics': {
                'memory_usage_percent': self._get_memory_usage_percent(),
                'active_alerts_count': len(recent_alerts),
                'last_export_time': self.last_export_time.isoformat() if self.last_export_time else None
            },
            'observability_config': self.observability_config
        }
    
    def start_metrics_export(self) -> None:
        """Start background metrics export"""
        
        if self.export_running:
            return
        
        self.export_running = True
        self.export_thread = threading.Thread(target=self._export_loop, daemon=True)
        self.export_thread.start()
        
        logger.info("Started metrics export thread")
    
    def stop_metrics_export(self) -> None:
        """Stop background metrics export"""
        
        self.export_running = False
        if self.export_thread:
            self.export_thread.join(timeout=5)
        
        logger.info("Stopped metrics export thread")
    
    def _export_loop(self) -> None:
        """Background export loop"""
        
        while self.export_running:
            try:
                # Export metrics
                self._perform_export()
                
                # Sleep until next export
                time.sleep(self.observability_config['export_interval_seconds'])
                
            except Exception as e:
                logger.error(f"Metrics export error: {e}")
                time.sleep(10)  # Short sleep on error
    
    def _perform_export(self) -> None:
        """Perform metrics export"""
        
        export_start = time.time()
        
        try:
            # Export to file
            json_metrics = self.export_json_metrics()
            export_file = Path('audio_extractor_metrics.json')
            
            with open(export_file, 'w') as f:
                json.dump(json_metrics, f, indent=2)
            
            # Export Prometheus metrics if enabled
            if self.observability_config['prometheus_enabled']:
                prometheus_metrics = self.export_prometheus_metrics()
                prometheus_file = Path('audio_extractor_prometheus.metrics')
                
                with open(prometheus_file, 'w') as f:
                    f.write(prometheus_metrics)
            
            # Record export
            self.last_export_time = datetime.utcnow()
            export_duration = (time.time() - export_start) * 1000
            
            self.export_history.append({
                'timestamp': self.last_export_time.isoformat(),
                'duration_ms': export_duration,
                'metrics_count': len(json_metrics.get('time_series_metrics', {})),
                'success': True
            })
            
            # Clean old metrics
            self._cleanup_old_metrics()
            
        except Exception as e:
            self.export_history.append({
                'timestamp': datetime.utcnow().isoformat(),
                'duration_ms': (time.time() - export_start) * 1000,
                'success': False,
                'error': str(e)
            })
            
            raise
    
    def _cleanup_old_metrics(self) -> None:
        """Clean up old metrics data"""
        
        cutoff_time = datetime.utcnow() - timedelta(hours=self.observability_config['metrics_retention_hours'])
        
        # Clean time series metrics
        for metric_name in list(self.time_series_metrics.keys()):
            filtered_values = [(timestamp, value) for timestamp, value in self.time_series_metrics[metric_name] if timestamp >= cutoff_time]
            self.time_series_metrics[metric_name] = filtered_values
        
        # Clean alert history
        self.alert_history = deque(
            [alert for alert in self.alert_history if datetime.fromisoformat(alert['timestamp']) >= cutoff_time],
            maxlen=1000
        )
    
    def get_observability_status(self) -> Dict[str, Any]:
        """Get observability system status"""
        
        return {
            'timestamp': datetime.utcnow().isoformat(),
            'export_running': self.export_running,
            'last_export_time': self.last_export_time.isoformat() if self.last_export_time else None,
            'metrics_count': len(self.time_series_metrics),
            'active_alerts': len([a for a in self.alert_history if (datetime.utcnow() - datetime.fromisoformat(a['timestamp'])).total_seconds() < 3600]),
            'alert_handlers_count': len(self.alert_handlers),
            'export_history_count': len(self.export_history),
            'observability_config': self.observability_config,
            'system_metrics': {
                'memory_usage_percent': self._get_memory_usage_percent(),
                'thread_id': threading.current_thread().ident
            }
        }
    
    def update_observability_config(self, config_updates: Dict[str, Any]) -> None:
        """Update observability configuration"""
        
        self.observability_config.update(config_updates)
        
        # Restart export if interval changed
        if 'export_interval_seconds' in config_updates and self.export_running:
            self.stop_metrics_export()
            self.start_metrics_export()
        
        logger.info(f"Updated observability configuration: {list(config_updates.keys())}")


class ProductionMetricsExporter:
    """Production metrics exporter with multiple format support"""
    
    def __init__(self, observability_manager: ObservabilityManager):
        self.observability_manager = observability_manager
        
        # Export configuration
        self.export_config = {
            'formats': ['json', 'prometheus'],
            'output_directory': 'metrics',
            'compression_enabled': True,
            'retention_days': 7,
            'batch_size': 1000,
            'export_timeout_seconds': 30
        }
        
        # Export state
        self.export_queue = asyncio.Queue()
        self.export_running = False
        self.export_stats = {
            'total_exports': 0,
            'successful_exports': 0,
            'failed_exports': 0,
            'average_export_time_ms': 0,
            'last_export_time': None
        }
    
    async def export_metrics_async(self, formats: Optional[List[str]] = None) -> Dict[str, Any]:
        """Export metrics asynchronously"""
        
        formats = formats or self.export_config['formats']
        export_results = {}
        
        export_start = time.time()
        
        try:
            # Export JSON metrics
            if 'json' in formats:
                json_result = await self._export_json_async()
                export_results['json'] = json_result
            
            # Export Prometheus metrics
            if 'prometheus' in formats:
                prometheus_result = await self._export_prometheus_async()
                export_results['prometheus'] = prometheus_result
            
            # Update statistics
            export_duration = (time.time() - export_start) * 1000
            self._update_export_stats(True, export_duration)
            
            return {
                'success': True,
                'formats': list(export_results.keys()),
                'export_duration_ms': export_duration,
                'results': export_results
            }
            
        except Exception as e:
            export_duration = (time.time() - export_start) * 1000
            self._update_export_stats(False, export_duration)
            
            return {
                'success': False,
                'error': str(e),
                'export_duration_ms': export_duration
            }
    
    async def _export_json_async(self) -> Dict[str, Any]:
        """Export JSON metrics asynchronously"""
        
        try:
            # Get metrics
            json_metrics = self.observability_manager.export_json_metrics()
            
            # Write to file
            output_dir = Path(self.export_config['output_directory'])
            output_dir.mkdir(exist_ok=True)
            
            timestamp = datetime.utcnow().strftime('%Y%m%d_%H%M%S')
            filename = f"audio_extractor_metrics_{timestamp}.json"
            filepath = output_dir / filename
            
            # Write asynchronously
            json_content = json.dumps(json_metrics, indent=2)
            
            with open(filepath, 'w') as f:
                f.write(json_content)
            
            # Compress if enabled
            if self.export_config['compression_enabled']:
                await self._compress_file_async(filepath)
            
            return {
                'success': True,
                'filename': filename,
                'filepath': str(filepath),
                'size_bytes': len(json_content.encode('utf-8')),
                'compressed': self.export_config['compression_enabled']
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': str(e)
            }
    
    async def _export_prometheus_async(self) -> Dict[str, Any]:
        """Export Prometheus metrics asynchronously"""
        
        try:
            # Get metrics
            prometheus_metrics = self.observability_manager.export_prometheus_metrics()
            
            # Write to file
            output_dir = Path(self.export_config['output_directory'])
            output_dir.mkdir(exist_ok=True)
            
            timestamp = datetime.utcnow().strftime('%Y%m%d_%H%M%S')
            filename = f"audio_extractor_prometheus_{timestamp}.metrics"
            filepath = output_dir / filename
            
            # Write asynchronously
            with open(filepath, 'w') as f:
                f.write(prometheus_metrics)
            
            # Compress if enabled
            if self.export_config['compression_enabled']:
                await self._compress_file_async(filepath)
            
            return {
                'success': True,
                'filename': filename,
                'filepath': str(filepath),
                'size_bytes': len(prometheus_metrics.encode('utf-8')),
                'compressed': self.export_config['compression_enabled']
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': str(e)
            }
    
    async def _compress_file_async(self, filepath: Path) -> None:
        """Compress file asynchronously"""
        
        try:
            import gzip
            
            # Read original file
            with open(filepath, 'rb') as f:
                original_content = f.read()
            
            # Write compressed file
            compressed_filepath = filepath.with_suffix(filepath.suffix + '.gz')
            with gzip.open(compressed_filepath, 'wb') as f:
                f.write(original_content)
            
            # Remove original file
            filepath.unlink()
            
        except Exception as e:
            logger.error(f"Failed to compress file {filepath}: {e}")
    
    def _update_export_stats(self, success: bool, duration_ms: float) -> None:
        """Update export statistics"""
        
        self.export_stats['total_exports'] += 1
        
        if success:
            self.export_stats['successful_exports'] += 1
        else:
            self.export_stats['failed_exports'] += 1
        
        # Update average export time
        total_time = self.export_stats['average_export_time_ms'] * (self.export_stats['total_exports'] - 1)
        current_time = duration_ms
        self.export_stats['average_export_time_ms'] = (total_time + current_time) / self.export_stats['total_exports']
        
        self.export_stats['last_export_time'] = datetime.utcnow().isoformat()
    
    def get_export_statistics(self) -> Dict[str, Any]:
        """Get export statistics"""
        
        return {
            'timestamp': datetime.utcnow().isoformat(),
            'export_stats': self.export_stats.copy(),
            'export_config': self.export_config.copy(),
            'success_rate': (
                self.export_stats['successful_exports'] / 
                max(self.export_stats['total_exports'], 1)
            ) * 100
        }


# Global observability manager instance
observability_manager = ObservabilityManager(structured_logger)
production_metrics_exporter = ProductionMetricsExporter(observability_manager)

