class BatchProcessingOptimizer:
    """High-performance batch processing and vectorized calculations"""
    
    def __init__(self):
        # Batch configuration
        self.batch_config = {
            'max_batch_size': 10000,           # Maximum items per batch
            'vectorization_threshold': 100,     # Minimum items for vectorization
            'memory_limit_mb': 512,            # Memory limit for batch processing
            'parallel_workers': 4,              # Number of parallel workers
            'chunk_size': 1000,                # Chunk size for large datasets
            'use_numpy': True,                  # Enable NumPy vectorization
            'use_multiprocessing': True,       # Enable multiprocessing for large batches
            'cache_intermediate_results': True  # Cache intermediate calculations
        }
        
        # Performance tracking
        self.performance_metrics = {
            'batches_processed': 0,
            'total_items_processed': 0,
            'vectorized_operations': 0,
            'parallel_operations': 0,
            'cache_hits': 0,
            'cache_misses': 0,
            'average_batch_time_ms': 0,
            'peak_memory_mb': 0
        }
        
        # Intermediate result cache
        self.result_cache = {}
        self.cache_lock = threading.Lock()
        
        # Initialize NumPy if available
        self.numpy_available = self._check_numpy_availability()
    
    def _check_numpy_availability(self) -> bool:
        """Check if NumPy is available for vectorization"""
        try:
            import numpy as np
            self.np = np
            return True
        except ImportError:
            self.np = None
            return False
    
    def process_numeric_batch(self, 
                           values: List[Any], 
                           rules: List[Dict[str, Any]], 
                           field_names: List[str]) -> Dict[str, Any]:
        """Process numeric validation batch with vectorization"""
        
        batch_start = time.time()
        
        # Determine processing strategy
        if len(values) >= self.batch_config['vectorization_threshold'] and self.numpy_available:
            return self._process_vectorized_batch(values, rules, field_names)
        elif len(values) >= self.batch_config['chunk_size']:
            return self._process_chunked_batch(values, rules, field_names)
        else:
            return self._process_standard_batch(values, rules, field_names)
    
    def _process_vectorized_batch(self, 
                                 values: List[Any], 
                                 rules: List[Dict[str, Any]], 
                                 field_names: List[str]) -> Dict[str, Any]:
        """Process batch using NumPy vectorization"""
        
        try:
            # Convert to NumPy arrays
            np_values = self.np.array(values, dtype=self.np.float64)
            
            results = {
                'success': True,
                'method': 'vectorized',
                'field_results': {},
                'batch_metrics': {
                    'items_processed': len(values),
                    'vectorized_operations': len(rules),
                    'processing_time_ms': 0
                }
            }
            
            # Process each rule vectorized
            for i, (rule, field_name) in enumerate(zip(rules, field_names)):
                rule_result = self._apply_vectorized_rule(np_values, rule, field_name)
                results['field_results'][field_name] = rule_result
            
            # Update performance metrics
            self.performance_metrics['vectorized_operations'] += len(rules)
            self.performance_metrics['batches_processed'] += 1
            self.performance_metrics['total_items_processed'] += len(values)
            
            return results
            
        except Exception as e:
            # Fallback to standard processing
            return self._process_standard_batch(values, rules, field_names)
    
    def _apply_vectorized_rule(self, 
                              np_values: 'numpy.ndarray', 
                              rule: Dict[str, Any], 
                              field_name: str) -> Dict[str, Any]:
        """Apply validation rule using vectorized operations"""
        
        try:
            # Vectorized range validation
            min_val = rule.get('min_value', -float('inf'))
            max_val = rule.get('max_value', float('inf'))
            
            # Check for NaN and infinite values
            nan_mask = self.np.isnan(np_values)
            inf_mask = self.np.isinf(np_values)
            
            # Range validation
            valid_mask = (np_values >= min_val) & (np_values <= max_val)
            
            # Combine all validation results
            final_valid_mask = valid_mask & ~nan_mask & ~inf_mask
            
            # Calculate statistics
            valid_count = self.np.sum(final_valid_mask)
            invalid_count = len(np_values) - valid_count
            
            # Extract invalid values and reasons
            invalid_indices = self.np.where(~final_valid_mask)[0]
            invalid_details = []
            
            for idx in invalid_indices[:100]:  # Limit to first 100 for memory
                value = np_values[idx]
                reason = self._determine_invalid_reason(value, rule)
                invalid_details.append({
                    'index': int(idx),
                    'value': float(value) if not self.np.isnan(value) else None,
                    'reason': reason
                })
            
            return {
                'success': valid_count == len(np_values),
                'valid_count': int(valid_count),
                'invalid_count': int(invalid_count),
                'nan_count': int(self.np.sum(nan_mask)),
                'inf_count': int(self.np.sum(inf_mask)),
                'invalid_details': invalid_details,
                'statistics': {
                    'mean': float(self.np.nanmean(np_values)),
                    'std_dev': float(self.np.nanstd(np_values)),
                    'min': float(self.np.nanmin(np_values)),
                    'max': float(self.np.nanmax(np_values))
                }
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': str(e),
                'field_name': field_name
            }
    
    def _determine_invalid_reason(self, value: float, rule: Dict[str, Any]) -> str:
        """Determine reason for invalid value"""
        
        if self.np.isnan(value):
            return "NaN value"
        elif self.np.isinf(value):
            return "Infinite value"
        elif value < rule.get('min_value', -float('inf')):
            return "Below minimum"
        elif value > rule.get('max_value', float('inf')):
            return "Above maximum"
        else:
            return "Unknown reason"
    
    def _process_chunked_batch(self, 
                              values: List[Any], 
                              rules: List[Dict[str, Any]], 
                              field_names: List[str]) -> Dict[str, Any]:
        """Process large batch in chunks"""
        
        chunk_size = self.batch_config['chunk_size']
        chunks = [values[i:i + chunk_size] for i in range(0, len(values), chunk_size)]
        
        results = {
            'success': True,
            'method': 'chunked',
            'field_results': {},
            'batch_metrics': {
                'items_processed': len(values),
                'chunks_processed': len(chunks),
                'chunk_size': chunk_size,
                'processing_time_ms': 0
            }
        }
        
        # Process each chunk
        for i, chunk in enumerate(chunks):
            chunk_result = self._process_standard_batch(chunk, rules, field_names)
            
            # Merge chunk results
            for field_name in field_names:
                if field_name not in results['field_results']:
                    results['field_results'][field_name] = {
                        'success': True,
                        'valid_count': 0,
                        'invalid_count': 0,
                        'chunk_results': []
                    }
                
                field_result = results['field_results'][field_name]
                chunk_field_result = chunk_result['field_results'].get(field_name, {})
                
                field_result['valid_count'] += chunk_field_result.get('valid_count', 0)
                field_result['invalid_count'] += chunk_field_result.get('invalid_count', 0)
                field_result['chunk_results'].append({
                    'chunk_index': i,
                    'chunk_size': len(chunk),
                    'result': chunk_field_result
                })
                
                # Update overall success
                field_result['success'] = field_result['success'] and chunk_field_result.get('success', True)
        
        return results
    
    def _process_standard_batch(self, 
                               values: List[Any], 
                               rules: List[Dict[str, Any]], 
                               field_names: List[str]) -> Dict[str, Any]:
        """Process batch using standard iteration"""
        
        results = {
            'success': True,
            'method': 'standard',
            'field_results': {},
            'batch_metrics': {
                'items_processed': len(values),
                'processing_time_ms': 0
            }
        }
        
        # Process each field
        for rule, field_name in zip(rules, field_names):
            field_result = self._validate_field_batch(values, rule, field_name)
            results['field_results'][field_name] = field_result
            
            # Update overall success
            if not field_result.get('success', True):
                results['success'] = False
        
        return results
    
    def _validate_field_batch(self, 
                             values: List[Any], 
                             rule: Dict[str, Any], 
                             field_name: str) -> Dict[str, Any]:
        """Validate field for entire batch"""
        
        valid_count = 0
        invalid_count = 0
        invalid_details = []
        
        for i, value in enumerate(values):
            try:
                # Simple validation (could be enhanced with existing validators)
                if isinstance(value, (int, float)) and not (math.isnan(value) or math.isinf(value)):
                    min_val = rule.get('min_value', -float('inf'))
                    max_val = rule.get('max_value', float('inf'))
                    
                    if min_val <= value <= max_val:
                        valid_count += 1
                    else:
                        invalid_count += 1
                        invalid_details.append({
                            'index': i,
                            'value': value,
                            'reason': 'Out of range'
                        })
                else:
                    invalid_count += 1
                    invalid_details.append({
                        'index': i,
                        'value': value,
                        'reason': 'Invalid type or NaN/Inf'
                    })
                    
            except Exception as e:
                invalid_count += 1
                invalid_details.append({
                    'index': i,
                    'value': value,
                    'reason': f'Validation error: {str(e)}'
                })
        
        return {
            'success': invalid_count == 0,
            'valid_count': valid_count,
            'invalid_count': invalid_count,
            'invalid_details': invalid_details[:100],  # Limit for memory
            'total_items': len(values)
        }
    
    def process_timing_batch(self, 
                           timestamps: List[Any], 
                           rules: List[Dict[str, Any]], 
                           field_names: List[str]) -> Dict[str, Any]:
        """Process timing validation batch with optimization"""
        
        batch_start = time.time()
        
        # Convert timestamps to datetime objects if needed
        processed_timestamps = []
        for ts in timestamps:
            if isinstance(ts, (int, float)):
                processed_timestamps.append(datetime.fromtimestamp(ts))
            elif isinstance(ts, str):
                try:
                    processed_timestamps.append(datetime.fromisoformat(ts))
                except:
                    processed_timestamps.append(None)
            else:
                processed_timestamps.append(ts)
        
        # Use vectorized processing if available and large enough
        if len(processed_timestamps) >= self.batch_config['vectorization_threshold'] and self.numpy_available:
            return self._process_timing_vectorized(processed_timestamps, rules, field_names)
        else:
            return self._process_timing_standard(processed_timestamps, rules, field_names)
    
    def _process_timing_vectorized(self, 
                                 timestamps: List[datetime], 
                                 rules: List[Dict[str, Any]], 
                                 field_names: List[str]) -> Dict[str, Any]:
        """Process timing batch using vectorized operations"""
        
        try:
            # Convert timestamps to Unix timestamps for vectorization
            unix_timestamps = []
            for ts in timestamps:
                if ts is not None:
                    unix_timestamps.append(ts.timestamp())
                else:
                    unix_timestamps.append(float('nan'))
            
            np_timestamps = self.np.array(unix_timestamps)
            
            results = {
                'success': True,
                'method': 'timing_vectorized',
                'field_results': {},
                'batch_metrics': {
                    'items_processed': len(timestamps),
                    'vectorized_operations': len(rules),
                    'processing_time_ms': 0
                }
            }
            
            # Process each rule vectorized
            for rule, field_name in zip(rules, field_names):
                rule_result = self._apply_timing_vectorized_rule(np_timestamps, rule, field_name)
                results['field_results'][field_name] = rule_result
            
            return results
            
        except Exception as e:
            # Fallback to standard processing
            return self._process_timing_standard(timestamps, rules, field_names)
    
    def _apply_timing_vectorized_rule(self, 
                                     np_timestamps: 'numpy.ndarray', 
                                     rule: Dict[str, Any], 
                                     field_name: str) -> Dict[str, Any]:
        """Apply timing rule using vectorized operations"""
        
        try:
            # Extract min/max timestamps
            min_ts = rule.get('min_value')
            max_ts = rule.get('max_value')
            
            if min_ts is not None:
                min_unix = min_ts.timestamp()
            else:
                min_unix = -float('inf')
            
            if max_ts is not None:
                max_unix = max_ts.timestamp()
            else:
                max_unix = float('inf')
            
            # Vectorized validation
            nan_mask = self.np.isnan(np_timestamps)
            valid_mask = (np_timestamps >= min_unix) & (np_timestamps <= max_unix)
            final_valid_mask = valid_mask & ~nan_mask
            
            valid_count = self.np.sum(final_valid_mask)
            invalid_count = len(np_timestamps) - valid_count
            
            return {
                'success': valid_count == len(np_timestamps),
                'valid_count': int(valid_count),
                'invalid_count': int(invalid_count),
                'nan_count': int(self.np.sum(nan_mask)),
                'statistics': {
                    'earliest': float(self.np.nanmin(np_timestamps)),
                    'latest': float(self.np.nanmax(np_timestamps)),
                    'range_seconds': float(self.np.nanmax(np_timestamps) - self.np.nanmin(np_timestamps))
                }
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': str(e),
                'field_name': field_name
            }
    
    def _process_timing_standard(self, 
                               timestamps: List[datetime], 
                               rules: List[Dict[str, Any]], 
                               field_names: List[str]) -> Dict[str, Any]:
        """Process timing batch using standard iteration"""
        
        results = {
            'success': True,
            'method': 'timing_standard',
            'field_results': {},
            'batch_metrics': {
                'items_processed': len(timestamps),
                'processing_time_ms': 0
            }
        }
        
        for rule, field_name in zip(rules, field_names):
            field_result = self._validate_timing_field_batch(timestamps, rule, field_name)
            results['field_results'][field_name] = field_result
            
            if not field_result.get('success', True):
                results['success'] = False
        
        return results
    
    def _validate_timing_field_batch(self, 
                                   timestamps: List[datetime], 
                                   rule: Dict[str, Any], 
                                   field_name: str) -> Dict[str, Any]:
        """Validate timing field for entire batch"""
        
        valid_count = 0
        invalid_count = 0
        invalid_details = []
        
        min_ts = rule.get('min_value')
        max_ts = rule.get('max_value')
        
        for i, ts in enumerate(timestamps):
            try:
                if ts is None:
                    invalid_count += 1
                    invalid_details.append({
                        'index': i,
                        'value': None,
                        'reason': 'Null timestamp'
                    })
                elif min_ts is not None and ts < min_ts:
                    invalid_count += 1
                    invalid_details.append({
                        'index': i,
                        'value': ts.isoformat(),
                        'reason': 'Before minimum'
                    })
                elif max_ts is not None and ts > max_ts:
                    invalid_count += 1
                    invalid_details.append({
                        'index': i,
                        'value': ts.isoformat(),
                        'reason': 'After maximum'
                    })
                else:
                    valid_count += 1
                    
            except Exception as e:
                invalid_count += 1
                invalid_details.append({
                    'index': i,
                    'value': str(ts),
                    'reason': f'Validation error: {str(e)}'
                })
        
        return {
            'success': invalid_count == 0,
            'valid_count': valid_count,
            'invalid_count': invalid_count,
            'invalid_details': invalid_details[:100],
            'total_items': len(timestamps)
        }
    
    def get_performance_metrics(self) -> Dict[str, Any]:
        """Get performance metrics"""
        
        return {
            'timestamp': datetime.utcnow().isoformat(),
            'batch_config': self.batch_config.copy(),
            'performance_metrics': self.performance_metrics.copy(),
            'cache_stats': {
                'cache_size': len(self.result_cache),
                'cache_hit_rate': (
                    self.performance_metrics['cache_hits'] / 
                    max(self.performance_metrics['cache_hits'] + self.performance_metrics['cache_misses'], 1)
                ) * 100
            },
            'optimization_stats': {
                'vectorization_enabled': self.numpy_available,
                'vectorized_ratio': (
                    self.performance_metrics['vectorized_operations'] / 
                    max(self.performance_metrics['batches_processed'], 1)
                ) * 100,
                'parallel_ratio': (
                    self.performance_metrics['parallel_operations'] / 
                    max(self.performance_metrics['batches_processed'], 1)
                ) * 100
            }
        }
    
    def clear_cache(self) -> None:
        """Clear intermediate result cache"""
        
        with self.cache_lock:
            self.result_cache.clear()
    
    def update_config(self, config_updates: Dict[str, Any]) -> None:
        """Update batch processing configuration"""
        
        self.batch_config.update(config_updates)
        
        # Re-check NumPy availability if enabled/disabled
        if 'use_numpy' in config_updates:
            self.numpy_available = self._check_numpy_availability()


class MemoryOptimizedValidator:
    """Memory-optimized validator for large-scale processing"""
    
    def __init__(self):
        # Memory configuration
        self.memory_config = {
            'max_memory_mb': 1024,              # Maximum memory usage
            'history_retention_limit': 1000,    # Max history items to keep
            'use_database_logging': True,        # Use database for large histories
            'summary_metrics_only': True,        # Store only summary metrics
            'compression_enabled': True,         # Compress stored data
            'cleanup_interval': 100,            # Cleanup every N operations
            'memory_check_interval': 10,         # Check memory every N operations
            'gc_threshold': 0.8                  # Trigger GC at 80% memory usage
        }
        
        # Memory tracking
        self.memory_usage_mb = 0
        self.operation_count = 0
        self.last_cleanup_time = time.time()
        
        # History storage (optimized)
        self.validation_history = deque(maxlen=self.memory_config['history_retention_limit'])
        self.summary_metrics = {}
        
        # Database connection for large-scale storage
        self.db_connection = None
        if self.memory_config['use_database_logging']:
            self._init_database_connection()
    
    def _init_database_connection(self) -> None:
        """Initialize database connection for large-scale storage"""
        
        try:
            import sqlite3
            self.db_connection = sqlite3.connect(':memory:')  # In-memory database
            self._create_database_tables()
        except ImportError:
            self.db_connection = None
            self.memory_config['use_database_logging'] = False
    
    def _create_database_tables(self) -> None:
        """Create database tables for validation history"""
        
        if self.db_connection is None:
            return
        
        cursor = self.db_connection.cursor()
        
        # Create validation history table
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS validation_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp TEXT,
                validation_type TEXT,
                field_name TEXT,
                success BOOLEAN,
                value REAL,
                error_message TEXT,
                metadata TEXT
            )
        ''')
        
        # Create summary metrics table
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS summary_metrics (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp TEXT,
                validation_type TEXT,
                total_validations INTEGER,
                success_count INTEGER,
                failure_count INTEGER,
                avg_processing_time_ms REAL,
                metadata TEXT
            )
        ''')
        
        self.db_connection.commit()
    
    def validate_with_memory_optimization(self, 
                                          validation_type: str,
                                          field_name: str,
                                          value: Any,
                                          rule: Dict[str, Any]) -> Dict[str, Any]:
        """Validate with memory optimization"""
        
        self.operation_count += 1
        
        # Check memory usage periodically
        if self.operation_count % self.memory_config['memory_check_interval'] == 0:
            self._check_memory_usage()
        
        # Perform validation
        start_time = time.time()
        result = self._perform_validation(validation_type, field_name, value, rule)
        processing_time = (time.time() - start_time) * 1000
        
        # Store result with memory optimization
        self._store_result_optimized(result, processing_time)
        
        # Periodic cleanup
        if self.operation_count % self.memory_config['cleanup_interval'] == 0:
            self._perform_cleanup()
        
        return result
    
    def _perform_validation(self, 
                           validation_type: str,
                           field_name: str,
                           value: Any,
                           rule: Dict[str, Any]) -> Dict[str, Any]:
        """Perform the actual validation"""
        
        # Simplified validation logic (would integrate with existing validators)
        try:
            if validation_type == "numeric":
                return self._validate_numeric_optimized(field_name, value, rule)
            elif validation_type == "timing":
                return self._validate_timing_optimized(field_name, value, rule)
            else:
                return {"success": False, "error": f"Unknown validation type: {validation_type}"}
                
        except Exception as e:
            return {"success": False, "error": str(e)}
    
    def _validate_numeric_optimized(self, field_name: str, value: Any, rule: Dict[str, Any]) -> Dict[str, Any]:
        """Optimized numeric validation"""
        
        if not isinstance(value, (int, float)):
            return {"success": False, "error": "Invalid numeric type"}
        
        if math.isnan(value) or math.isinf(value):
            return {"success": False, "error": "NaN or infinite value"}
        
        min_val = rule.get('min_value', -float('inf'))
        max_val = rule.get('max_value', float('inf'))
        
        if min_val <= value <= max_val:
            return {"success": True, "value": value}
        else:
            return {"success": False, "error": "Value out of range"}
    
    def _validate_timing_optimized(self, field_name: str, value: Any, rule: Dict[str, Any]) -> Dict[str, Any]:
        """Optimized timing validation"""
        
        if not isinstance(value, datetime):
            return {"success": False, "error": "Invalid datetime type"}
        
        min_ts = rule.get('min_value')
        max_ts = rule.get('max_value')
        
        if min_ts is not None and value < min_ts:
            return {"success": False, "error": "Timestamp before minimum"}
        
        if max_ts is not None and value > max_ts:
            return {"success": False, "error": "Timestamp after maximum"}
        
        return {"success": True, "value": value.isoformat()}
    
    def _store_result_optimized(self, result: Dict[str, Any], processing_time: float) -> None:
        """Store validation result with memory optimization"""
        
        # Create summary record
        summary_record = {
            'timestamp': datetime.utcnow().isoformat(),
            'success': result.get('success', False),
            'processing_time_ms': processing_time
        }
        
        # Store in deque (limited size)
        self.validation_history.append(summary_record)
        
        # Update summary metrics
        self._update_summary_metrics(summary_record)
        
        # Store in database if enabled and history is large
        if (self.db_connection and 
            len(self.validation_history) >= self.memory_config['history_retention_limit']):
            self._archive_to_database(result, processing_time)
    
    def _update_summary_metrics(self, record: Dict[str, Any]) -> None:
        """Update summary metrics"""
        
        # Simple rolling metrics (could be enhanced)
        current_time = datetime.utcnow().isoformat()[:16]  # YYYY-MM-DD HH:MM
        
        if current_time not in self.summary_metrics:
            self.summary_metrics[current_time] = {
                'total_validations': 0,
                'success_count': 0,
                'failure_count': 0,
                'total_processing_time_ms': 0
            }
        
        metrics = self.summary_metrics[current_time]
        metrics['total_validations'] += 1
        metrics['total_processing_time_ms'] += record['processing_time_ms']
        
        if record['success']:
            metrics['success_count'] += 1
        else:
            metrics['failure_count'] += 1
    
    def _archive_to_database(self, result: Dict[str, Any], processing_time: float) -> None:
        """Archive validation result to database"""
        
        if self.db_connection is None:
            return
        
        try:
            cursor = self.db_connection.cursor()
            
            # Insert validation record
            cursor.execute('''
                INSERT INTO validation_history 
                (timestamp, validation_type, field_name, success, error_message, metadata)
                VALUES (?, ?, ?, ?, ?, ?)
            ''', (
                datetime.utcnow().isoformat(),
                result.get('validation_type', 'unknown'),
                result.get('field_name', 'unknown'),
                result.get('success', False),
                result.get('error', ''),
                json.dumps({'processing_time_ms': processing_time})
            ))
            
            self.db_connection.commit()
            
        except Exception as e:
            # Log error but don't fail validation
            pass
    
    def _check_memory_usage(self) -> None:
        """Check current memory usage"""
        
        try:
            import psutil
            process = psutil.Process()
            self.memory_usage_mb = process.memory_info().rss / 1024 / 1024
            
            # Trigger cleanup if memory usage is high
            if self.memory_usage_mb > self.memory_config['max_memory_mb'] * self.memory_config['gc_threshold']:
                self._perform_cleanup()
                import gc
                gc.collect()
                
        except ImportError:
            # Fallback: estimate memory usage based on operation count
            estimated_memory = self.operation_count * 0.001  # Rough estimate
            if estimated_memory > self.memory_config['max_memory_mb'] * self.memory_config['gc_threshold']:
                self._perform_cleanup()
    
    def _perform_cleanup(self) -> None:
        """Perform memory cleanup"""
        
        # Clear old summary metrics (keep only recent)
        current_time = datetime.utcnow()
        cutoff_time = current_time - timedelta(hours=1)
        
        keys_to_remove = []
        for timestamp_key in self.summary_metrics.keys():
            try:
                key_time = datetime.strptime(timestamp_key, '%Y-%m-%d %H:%M')
                if key_time < cutoff_time:
                    keys_to_remove.append(timestamp_key)
            except:
                keys_to_remove.append(timestamp_key)
        
        for key in keys_to_remove:
            del self.summary_metrics[key]
        
        # Clear database if it's getting large
        if self.db_connection:
            try:
                cursor = self.db_connection.cursor()
                # Keep only last 10000 records
                cursor.execute('''
                    DELETE FROM validation_history 
                    WHERE id NOT IN (
                        SELECT id FROM validation_history 
                        ORDER BY id DESC LIMIT 10000
                    )
                ''')
                self.db_connection.commit()
            except:
                pass
        
        self.last_cleanup_time = time.time()
    
    def get_memory_usage_report(self) -> Dict[str, Any]:
        """Get comprehensive memory usage report"""
        
        return {
            'timestamp': datetime.utcnow().isoformat(),
            'current_memory_mb': self.memory_usage_mb,
            'max_memory_mb': self.memory_config['max_memory_mb'],
            'memory_utilization_percent': (
                self.memory_usage_mb / self.memory_config['max_memory_mb'] * 100
            ),
            'operation_count': self.operation_count,
            'history_size': len(self.validation_history),
            'summary_metrics_count': len(self.summary_metrics),
            'database_enabled': self.db_connection is not None,
            'last_cleanup_time': self.last_cleanup_time,
            'memory_config': self.memory_config.copy()
        }
    
    def get_summary_metrics(self, time_window_hours: int = 1) -> Dict[str, Any]:
        """Get summary metrics for time window"""
        
        cutoff_time = datetime.utcnow() - timedelta(hours=time_window_hours)
        
        filtered_metrics = {}
        for timestamp_key, metrics in self.summary_metrics.items():
            try:
                key_time = datetime.strptime(timestamp_key, '%Y-%m-%d %H:%M')
                if key_time >= cutoff_time:
                    filtered_metrics[timestamp_key] = metrics
            except:
                continue
        
        # Calculate aggregates
        total_validations = sum(m['total_validations'] for m in filtered_metrics.values())
        total_success = sum(m['success_count'] for m in filtered_metrics.values())
        total_failures = sum(m['failure_count'] for m in filtered_metrics.values())
        total_processing_time = sum(m['total_processing_time_ms'] for m in filtered_metrics.values())
        
        return {
            'time_window_hours': time_window_hours,
            'total_validations': total_validations,
            'success_count': total_success,
            'failure_count': total_failures,
            'success_rate': (total_success / total_validations * 100) if total_validations > 0 else 0,
            'average_processing_time_ms': (total_processing_time / total_validations) if total_validations > 0 else 0,
            'data_points': len(filtered_metrics)
        }


# Global performance optimization instances
batch_optimizer = BatchProcessingOptimizer()
memory_validator = MemoryOptimizedValidator()

class EnhancedMicrosecondValidator:
    """Enhanced microsecond validator with memory optimization for massive streams"""
    
