@dataclass
class PlatformConfig:
    """Platform-specific configuration from config management"""
    platform: str
    preferred_sample_rate: int
    max_retries: int
    backoff_base: float
    timeout_seconds: int
    quality_preset: str  # fast, balanced, quality
    memory_limit_mb: int
    cpu_limit_cores: float
    enabled_codecs: List[str]
    storage_class: str  # standard, premium, archive
    
    @classmethod
    def from_dict(cls, platform: str, config: Dict[str, Any]) -> 'PlatformConfig':
        return cls(
            platform=platform,
            preferred_sample_rate=config.get('preferred_sample_rate', 44100),
            max_retries=config.get('max_retries', 3),
            backoff_base=config.get('backoff_base', 2.0),
            timeout_seconds=config.get('timeout_seconds', 300),
            quality_preset=config.get('quality_preset', 'balanced'),
            memory_limit_mb=config.get('memory_limit_mb', 1024),
            cpu_limit_cores=config.get('cpu_limit_cores', 1.0),
            enabled_codecs=config.get('enabled_codecs', ['aac', 'mp3', 'wav']),
            storage_class=config.get('storage_class', 'standard')
        )


class StorageBackend:
    """Abstract storage backend for cloud storage integration"""
    
    def upload_atomic(self, local_path: Path, remote_path: str, metadata: Dict[str, Any]) -> bool:
        """Atomically upload file with metadata verification"""
        raise NotImplementedError
    
    def download(self, remote_path: str, local_path: Path) -> bool:
        """Download file from remote storage"""
        raise NotImplementedError
    
    def exists(self, remote_path: str) -> bool:
        """Check if file exists in remote storage"""
        raise NotImplementedError
    
    def get_metadata(self, remote_path: str) -> Optional[Dict[str, Any]]:
        """Get file metadata"""
        raise NotImplementedError


class LocalBackend(StorageBackend):
    """Local filesystem backend for development/testing"""
    
    def __init__(self, base_path: Path):
        self.base_path = Path(base_path)
        self.base_path.mkdir(parents=True, exist_ok=True)
    
    def upload_atomic(self, local_path: Path, remote_path: str, metadata: Dict[str, Any]) -> bool:
        """Copy file locally with metadata"""
        try:
            dest_path = self.base_path / remote_path
            dest_path.parent.mkdir(parents=True, exist_ok=True)
            
            # Copy file
            shutil.copy2(local_path, dest_path)
            
            # Save metadata separately
            metadata_path = dest_path.with_suffix('.metadata.json')
            with open(metadata_path, 'w') as f:
                json.dump(metadata, f, indent=2)
            
            return True
        except Exception as e:
            logger.error(f"Local upload failed: {e}")
            return False
    
    def download(self, remote_path: str, local_path: Path) -> bool:
        """Copy file locally"""
        try:
            src_path = self.base_path / remote_path
            shutil.copy2(src_path, local_path)
            return True
        except Exception as e:
            logger.error(f"Local download failed: {e}")
            return False
    
    def exists(self, remote_path: str) -> bool:
        """Check if file exists locally"""
        return (self.base_path / remote_path).exists()
    
    def get_metadata(self, remote_path: str) -> Optional[Dict[str, Any]]:
        """Get file metadata"""
        try:
            metadata_path = self.base_path / f"{remote_path}.metadata.json"
            with open(metadata_path, 'r') as f:
                return json.load(f)
        except Exception as e:
            logger.warning(f"Failed to get metadata for {remote_path}: {e}")
            return None

# Try to import cloud storage backends (optional dependencies)
try:
    from google.cloud import storage as gcs
    from google.auth import default
    
    class GCSBackend(StorageBackend):
        """Google Cloud Storage backend with atomic writes and metadata verification"""
        
        def __init__(self, bucket_name: str):
            self.bucket_name = bucket_name
            self.client = gcs.Client()
            self.bucket = self.client.bucket(bucket_name)
            # GOOGLE-LEVEL: Atomic upload locking
            self._upload_locks: Dict[str, threading.Lock] = {}
            self._lock_timeout = ATOMIC_RENAME_TIMEOUT
        
        def _get_upload_lock(self, remote_path: str) -> threading.Lock:
            """Get or create upload lock for specific remote path"""
            if remote_path not in self._upload_locks:
                self._upload_locks[remote_path] = threading.Lock()
            return self._upload_locks[remote_path]
        
        def _acquire_upload_lock(self, remote_path: str, timeout: Optional[float] = None) -> bool:
            """Acquire upload lock with timeout"""
            lock = self._get_upload_lock(remote_path)
            timeout = timeout or self._lock_timeout
            
            try:
                return lock.acquire(timeout=timeout)
            except Exception as e:
                logger.error(f"Failed to acquire upload lock for {remote_path}: {e}")
                return False
        
        def _release_upload_lock(self, remote_path: str) -> None:
            """Release upload lock"""
            lock = self._get_upload_lock(remote_path)
            try:
                lock.release()
            except Exception as e:
                logger.warning(f"Failed to release upload lock for {remote_path}: {e}")
        
        def upload_atomic(self, local_path: Path, remote_path: str, metadata: Dict[str, Any]) -> bool:
            """Atomically upload file with metadata verification and proper locking"""
            upload_lock = self._get_upload_lock(remote_path)
            
            # Acquire lock for this specific upload path
            if not self._acquire_upload_lock(remote_path):
                logger.error(f"Failed to acquire upload lock for {remote_path} - upload may be in progress")
                return False
            
            try:
                # Check if file already exists (avoid race conditions)
                if self.exists(remote_path):
                    logger.warning(f"Target file already exists: {remote_path} - skipping upload")
                    return True
                
                # Upload to temporary location first
                temp_path = f"{remote_path}.tmp.{uuid.uuid4().hex}"
                blob = self.bucket.blob(temp_path)
                
                # Upload with metadata
                blob.metadata = {
                    'build_hash': BUILD_HASH,
                    'ffmpeg_version': FFMPEG_VERSION,
                    'upload_timestamp': datetime.now(timezone.utc).isoformat(),
                    'immutable_build_id': IMMUTABLE_BUILD_ID,
                    'upload_id': uuid.uuid4().hex,
                    **metadata
                }
                
                blob.upload_from_filename(str(local_path))
                
                # Verify upload integrity
                if not self._verify_upload_integrity(temp_path, local_path):
                    logger.error(f"Upload integrity verification failed for {temp_path}")
                    blob.delete()  # Clean up temp file
                    return False
                
                # Atomic rename with verification
                if not self._atomic_rename_with_verification(temp_path, remote_path):
                    logger.error(f"Atomic rename failed for {temp_path} -> {remote_path}")
                    blob.delete()  # Clean up temp file
                    return False
                
                logger.info(f"Atomically uploaded {local_path.name} to gs://{self.bucket_name}/{remote_path}")
                return True
                
            except Exception as e:
                logger.error(f"GCS upload failed: {e}")
                # Clean up temp file on error
                try:
                    temp_blob = self.bucket.blob(f"{remote_path}.tmp.{uuid.uuid4().hex}")
                    if temp_blob.exists():
                        temp_blob.delete()
                except:
                    pass
                return False
            finally:
                # Always release the lock
                self._release_upload_lock(remote_path)
        
        def _verify_upload_integrity(self, remote_path: str, local_path: Path) -> bool:
            """Verify uploaded file integrity against local file"""
            try:
                # Get remote blob metadata
                blob = self.bucket.blob(remote_path)
                if not blob.exists():
                    return False
                
                # Calculate local file hash
                local_hash = self._calculate_file_hash(local_path)
                
                # Get remote file hash (if available in metadata)
                remote_hash = blob.metadata.get('file_hash') if blob.metadata else None
                
                if remote_hash and remote_hash != local_hash:
                    logger.error(f"Hash mismatch: local={local_hash}, remote={remote_hash}")
                    return False
                
                # Verify file size
                local_size = local_path.stat().st_size
                remote_size = blob.size
                
                if local_size != remote_size:
                    logger.error(f"Size mismatch: local={local_size}, remote={remote_size}")
                    return False
                
                return True
                
            except Exception as e:
                logger.error(f"Upload integrity verification failed: {e}")
                return False
        
        def _atomic_rename_with_verification(self, temp_path: str, target_path: str) -> bool:
            """Perform atomic rename with verification"""
            try:
                temp_blob = self.bucket.blob(temp_path)
                target_blob = self.bucket.blob(target_path)
                
                # Check if target already exists (shouldn't happen with locking)
                if target_blob.exists():
                    logger.warning(f"Target already exists during rename: {target_path}")
                    return False
                
                # Copy to target location
                self.bucket.copy_blob(temp_blob, self.bucket, target_path)
                
                # Verify copy succeeded
                if not target_blob.exists():
                    logger.error(f"Target blob does not exist after copy: {target_path}")
                    return False
                
                # Delete temporary file
                temp_blob.delete()
                
                # Final verification
                if not target_blob.exists():
                    logger.error(f"Target blob disappeared after temp cleanup: {target_path}")
                    return False
                
                return True
                
            except Exception as e:
                logger.error(f"Atomic rename failed: {e}")
                return False
        
        def _calculate_file_hash(self, file_path: Path) -> str:
            """Calculate SHA256 hash of local file"""
            import hashlib
            
            hasher = hashlib.sha256()
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    hasher.update(chunk)
            return hasher.hexdigest()
        
        def download(self, remote_path: str, local_path: Path) -> bool:
            """Download file from remote storage"""
            try:
                blob = self.bucket.blob(remote_path)
                blob.download_to_filename(str(local_path))
                return True
            except Exception as e:
                logger.error(f"GCS download failed: {e}")
                return False
        
        def exists(self, remote_path: str) -> bool:
            """Check if file exists in remote storage"""
            try:
                blob = self.bucket.blob(remote_path)
                return blob.exists()
            except Exception as e:
                logger.warning(f"GCS exists check failed for {remote_path}: {e}")
                return False
        
        def get_metadata(self, remote_path: str) -> Optional[Dict[str, Any]]:
            """Get file metadata"""
            try:
                blob = self.bucket.blob(remote_path)
                blob.reload()
                return blob.metadata
            except Exception as e:
                logger.warning(f"GCS metadata retrieval failed for {remote_path}: {e}")
                return None
    
    GCS_AVAILABLE = True
except ImportError:
    GCS_AVAILABLE = False
    logger.warning("Google Cloud Storage not available - install google-cloud-storage")

