class TelemetryHTTPHandler(BaseHTTPRequestHandler):
    """HTTP handler for health checks and metrics endpoints"""
    
    # Global reference to extractor instance for health checks
    extractor_instance = None
    
    def __init__(self, *args, **kwargs):
        self.extractor = TelemetryHTTPHandler.extractor_instance
        super().__init__(*args, **kwargs)
    
    def do_GET(self):
        """Handle GET requests"""
        if self.path == '/healthz':
            self._handle_healthz()
        elif self.path == '/metrics':
            self._handle_metrics()
        elif self.path == '/health':
            self._handle_health()
        else:
            self._send_404()
    
    def _handle_healthz(self):
        """Handle /healthz endpoint with comprehensive liveness checks"""
        try:
            health_status = self._check_health()
            
            if health_status['healthy']:
                response = {
                    'status': 'healthy',
                    'timestamp': datetime.utcnow().isoformat(),
                    'version': EXTRACTOR_VERSION,
                    'commit': EXTRACTOR_COMMIT,
                    'build': EXTRACTOR_BUILD,
                    'checks': health_status['checks']
                }
                self._send_json(200, response)
            else:
                response = {
                    'status': 'unhealthy',
                    'timestamp': datetime.utcnow().isoformat(),
                    'version': EXTRACTOR_VERSION,
                    'commit': EXTRACTOR_COMMIT,
                    'build': EXTRACTOR_BUILD,
                    'checks': health_status['checks'],
                    'errors': health_status['errors']
                }
                self._send_json(503, response)
                
        except Exception as e:
            logger.error(f"Health check failed: {e}")
            self._send_json(503, {
                'status': 'unhealthy',
                'timestamp': datetime.utcnow().isoformat(),
                'error': str(e)
            })
    
    def _handle_health(self):
        """Handle legacy /health endpoint"""
        try:
            health_status = self._check_health()
            if health_status['healthy']:
                self._send_json(200, {'status': 'ok'})
            else:
                self._send_json(503, {'status': 'error'})
        except Exception as e:
            logger.error(f"Health check failed: {e}")
            self._send_json(503, {'status': 'error', 'error': str(e)})
    
    def _handle_metrics(self):
        """Handle /metrics endpoint with Prometheus metrics"""
        try:
            if PROMETHEUS_AVAILABLE:
                # Get the latest Prometheus metrics
                from prometheus_client import generate_latest, CONTENT_TYPE_LATEST
                metrics_data = generate_latest()
                self._send_response(200, metrics_data, CONTENT_TYPE_LATEST)
            else:
                # Fallback to structured metrics
                if self.extractor and hasattr(self.extractor, '_metrics'):
                    metrics = self.extractor._metrics
                    self._send_json(200, {
                        'timestamp': datetime.utcnow().isoformat(),
                        'metrics': {
                            'success_count': metrics.get('success', 0),
                            'failure_count': metrics.get('failure', 0),
                            'avg_duration_ms': sum(metrics.get('durations_ms', [])) / len(metrics.get('durations_ms', [1])),
                            'avg_sync_offset_ms': sum(metrics.get('sync_offsets_ms', [])) / len(metrics.get('sync_offsets_ms', [1])),
                            'recent_checksum_mismatches': sum(metrics.get('checksum_mismatches', []))
                        }
                    })
                else:
                    self._send_json(200, {'metrics': {}})
        except Exception as e:
            logger.error(f"Metrics endpoint failed: {e}")
            self._send_json(500, {'error': str(e)})
    
    def _check_health(self) -> Dict[str, Any]:
        """Perform comprehensive health checks"""
        checks = {}
        errors = []
        healthy = True
        
        # Check 1: FFmpeg availability
        try:
            result = subprocess.run(['ffmpeg', '-version'], capture_output=True, text=True, timeout=5)
            if result.returncode == 0:
                checks['ffmpeg'] = {'status': 'healthy', 'version': result.stdout.split('\n')[0]}
            else:
                checks['ffmpeg'] = {'status': 'unhealthy', 'error': 'FFmpeg not responding'}
                errors.append('FFmpeg not responding')
                healthy = False
        except Exception as e:
            checks['ffmpeg'] = {'status': 'unhealthy', 'error': str(e)}
            errors.append(f'FFmpeg check failed: {e}')
            healthy = False
        
        # Check 2: Disk space
        try:
            disk_usage = psutil.disk_usage('/')
            free_percent = (disk_usage.free / disk_usage.total) * 100
            if free_percent < 5:  # Less than 5% free
                checks['disk_space'] = {'status': 'unhealthy', 'free_percent': free_percent}
                errors.append(f'Low disk space: {free_percent:.1f}%')
                healthy = False
            else:
                checks['disk_space'] = {'status': 'healthy', 'free_percent': free_percent}
        except Exception as e:
            checks['disk_space'] = {'status': 'unknown', 'error': str(e)}
        
        # Check 3: Memory usage
        try:
            memory = psutil.virtual_memory()
            if memory.percent > 95:  # More than 95% memory usage
                checks['memory'] = {'status': 'unhealthy', 'usage_percent': memory.percent}
                errors.append(f'High memory usage: {memory.percent:.1f}%')
                healthy = False
            else:
                checks['memory'] = {'status': 'healthy', 'usage_percent': memory.percent}
        except Exception as e:
            checks['memory'] = {'status': 'unknown', 'error': str(e)}
        
        # Check 4: Extractor-specific health
        if self.extractor:
            try:
                # Check if extractor is responsive
                active_extractions = getattr(self.extractor, 'active_extractions', 0)
                max_concurrent = getattr(self.extractor, 'max_workers', MAX_CONCURRENT_EXTRACTIONS)
                
                if active_extractions >= max_concurrent:
                    checks['extractor'] = {'status': 'warning', 'active_extractions': active_extractions, 'max_concurrent': max_concurrent}
                else:
                    checks['extractor'] = {'status': 'healthy', 'active_extractions': active_extractions, 'max_concurrent': max_concurrent}
                
                # Check recent failure rate
                if hasattr(self.extractor, '_metrics'):
                    metrics = self.extractor._metrics
                    total = metrics.get('success', 0) + metrics.get('failure', 0)
                    if total >= 10:  # Only check if we have enough samples
                        failure_rate = metrics.get('failure', 0) / total
                        if failure_rate > 0.5:  # More than 50% failure rate
                            checks['extractor']['status'] = 'unhealthy'
                            checks['extractor']['failure_rate'] = failure_rate
                            errors.append(f'High failure rate: {failure_rate:.1%}')
                            healthy = False
            except Exception as e:
                checks['extractor'] = {'status': 'unknown', 'error': str(e)}
        else:
            checks['extractor'] = {'status': 'unknown', 'error': 'No extractor instance'}
        
        return {
            'healthy': healthy,
            'checks': checks,
            'errors': errors
        }
    
    def _send_json(self, status_code: int, data: Dict[str, Any]):
        """Send JSON response"""
        json_data = json.dumps(data, indent=2)
        self._send_response(status_code, json_data.encode('utf-8'), 'application/json')
    
    def _send_response(self, status_code: int, content: bytes, content_type: str):
        """Send HTTP response"""
        self.send_response(status_code)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(content)))
        self.end_headers()
        self.wfile.write(content)
    
    def _send_404(self):
        """Send 404 response"""
        self._send_json(404, {'error': 'Not found'})
    
    def log_message(self, format, *args):
        """Override to reduce log noise"""
        # Only log errors, not normal health checks
        if 'ERROR' in format or 'error' in format.lower():
            logger.info(f"Telemetry HTTP: {format % args}")

class TelemetryHTTPServer:
    """HTTP server for telemetry endpoints"""
    
    def __init__(self, host: str = TELEMETRY_HTTP_HOST, port: int = TELEMETRY_HTTP_PORT):
        self.host = host
        self.port = port
        self.server = None
        self.server_thread = None
        self.running = False
    
    def start(self, extractor_instance=None):
        """Start the telemetry HTTP server"""
        if not TELEMETRY_HTTP_ENABLED:
            logger.info("Telemetry HTTP server disabled")
            return
        
        try:
            # Set the global extractor reference
            TelemetryHTTPHandler.extractor_instance = extractor_instance
            
            # Create server
            self.server = ThreadingHTTPServer((self.host, self.port), TelemetryHTTPHandler)
            self.running = True
            
            # Start in separate thread
            self.server_thread = threading.Thread(target=self._run_server, daemon=True)
            self.server_thread.start()
            
            logger.info(f"Telemetry HTTP server started on http://{self.host}:{self.port}")
            logger.info(f"  Health check: http://{self.host}:{self.port}/healthz")
            logger.info(f"  Metrics: http://{self.host}:{self.port}/metrics")
            
        except Exception as e:
            logger.error(f"Failed to start telemetry HTTP server: {e}")
            self.running = False
    
    def stop(self):
        """Stop the telemetry HTTP server"""
        if self.server and self.running:
            try:
                self.server.shutdown()
                self.server.server_close()
                self.running = False
                logger.info("Telemetry HTTP server stopped")
            except Exception as e:
                logger.error(f"Error stopping telemetry HTTP server: {e}")
    
    def _run_server(self):
        """Run the server loop"""
        try:
            self.server.serve_forever()
        except Exception as e:
            logger.error(f"Telemetry HTTP server error: {e}")
        finally:
            self.running = False

# Global telemetry server instance
telemetry_server = TelemetryHTTPServer()

# ============================================================================
# GOOGLE-LEVEL: DISTRIBUTED LOCKING & QUEUEING
# ============================================================================

class DistributedLock:
    """Google-level distributed locking for multi-node deployments"""
    
    def __init__(self, resource_key: str, backend: str = DISTRIBUTED_LOCK_BACKEND):
        self.resource_key = resource_key
        self.backend = backend
        self.lock_acquired = False
        
    def __enter__(self):
        if self.backend == "redis":
            return self._redis_lock()
        elif self.backend == "file":
            return self._file_lock()
        else:
            raise AudioExtractionError(f"Unsupported lock backend: {self.backend}")
    
    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.lock_acquired:
            self._release_lock()
    
    def _file_lock(self) -> 'DistributedLock':
        """Fallback file-based locking for single-node deployments with stale lock cleanup"""
        lock_file = Path(f"/tmp/audio_extractor_{self.resource_key}.lock")
        
        # CRITICAL: Check for and clean up stale locks
        self._cleanup_stale_lock(lock_file)
        
        try:
            fd = os.open(lock_file, os.O_CREAT | os.O_WRONLY | os.O_EXCL)
            fcntl.flock(fd, fcntl.LOCK_EX)
            self.lock_acquired = True
            self._lock_fd = fd
            
            # Write lock metadata for stale detection
            lock_info = {
                "pid": os.getpid(),
                "hostname": socket.gethostname(),
                "timestamp": time.time(),
                "resource_key": self.resource_key
            }
            with os.fdopen(fd, 'w') as f:
                f.write(json.dumps(lock_info))
            
            return self
        except OSError:
            raise AudioExtractionError(f"Could not acquire lock for {self.resource_key}")
    
    def _redis_lock(self) -> 'DistributedLock':
        """Redis-based distributed locking for multi-node deployments"""
        try:
            import redis
            r = redis.Redis(host=os.getenv('REDIS_HOST', 'localhost'), 
                          port=int(os.getenv('REDIS_PORT', 6379)),
                          db=int(os.getenv('REDIS_DB', 0)))
            
            # Try to acquire lock with timeout
            lock_acquired = r.set(f"lock:{self.resource_key}", 
                               os.getpid(), 
                               nx=True, 
                               ex=IDEMPOTENCY_LOCK_TIMEOUT)
            
            if lock_acquired:
                self.lock_acquired = True
                self._redis_client = r
                return self
            else:
                raise AudioExtractionError(f"Could not acquire Redis lock for {self.resource_key}")
                
        except ImportError:
            raise AudioExtractionError("Redis not available for distributed locking")
    
    def _release_lock(self) -> None:
        if self.backend == "redis" and hasattr(self, '_redis_client'):
            self._redis_client.delete(f"lock:{self.resource_key}")
        elif self.backend == "file" and hasattr(self, '_lock_fd'):
            fcntl.flock(self._lock_fd, fcntl.LOCK_UN)
            os.close(self._lock_fd)
            
            # CRITICAL: Clean up lock file after release
            lock_file = Path(f"/tmp/audio_extractor_{self.resource_key}.lock")
            try:
                lock_file.unlink(missing_ok=True)
            except OSError:
                pass  # Best effort cleanup
    
    def _cleanup_stale_lock(self, lock_file: Path) -> None:
        """Clean up stale lock files from dead processes"""
        if not lock_file.exists():
            return
            
        try:
            # Read lock metadata
            with open(lock_file, 'r') as f:
                lock_info = json.loads(f.read())
            
            # Check if process is still alive
            pid = lock_info.get("pid")
            hostname = lock_info.get("hostname")
            timestamp = lock_info.get("timestamp", 0)
            
            # Check if lock is stale (older than 5 minutes or process dead)
            is_stale = False
            
            # Check age
            if time.time() - timestamp > 300:  # 5 minutes
                is_stale = True
                logger.warning(f"Found stale lock file (age: {time.time() - timestamp:.1f}s): {lock_file}")
            
            # Check if process is still alive
            if not is_stale and pid and hostname == socket.gethostname():
                try:
                    # Send signal 0 to check if process exists
                    os.kill(pid, 0)
                except OSError:
                    # Process doesn't exist
                    is_stale = True
                    logger.warning(f"Found stale lock file (dead PID {pid}): {lock_file}")
            
            # Clean up stale lock
            if is_stale:
                try:
                    # Try to remove the stale lock file
                    lock_file.unlink()
                    logger.info(f"Cleaned up stale lock file: {lock_file}")
                except OSError as e:
                    # If we can't remove it, at least log the issue
                    logger.error(f"Failed to clean up stale lock file {lock_file}: {e}")
                    
        except (json.JSONDecodeError, KeyError, OSError) as e:
            # If we can't read the lock file, it might be corrupted
            logger.warning(f"Corrupted or unreadable lock file {lock_file}: {e}")
            try:
                lock_file.unlink()
                logger.info(f"Cleaned up corrupted lock file: {lock_file}")
            except OSError:
                pass

@dataclass
class JobQueue:
    """Google-level distributed job queue"""
    
    def __init__(self, backend: str = "memory"):
        self.backend = backend
        self.pending_jobs = []
        self.processing_jobs = set()
        self.completed_jobs = []
        self.active_jobs = set()
        self.failed_jobs = set()
        
        # Concurrency safety
        self._queue_lock = asyncio.Lock()
        self._stats_lock = asyncio.Lock()
        
    async def add_job(self, metadata: VideoMetadata) -> str:
        """Add job to queue with unique ID - thread-safe"""
        async with self._queue_lock:
            job_id = str(uuid.uuid4())
            job = {
                'job_id': job_id,
                'metadata': metadata,
                'queued_at': datetime.now(timezone.utc).isoformat(),
                'status': 'pending'
            }
            
            if self.backend == "redis":
                await self._redis_add_job(job)
            else:
                self.pending_jobs.append(job)
                
            QUEUE_DEPTH_GAUGE.set(len(self.pending_jobs))
            return job_id
    
    async def get_next_job(self) -> Optional[Dict[str, Any]]:
        """Get next job from queue - thread-safe"""
        async with self._queue_lock:
            if self.backend == "redis":
                return await self._redis_get_job()
            else:
                for job in self.pending_jobs:
                    if job['job_id'] not in self.processing_jobs:
                        job['status'] = 'processing'
                        self.processing_jobs.add(job['job_id'])
                        self.active_jobs.add(job['job_id'])
                        return job
                return None
    
    async def complete_job(self, job_id: str, result: ExtractionResult) -> None:
        """Mark job as completed - thread-safe"""
        async with self._queue_lock:
            if self.backend == "redis":
                await self._redis_complete_job(job_id, result)
            else:
                self.processing_jobs.discard(job_id)
                # Move from pending to completed
                self.pending_jobs = [j for j in self.pending_jobs if j['job_id'] != job_id]
                self.completed_jobs.append({
                    'job_id': job_id,
                    'result': result,
                    'completed_at': datetime.now(timezone.utc).isoformat()
                })
            
            # Update tracking sets
            self.active_jobs.discard(job_id)
            if result.success:
                self.completed_jobs.add(job_id)
            else:
                self.failed_jobs.add(job_id)
                
            QUEUE_DEPTH_GAUGE.set(len(self.pending_jobs))
        
    async def _redis_add_job(self, job: Dict[str, Any]) -> None:
        """Redis-based job addition using aioredis"""
        try:
            import aioredis
            r = await aioredis.from_url(
                f"redis://{os.getenv('REDIS_HOST', 'localhost')}:{int(os.getenv('REDIS_PORT', 6379))}/{int(os.getenv('REDIS_DB', 0))}"
            )
            await r.lpush("audio_extraction_queue", json.dumps(job))
            await r.close()
        except Exception as e:
            logger.error(f"Redis job addition failed: {e}")
            
    async def _redis_get_job(self) -> Optional[Dict[str, Any]]:
        """Redis-based job retrieval using aioredis"""
        try:
            import aioredis
            r = await aioredis.from_url(
                f"redis://{os.getenv('REDIS_HOST', 'localhost')}:{int(os.getenv('REDIS_PORT', 6379))}/{int(os.getenv('REDIS_DB', 0))}"
            )
            job_data = await r.brpop("audio_extraction_queue", timeout=1)
            await r.close()
            if job_data:
                return json.loads(job_data[1])
            return None
        except Exception as e:
            logger.error(f"Redis job retrieval failed: {e}")
            return None
            
    async def _redis_complete_job(self, job_id: str, result: ExtractionResult) -> None:
        """Redis-based job completion using aioredis"""
        try:
            import aioredis
            r = await aioredis.from_url(
                f"redis://{os.getenv('REDIS_HOST', 'localhost')}:{int(os.getenv('REDIS_PORT', 6379))}/{int(os.getenv('REDIS_DB', 0))}"
            )
            completion_data = {
                "job_id": job_id,
                "worker_id": getattr(self, 'worker_id', 'unknown'),
                "status": "completed" if result.success else "failed",
                "completed_at": datetime.utcnow().isoformat(),
                "result": {
                    "success": result.success,
                    "duration_ms": result.duration_ms,
                    "retry_count": result.retry_count,
                    "error": str(result.error) if result.error else None
                }
            }
            # Store completion in Redis for monitoring
            await r.lpush("audio_extraction_completed", json.dumps(completion_data))
            await r.close()
        except Exception as e:
            logger.error(f"Redis job completion failed: {e}")
    
    async def get_queue_stats(self) -> Dict[str, Any]:
        """Get queue statistics for monitoring"""
        try:
            if self.backend_type == "redis":
                stats = await self._redis_queue_stats()
            elif self.backend_type == "etcd":
                stats = await self._etcd_queue_stats()
            elif self.backend_type == "consul":
                stats = await self._consul_queue_stats()
            
            # Add worker-specific stats
            stats.update({
                "worker_id": self.worker_id,
                "active_jobs": len(self.active_jobs),
                "completed_jobs": len(self.completed_jobs),
                "failed_jobs": len(self.failed_jobs)
            })
            
            return stats
            
        except Exception as e:
            logger.error(f"Failed to get queue stats: {e}")
            return {}
    
    # Backend-specific implementations (simplified for brevity)
    async def _redis_enqueue(self, job_data: Dict[str, Any], priority: int) -> None:
        """Redis enqueue using sorted set for priority"""
        import asyncio
        loop = asyncio.get_event_loop()
        await loop.run_in_executor(
            None, 
            lambda: self.backend.zadd(self.priority_queue_name, {json.dumps(job_data): -priority})
        )
    
    async def _redis_dequeue(self, timeout: int) -> Optional[Dict[str, Any]]:
        """Redis dequeue with timeout"""
        import asyncio
        loop = asyncio.get_event_loop()
        
        # Get highest priority job (lowest score)
        result = await loop.run_in_executor(
            None,
            lambda: self.backend.zpopmin(self.priority_queue_name, count=1)
        )
        
        if result:
            job_json = result[0][0]  # Get job data from tuple
            return json.loads(job_json)
        return None
    
    async def _redis_complete_job(self, completion_data: Dict[str, Any]) -> None:
        """Redis job completion"""
        import asyncio
        loop = asyncio.get_event_loop()
        await loop.run_in_executor(
            None,
            lambda: self.backend.hset(
                f"completed_jobs:{completion_data['job_id']}",
                mapping=completion_data
            )
        )
    
    async def _redis_queue_stats(self) -> Dict[str, Any]:
        """Redis queue statistics"""
        import asyncio
        loop = asyncio.get_event_loop()
        
        queue_size = await loop.run_in_executor(
            None, lambda: self.backend.zcard(self.priority_queue_name)
        )
        
        return {
            "backend": "redis",
            "queue_size": queue_size,
            "queue_name": self.priority_queue_name
        }
    
    # Placeholder methods for etcd and consul (would be implemented similarly)
    async def _etcd_enqueue(self, job_data: Dict[str, Any], priority: int) -> None:
        """etcd enqueue implementation"""
        pass
    
    async def _etcd_dequeue(self, timeout: int) -> Optional[Dict[str, Any]]:
        """etcd dequeue implementation"""
        pass
    
    async def _etcd_complete_job(self, completion_data: Dict[str, Any]) -> None:
        """etcd job completion"""
        pass
    
    async def _etcd_queue_stats(self) -> Dict[str, Any]:
        """etcd queue statistics"""
        return {"backend": "etcd", "queue_size": 0}
    
    async def _consul_enqueue(self, job_data: Dict[str, Any], priority: int) -> None:
        """Consul enqueue implementation"""
        pass
    
    async def _consul_dequeue(self, timeout: int) -> Optional[Dict[str, Any]]:
        """Consul dequeue implementation"""
        pass
    
    async def _consul_complete_job(self, completion_data: Dict[str, Any]) -> None:
        """Consul job completion"""
        pass
    
    async def _consul_queue_stats(self) -> Dict[str, Any]:
        """Consul queue statistics"""
        return {"backend": "consul", "queue_size": 0}


# ============================================================================
# GOOGLE-LEVEL DYNAMIC WORKER POOL
# ============================================================================

class DynamicWorkerPool:
    """
    Google-level dynamic worker pool with autoscaling.
    
    Automatically adjusts worker count based on:
    - Queue depth
    - CPU/memory usage
    - Processing latency
    - Error rates
    """
    
    def __init__(
        self,
        min_workers: int = 2,
        max_workers: int = 50,
        target_queue_depth: int = 10,
        scale_up_threshold: float = 0.8,
        scale_down_threshold: float = 0.2,
        cooldown_seconds: int = 30,
        job_queue: Optional[JobQueue] = None
    ):
        self.min_workers = min_workers
        self.max_workers = max_workers
        self.target_queue_depth = target_queue_depth
        self.scale_up_threshold = scale_up_threshold
        self.scale_down_threshold = scale_down_threshold
        self.cooldown_seconds = cooldown_seconds
        self.job_queue = job_queue
        
        # Worker management
        self.current_workers = min_workers
        self.target_workers = min_workers
        self.workers = []
        self.last_scale_time = time.time()
        self.worker_adjustment_cooldown = 0
        
        # GOOGLE-LEVEL: Resource monitoring
        self.current_workers = 0
        self.cpu_usage = 0.0
        self.io_usage = 0.0
        self.queue_size = 0
        self.last_resource_check = time.time()
        
        # Metrics for scaling decisions
        self.queue_depth_history = deque(maxlen=100)
        self.cpu_usage_history = deque(maxlen=100)
        self.memory_usage_history = deque(maxlen=100)
        self.processing_latency_history = deque(maxlen=100)
        self.error_rate_history = deque(maxlen=100)
        
        # Initialize worker pool
        self._initialize_workers()
        
        logger.info(f"Dynamic worker pool initialized: min={min_workers}, max={max_workers}")
    
    def _initialize_workers(self) -> None:
        """Initialize the minimum number of workers"""
        for i in range(self.min_workers):
            worker = self._create_worker(f"worker_{i}")
            self.workers.append(worker)
        
        logger.info(f"Initialized {self.min_workers} workers")
    
    def _create_worker(self, worker_id: str) -> ThreadPoolExecutor:
        """Create a new worker thread pool"""
        return ThreadPoolExecutor(max_workers=1, thread_name_prefix=worker_id)
    
    async def submit_job(self, func, *args, **kwargs) -> asyncio.Future:
        """
        Submit a job to the worker pool.
        
        Returns a Future that will complete when the job is done.
        """
        # Check if we need to scale up
        await self._check_scaling()
        
        # Submit to least loaded worker
        worker = self._get_least_loaded_worker()
        
        # Convert ThreadPoolExecutor future to asyncio future
        loop = asyncio.get_event_loop()
        return await loop.run_in_executor(worker, func, *args, **kwargs)
    
    def _get_least_loaded_worker(self) -> ThreadPoolExecutor:
        """Get the worker with the least load"""
        # Simple round-robin for now, could be enhanced with actual load tracking
        if not self.workers:
            raise RuntimeError("No workers available")
        
        return self.workers[0]  # Simplified - would use actual load metrics
    
    async def _check_scaling(self) -> None:
        """Check if scaling is needed and apply changes"""
        now = time.time()
        
        # Respect cooldown period
        if now - self.last_scale_time < self.cooldown_seconds:
            return
        
        # Collect current metrics
        queue_depth = len(self.queue_depth_history) if self.queue_depth_history else 0
        cpu_usage = sum(self.cpu_usage_history) / len(self.cpu_usage_history) if self.cpu_usage_history else 0
        memory_usage = sum(self.memory_usage_history) / len(self.memory_usage_history) if self.memory_usage_history else 0
        error_rate = sum(self.error_rate_history) / len(self.error_rate_history) if self.error_rate_history else 0
        
        # Determine scaling action
        should_scale_up = (
            queue_depth > self.target_queue_depth * self.scale_up_threshold and
            cpu_usage < 0.8 and  # Don't scale up if CPU is already high
            memory_usage < 0.8 and
            error_rate < 0.1 and  # Don't scale up if error rate is high
            self.current_workers < self.max_workers
        )
        
        should_scale_down = (
            queue_depth < self.target_queue_depth * self.scale_down_threshold and
            self.current_workers > self.min_workers
        )
        
        if should_scale_up:
            await self._scale_up()
            self.last_scale_time = now
        elif should_scale_down:
            await self._scale_down()
            self.last_scale_time = now
    
    async def _scale_up(self) -> None:
        """Scale up by adding a worker"""
        if self.current_workers >= self.max_workers:
            return
        
        worker_id = f"worker_{self.current_workers}"
        worker = self._create_worker(worker_id)
        self.workers.append(worker)
        self.current_workers += 1
        
        logger.info(f"Scaled up to {self.current_workers} workers")
    
    async def _scale_down(self) -> None:
        """Scale down by removing a worker"""
        if self.current_workers <= self.min_workers:
            return
        
        # Remove the last worker
        worker = self.workers.pop()
        worker.shutdown(wait=True)
        self.current_workers -= 1
        
        logger.info(f"Scaled down to {self.current_workers} workers")
    
    def update_metrics(self, queue_depth: int = None, cpu_usage: float = None, memory_usage: float = None, 
                      processing_latency: float = None, error_rate: float = None) -> None:
        """Update metrics for scaling decisions with real-time data"""
        # Get real-time metrics if not provided
        if queue_depth is None and self.job_queue:
            queue_depth = len(self.job_queue.pending_jobs)
        elif queue_depth is None:
            queue_depth = len(self.queue_depth_history) if self.queue_depth_history else 0
            
        if cpu_usage is None:
            cpu_usage = self._get_system_cpu_usage()
        if memory_usage is None:
            memory_usage = self._get_system_memory_usage()
        if processing_latency is None:
            processing_latency = self._get_avg_processing_latency()
        if error_rate is None:
            error_rate = self._get_error_rate()
        
        # Update histories
        self.queue_depth_history.append(queue_depth)
        self.cpu_usage_history.append(cpu_usage)
        self.memory_usage_history.append(memory_usage)
        self.processing_latency_history.append(processing_latency)
        self.error_rate_history.append(error_rate)
        
        # Update Prometheus metrics
        WORKER_COUNT_GAUGE.set(self.current_workers)
        QUEUE_DEPTH_GAUGE.set(queue_depth)
        CPU_USAGE_GAUGE.set(cpu_usage)
        MEMORY_USAGE_GAUGE.set(memory_usage)
        
        # Update internal tracking
        self.queue_size = queue_depth
        self.cpu_usage = cpu_usage
    
    def get_pool_stats(self) -> Dict[str, Any]:
        """Get current pool statistics with real-time data"""
        # Get current real-time metrics
        current_queue_depth = len(self.job_queue.pending_jobs) if self.job_queue else 0
        current_cpu_usage = self._get_system_cpu_usage()
        current_memory_usage = self._get_system_memory_usage()
        
        return {
            "current_workers": self.current_workers,
            "target_workers": self.target_workers,
            "min_workers": self.min_workers,
            "max_workers": self.max_workers,
            "queue_depth": current_queue_depth,
            "avg_queue_depth": len(self.queue_depth_history) if self.queue_depth_history else 0,
            "current_cpu_usage": current_cpu_usage,
            "avg_cpu_usage": sum(self.cpu_usage_history) / len(self.cpu_usage_history) if self.cpu_usage_history else 0,
            "current_memory_usage": current_memory_usage,
            "avg_memory_usage": sum(self.memory_usage_history) / len(self.memory_usage_history) if self.memory_usage_history else 0,
            "avg_processing_latency": sum(self.processing_latency_history) / len(self.processing_latency_history) if self.processing_latency_history else 0,
            "avg_error_rate": sum(self.error_rate_history) / len(self.error_rate_history) if self.error_rate_history else 0,
            "last_scale_time": self.last_scale_time,
            "worker_adjustment_cooldown": self.worker_adjustment_cooldown
        }
    
    async def shutdown(self) -> None:
        """Graceful shutdown of all workers"""
        logger.info(f"Shutting down {self.current_workers} workers")
        
        for worker in self.workers:
            worker.shutdown(wait=True)
        
        self.workers.clear()
        self.current_workers = 0
        
        logger.info("Worker pool shutdown complete")
    
    def _get_system_cpu_usage(self) -> float:
        """Get current system CPU usage"""
        try:
            import psutil
            return psutil.cpu_percent(interval=None)
        except ImportError:
            logger.warning("psutil not available for CPU monitoring")
            return 0.0
        except Exception as e:
            logger.warning(f"Failed to get CPU usage: {e}")
            return 0.0
    
    def _get_system_memory_usage(self) -> float:
        """Get current system memory usage percentage"""
        try:
            import psutil
            memory = psutil.virtual_memory()
            return memory.percent
        except ImportError:
            logger.warning("psutil not available for memory monitoring")
            return 0.0
        except Exception as e:
            logger.warning(f"Failed to get memory usage: {e}")
            return 0.0
    
    def _get_avg_processing_latency(self) -> float:
        """Get average processing latency from history"""
        if not self.processing_latency_history:
            return 0.0
        return sum(self.processing_latency_history) / len(self.processing_latency_history)
    
    def _get_error_rate(self) -> float:
        """Get current error rate from history"""
        if not self.error_rate_history:
            return 0.0
        return sum(self.error_rate_history) / len(self.error_rate_history)


# ============================================================================
# GOOGLE-LEVEL BACKPRESSURE CONTROL
# ============================================================================

class BackpressureController:
    """
    Google-level backpressure control for system stability.
    
    Prevents system overload by:
    - Monitoring queue depth
    - Throttling new requests
    - Prioritizing critical jobs
    - Shedding load when necessary
    """
    
    def __init__(
        self,
        max_queue_depth: int = 1000,
        throttle_threshold: float = 0.8,
        shed_threshold: float = 0.95,
        recovery_threshold: float = 0.5
    ):
        self.max_queue_depth = max_queue_depth
        self.throttle_threshold = throttle_threshold
        self.shed_threshold = shed_threshold
        self.recovery_threshold = recovery_threshold
        
        # State tracking
        self.current_depth = 0
        self.is_throttling = False
        self.is_shedding = False
        self.throttled_requests = 0
        self.shed_requests = 0
        
        # Metrics
        self.depth_history = deque(maxlen=1000)
        self.throttle_history = deque(maxlen=100)
        self.shed_history = deque(maxlen=100)
        
        logger.info(f"Backpressure controller initialized: max_depth={max_queue_depth}")
    
    def can_accept_request(self, priority: int = 0) -> bool:
        """
        Check if a new request can be accepted.
        
        Returns True if request can be processed, False if it should be rejected.
        """
        self.current_depth = len(self.depth_history)
        load_ratio = self.current_depth / self.max_queue_depth
        
        # Update state based on current load
        if load_ratio >= self.shed_threshold:
            self.is_shedding = True
            self.is_throttling = True
        elif load_ratio >= self.throttle_threshold:
            self.is_throttling = True
            self.is_shedding = False
        elif load_ratio <= self.recovery_threshold:
            self.is_throttling = False
            self.is_shedding = False
        
        # Apply backpressure logic
        if self.is_shedding:
            # Only accept high-priority requests when shedding
            if priority < 5:  # Lower priority numbers = higher priority
                self.shed_requests += 1
                self.shed_history.append(time.time())
                logger.warning(f"Shedding low-priority request: priority={priority}, depth={self.current_depth}")
                return False
            else:
                logger.info(f"Accepting high-priority request during shedding: priority={priority}")
                return True
        
        elif self.is_throttling:
            # Throttle based on priority and current load
            throttle_factor = 1.0 - (load_ratio - self.throttle_threshold) / (self.shed_threshold - self.throttle_threshold)
            
            # Higher priority requests are less likely to be throttled
            priority_factor = (priority + 1) / 10.0  # Normalize priority to 0.1-1.0
            acceptance_probability = throttle_factor * priority_factor
            
            if random.random() > acceptance_probability:
                self.throttled_requests += 1
                self.throttle_history.append(time.time())
                logger.debug(f"Throttling request: priority={priority}, prob={acceptance_probability:.2f}")
                return False
            
            return True
        
        # Normal operation - accept all requests
        return True
    
    def record_request(self) -> None:
        """Record a new request being processed"""
        self.depth_history.append(time.time())
    
    def record_completion(self) -> None:
        """Record a request completion"""
        if self.depth_history:
            self.depth_history.popleft()
    
    def get_backpressure_stats(self) -> Dict[str, Any]:
        """Get current backpressure statistics"""
        return {
            "current_depth": self.current_depth,
            "max_queue_depth": self.max_queue_depth,
            "load_ratio": self.current_depth / self.max_queue_depth,
            "is_throttling": self.is_throttling,
            "is_shedding": self.is_shedding,
            "throttled_requests": self.throttled_requests,
            "shed_requests": self.shed_requests,
            "throttle_threshold": self.throttle_threshold,
            "shed_threshold": self.shed_threshold,
            "recovery_threshold": self.recovery_threshold
        }


# ============================================================================
# GOOGLE-LEVEL OBSERVABILITY & MONITORING
# ============================================================================

class MetricsExporter:
    """
    Google-level metrics exporter for production monitoring.
    
    Supports Prometheus, Stackdriver, and custom metrics backends.
    Provides structured logging and alerting integration.
    """
    
    def __init__(self, enabled: bool = True, backend: str = "prometheus"):
        self.enabled = enabled
        self.backend = backend
        self.metrics_registry = {}
        
        # Initialize backend
        if self.enabled:
            self._initialize_backend()
        
        logger.info(f"Metrics exporter initialized: enabled={enabled}, backend={backend}")
    
    def _initialize_backend(self) -> None:
        """Initialize the metrics backend"""
        try:
            if self.backend == "prometheus":
                self._init_prometheus()
            elif self.backend == "stackdriver":
                self._init_stackdriver()
            elif self.backend == "custom":
                self._init_custom()
            else:
                logger.warning(f"Unknown metrics backend: {self.backend}")
                
        except Exception as e:
            logger.error(f"Failed to initialize metrics backend {self.backend}: {e}")
            self.enabled = False
    
    def _init_prometheus(self) -> None:
        """Initialize Prometheus metrics"""
        try:
            # Create Prometheus metrics
            self.metrics_registry = {
                'extraction_requests_total': prometheus_client.Counter(
                    'audio_extraction_requests_total',
                    'Total number of audio extraction requests',
                    ['platform', 'status']
                ),
                'extraction_duration_seconds': prometheus_client.Histogram(
                    'audio_extraction_duration_seconds',
                    'Audio extraction duration in seconds',
                    ['platform'],
                    buckets=[0.1, 0.5, 1.0, 2.0, 5.0, 10.0, 30.0, 60.0, 120.0, 300.0]
                ),
                'active_extractions': prometheus_client.Gauge(
                    'audio_active_extractions',
                    'Number of active audio extractions',
                    ['platform']
                ),
                'queue_depth': prometheus_client.Gauge(
                    'audio_queue_depth',
                    'Number of jobs in extraction queue',
                    ['platform']
                ),
                'error_rate': prometheus_client.Gauge(
                    'audio_extraction_error_rate',
                    'Audio extraction error rate (5 minute window)',
                    ['platform']
                ),
                'checksum_mismatches': prometheus_client.Counter(
                    'audio_checksum_mismatches_total',
                    'Total number of checksum mismatches detected',
                    ['platform']
                ),
                'sync_offset_ms': prometheus_client.Histogram(
                    'audio_sync_offset_milliseconds',
                    'Audio/video sync offset in milliseconds',
                    ['platform'],
                    buckets=[0.1, 0.5, 1.0, 2.0, 5.0, 10.0, 20.0, 50.0, 100.0]
                )
            }
            
            logger.info("Prometheus metrics initialized")
            
        except Exception as e:
            logger.error(f"Failed to initialize Prometheus metrics: {e}")
            raise
    
    def _init_stackdriver(self) -> None:
        """Initialize Stackdriver metrics"""
        try:
            from google.cloud import monitoring_v3
            # Stackdriver implementation would go here
            logger.info("Stackdriver metrics initialized (placeholder)")
            
        except ImportError:
            logger.warning("Stackdriver client not available")
            raise
    
    def _init_custom(self) -> None:
        """Initialize custom metrics backend"""
        self.metrics_registry = {
            'extraction_requests_total': 0,
            'extraction_failures_total': 0,
            'active_extractions': 0,
            'queue_depth': 0,
            'error_rate': 0.0,
            'checksum_mismatches': 0,
            'avg_duration_ms': 0.0,
            'avg_sync_offset_ms': 0.0
        }
        
        logger.info("Custom metrics backend initialized")
    
    def record_extraction_start(self, platform: str) -> None:
        """Record extraction start"""
        if not self.enabled:
            return
        
        if self.backend == "prometheus":
            self.metrics_registry['extraction_requests_total'].labels(platform=platform, status='started').inc()
            self.metrics_registry['active_extractions'].labels(platform=platform).inc()
        elif self.backend == "custom":
            self.metrics_registry['extraction_requests_total'] += 1
            self.metrics_registry['active_extractions'] += 1
    
    def record_extraction_complete(self, platform: str, success: bool, duration_ms: float, sync_offset_ms: float) -> None:
        """Record extraction completion"""
        if not self.enabled:
            return
        
        status = 'success' if success else 'failure'
        
        if self.backend == "prometheus":
            self.metrics_registry['extraction_requests_total'].labels(platform=platform, status=status).inc()
            self.metrics_registry['extraction_duration_seconds'].labels(platform=platform).observe(duration_ms / 1000.0)
            self.metrics_registry['active_extractions'].labels(platform=platform).dec()
            self.metrics_registry['sync_offset_ms'].labels(platform=platform).observe(sync_offset_ms)
            
            if not success:
                self.metrics_registry['error_rate'].labels(platform=platform).inc()
                
        elif self.backend == "custom":
            if success:
                # Update running averages
                current_avg = self.metrics_registry['avg_duration_ms']
                count = self.metrics_registry['extraction_requests_total']
                new_avg = (current_avg * count + duration_ms) / (count + 1)
                self.metrics_registry['avg_duration_ms'] = new_avg
            else:
                self.metrics_registry['extraction_failures_total'] += 1
                self.metrics_registry['active_extractions'] = max(0, self.metrics_registry['active_extractions'] - 1)
    
    def record_checksum_mismatch(self, platform: str) -> None:
        """Record checksum mismatch"""
        if not self.enabled:
            return
        
        if self.backend == "prometheus":
            self.metrics_registry['checksum_mismatches'].labels(platform=platform).inc()
        elif self.backend == "custom":
            self.metrics_registry['checksum_mismatches'] += 1
    
    def update_queue_metrics(self, platform: str, queue_depth: int) -> None:
        """Update queue depth metrics"""
        if not self.enabled:
            return
        
        if self.backend == "prometheus":
            self.metrics_registry['queue_depth'].labels(platform=platform).set(queue_depth)
        elif self.backend == "custom":
            self.metrics_registry['queue_depth'] = queue_depth
    
    def get_metrics_summary(self) -> Dict[str, Any]:
        """Get current metrics summary"""
        if not self.enabled:
            return {"enabled": False}
        
        if self.backend == "custom":
            return {
                "backend": "custom",
                "enabled": True,
                "metrics": self.metrics_registry.copy()
            }
        elif self.backend == "prometheus":
            # Collect Prometheus metrics
            return {
                "backend": "prometheus",
                "enabled": True,
                "metrics": self._collect_prometheus_metrics()
            }
        else:
            return {"backend": self.backend, "enabled": True}
    
    def _collect_prometheus_metrics(self) -> Dict[str, Any]:
        """Collect current Prometheus metric values using proper registry collection"""
        try:
            import prometheus_client
            
            # CRITICAL: Use proper registry collection instead of generate_latest on individual metrics
            metrics_data = {}
            
            # Collect all metrics from the registry
            for metric_family in prometheus_client.REGISTRY.collect():
                metric_name = metric_family.name
                metric_samples = []
                
                # Extract samples from the metric family
                for sample in metric_family.samples:
                    metric_samples.append({
                        'name': sample.name,
                        'value': sample.value,
                        'labels': sample.labels,
                        'timestamp': sample.timestamp
                    })
                
                metrics_data[metric_name] = {
                    'samples': metric_samples,
                    'type': metric_family.type,
                    'help': metric_family.documentation
                }
            
            return metrics_data
            
        except Exception as e:
            logger.error(f"Failed to collect Prometheus metrics: {e}")
            return {}


class HealthChecker:
    """
    Google-level health checker for service monitoring.
    
    Provides comprehensive health checks including:
    - Service availability
    - Dependency health
    - Resource utilization
    - Performance metrics
    """
    
    def __init__(self, check_interval: int = 30):
        self.check_interval = check_interval
        self.last_check_time = 0
        self.health_status = "healthy"
        self.health_details = {}
        
        # CRITICAL: Rolling averages for disk I/O and network metrics
        from collections import deque
        self.disk_io_history = deque(maxlen=60)  # 60 samples for rolling average
        self.network_history = deque(maxlen=60)   # 60 samples for rolling average
        self.last_disk_io = None
        self.last_network_io = None
        
        logger.info(f"Health checker initialized: interval={check_interval}s")
    
    async def check_health(self) -> Dict[str, Any]:
        """
        Perform comprehensive health check.
        
        Returns health status and detailed information.
        """
        now = time.time()
        
        # Rate limit health checks
        if now - self.last_check_time < self.check_interval:
            return self._get_cached_health()
        
        self.last_check_time = now
        
        # Perform health checks
        checks = {
            'service_health': self._check_service_health(),
            'dependencies': await self._check_dependencies(),
            'resources': self._check_resources(),
            'performance': self._check_performance()
        }
        
        # Determine overall health
        all_healthy = all(check['healthy'] for check in checks.values())
        self.health_status = "healthy" if all_healthy else "unhealthy"
        self.health_details = checks
        
        return self._get_cached_health()
    
    def _get_cached_health(self) -> Dict[str, Any]:
        """Get cached health status"""
        return {
            "status": self.health_status,
            "timestamp": self.last_check_time,
            "checks": self.health_details
        }
    
    def _check_service_health(self) -> Dict[str, Any]:
        """Check service health"""
        try:
            # Check if core components are responding
            health_score = 100  # Start with perfect score
            
            # Check file system access
            test_file = Path("/tmp/health_check")
            test_file.write_text("health_check")
            test_file.unlink()
            
            # Check memory usage
            import psutil
            memory_percent = psutil.virtual_memory().percent
            if memory_percent > 90:
                health_score -= 20
            
            # Check CPU usage (non-blocking)
            cpu_percent = psutil.cpu_percent(interval=None)  # Non-blocking
            if cpu_percent > 90:
                health_score -= 20
            
            return {
                "healthy": health_score >= 80,
                "score": health_score,
                "memory_usage_percent": memory_percent,
                "cpu_usage_percent": cpu_percent,
                "filesystem": "ok"
            }
            
        except Exception as e:
            return {
                "healthy": False,
                "score": 0,
                "error": str(e)
            }
    
    async def _check_dependencies(self) -> Dict[str, Any]:
        """Check dependency health"""
        dependencies = {}
        
        # Check FFmpeg availability
        try:
            result = subprocess.run(["ffmpeg", "-version"], capture_output=True, text=True, timeout=5)
            dependencies["ffmpeg"] = {
                "healthy": result.returncode == 0,
                "version": result.stdout.split('\n')[0] if result.returncode == 0 else "error"
            }
        except Exception as e:
            dependencies["ffmpeg"] = {
                "healthy": False,
                "error": str(e)
            }
        
        # Check Redis if available
        try:
            import redis
            r = redis.Redis(host='localhost', port=6379, socket_timeout=5)
            r.ping()
            dependencies["redis"] = {"healthy": True}
        except Exception as e:
            dependencies["redis"] = {"healthy": False, "error": str(e)}
        
        # Check disk space
        try:
            import psutil
            disk_usage = psutil.disk_usage('/')
            free_percent = (disk_usage.free / disk_usage.total) * 100
            dependencies["disk_space"] = {
                "healthy": free_percent > 10,  # At least 10% free
                "free_percent": free_percent,
                "free_gb": disk_usage.free / (1024**3)
            }
        except Exception as e:
            dependencies["disk_space"] = {"healthy": False, "error": str(e)}
        
        all_healthy = all(dep.get("healthy", False) for dep in dependencies.values())
        
        return {
            "healthy": all_healthy,
            "dependencies": dependencies
        }
    
    def _check_resources(self) -> Dict[str, Any]:
        """Check resource utilization with rolling averages"""
        try:
            import psutil
            
            # Memory
            memory = psutil.virtual_memory()
            
            # CPU (non-blocking)
            cpu_percent = psutil.cpu_percent(interval=None)
            
            # Disk I/O with rolling average
            current_disk_io = psutil.disk_io_counters()
            disk_io_rate = 0.0
            if self.last_disk_io and current_disk_io:
                # Calculate rate since last check
                read_rate = (current_disk_io.read_bytes - self.last_disk_io.read_bytes) / 1024 / 1024  # MB/s
                write_rate = (current_disk_io.write_bytes - self.last_disk_io.write_bytes) / 1024 / 1024  # MB/s
                disk_io_rate = read_rate + write_rate
                
                # Add to history
                self.disk_io_history.append(disk_io_rate)
                
                # Calculate rolling average
                if len(self.disk_io_history) > 0:
                    disk_io_rate = sum(self.disk_io_history) / len(self.disk_io_history)
            
            self.last_disk_io = current_disk_io
            
            # Network with rolling average
            current_network = psutil.net_io_counters()
            network_rate = 0.0
            if self.last_network_io and current_network:
                # Calculate rate since last check
                sent_rate = (current_network.bytes_sent - self.last_network_io.bytes_sent) / 1024 / 1024  # MB/s
                recv_rate = (current_network.bytes_recv - self.last_network_io.bytes_recv) / 1024 / 1024  # MB/s
                network_rate = sent_rate + recv_rate
                
                # Add to history
                self.network_history.append(network_rate)
                
                # Calculate rolling average
                if len(self.network_history) > 0:
                    network_rate = sum(self.network_history) / len(self.network_history)
            
            self.last_network_io = current_network
            
            return {
                "healthy": memory.percent < 90 and cpu_percent < 90,
                "memory": {
                    "percent": memory.percent,
                    "available_gb": memory.available / (1024**3),
                    "used_gb": memory.used / (1024**3)
                },
                "cpu": {
                    "percent": cpu_percent,
                    "count": psutil.cpu_count()
                },
                "disk_io": {
                    "rate_mb_s": disk_io_rate,
                    "samples": len(self.disk_io_history)
                },
                "network": {
                    "rate_mb_s": network_rate,
                    "samples": len(self.network_history)
                }
            }
            
        except Exception as e:
            return {
                "healthy": False,
                "error": str(e)
            }
    
    def _check_performance(self) -> Dict[str, Any]:
        """Check performance metrics"""
        # This would integrate with actual performance metrics
        # For now, return a placeholder
        return {
            "healthy": True,
            "avg_response_time_ms": 0.0,
            "throughput_per_second": 0.0,
            "error_rate_5min": 0.0
        }


class AlertManager:
    """
    Google-level alert manager for production monitoring.
    
    Provides configurable alerting with multiple channels:
    - Structured logging
    - Prometheus alerts
    - Webhook notifications
    - Email alerts
    """
    
    def __init__(self, enabled: bool = True):
        self.enabled = enabled
        self.alert_history = deque(maxlen=1000)
        self.alert_thresholds = {
            'failure_rate': 0.1,  # 10% failure rate
            'avg_duration_ms': 30000,  # 30 seconds
            'queue_depth': 100,  # 100 jobs in queue
            'error_rate_5min': 0.05,  # 5% error rate in 5 minutes
            'memory_usage': 0.9,  # 90% memory usage
            'cpu_usage': 0.9  # 90% CPU usage
        }
        
        # CRITICAL: Real alert channel configuration
        self.alert_channels = {
            'pagerduty': {
                'enabled': os.getenv('PAGERDUTY_ENABLED', 'false').lower() == 'true',
                'integration_key': os.getenv('PAGERDUTY_INTEGRATION_KEY'),
                'severity_mapping': {
                    'critical': 'critical',
                    'warning': 'warning',
                    'info': 'info'
                }
            },
            'slack': {
                'enabled': os.getenv('SLACK_ENABLED', 'false').lower() == 'true',
                'webhook_url': os.getenv('SLACK_WEBHOOK_URL'),
                'channel': os.getenv('SLACK_CHANNEL', '#alerts'),
                'username': os.getenv('SLACK_USERNAME', 'AudioExtractor')
            },
            'webhook': {
                'enabled': os.getenv('WEBHOOK_ENABLED', 'false').lower() == 'true',
                'url': os.getenv('WEBHOOK_URL'),
                'timeout': int(os.getenv('WEBHOOK_TIMEOUT', '10'))
            }
        }
        
        logger.info(f"Alert manager initialized: enabled={enabled}")
    
    def check_alerts(self, metrics: Dict[str, Any]) -> List[Dict[str, Any]]:
        """
        Check metrics against alert thresholds.
        
        Returns list of triggered alerts.
        """
        if not self.enabled:
            return []
        
        # CRITICAL: Normalize metrics from different backends
        normalized_metrics = self._normalize_metrics(metrics)
        
        alerts = []
        timestamp = datetime.utcnow().isoformat()
        
        # Check failure rate
        if 'error_rate' in normalized_metrics and normalized_metrics['error_rate'] > self.alert_thresholds['failure_rate']:
            alert = {
                "type": "high_failure_rate",
                "severity": "critical",
                "message": f"High failure rate: {normalized_metrics['error_rate']:.2%}",
                "threshold": self.alert_thresholds['failure_rate'],
                "current_value": normalized_metrics['error_rate'],
                "timestamp": timestamp
            }
            alerts.append(alert)
            self._send_alert(alert)
        
        # Check average duration
        if 'avg_duration_ms' in normalized_metrics and normalized_metrics['avg_duration_ms'] > self.alert_thresholds['avg_duration_ms']:
            alert = {
                "type": "high_duration",
                "severity": "warning",
                "message": f"High average duration: {normalized_metrics['avg_duration_ms']:.0f}ms",
                "threshold": self.alert_thresholds['avg_duration_ms'],
                "current_value": normalized_metrics['avg_duration_ms'],
                "timestamp": timestamp
            }
            alerts.append(alert)
            self._send_alert(alert)
        
        # Check queue depth
        if 'queue_depth' in normalized_metrics and normalized_metrics['queue_depth'] > self.alert_thresholds['queue_depth']:
            alert = {
                "type": "high_queue_depth",
                "severity": "warning",
                "message": f"High queue depth: {normalized_metrics['queue_depth']}",
                "threshold": self.alert_thresholds['queue_depth'],
                "current_value": normalized_metrics['queue_depth'],
                "timestamp": timestamp
            }
            alerts.append(alert)
            self._send_alert(alert)
        
        # Check memory usage
        if 'memory_usage' in normalized_metrics and normalized_metrics['memory_usage'] > self.alert_thresholds['memory_usage']:
            alert = {
                "type": "high_memory_usage",
                "severity": "critical",
                "message": f"High memory usage: {normalized_metrics['memory_usage']:.1%}",
                "threshold": self.alert_thresholds['memory_usage'],
                "current_value": normalized_metrics['memory_usage'],
                "timestamp": timestamp
            }
            alerts.append(alert)
            self._send_alert(alert)
        
        # Check CPU usage
        if 'cpu_usage' in normalized_metrics and normalized_metrics['cpu_usage'] > self.alert_thresholds['cpu_usage']:
            alert = {
                "type": "high_cpu_usage",
                "severity": "critical",
                "message": f"High CPU usage: {normalized_metrics['cpu_usage']:.1%}",
                "threshold": self.alert_thresholds['cpu_usage'],
                "current_value": normalized_metrics['cpu_usage'],
                "timestamp": timestamp
            }
            alerts.append(alert)
            self._send_alert(alert)
        
        # Store alerts in history
        for alert in alerts:
            self.alert_history.append(alert)
        
        return alerts
    
    def _normalize_metrics(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        """
        Normalize metrics from different backends to flat format.
        
        Handles both Prometheus nested format and flat metrics.
        """
        normalized = {}
        
        # Handle Prometheus nested metrics
        if 'metrics' in metrics and isinstance(metrics['metrics'], dict):
            prometheus_metrics = metrics['metrics']
            
            # Extract error rate from Prometheus metrics
            if 'audio_extraction_error_rate' in prometheus_metrics:
                error_rate_samples = prometheus_metrics['audio_extraction_error_rate'].get('samples', [])
                if error_rate_samples:
                    # Get the latest error rate value
                    normalized['error_rate'] = error_rate_samples[-1]['value']
            
            # Extract queue depth from Prometheus metrics
            if 'audio_queue_depth' in prometheus_metrics:
                queue_samples = prometheus_metrics['audio_queue_depth'].get('samples', [])
                if queue_samples:
                    # Sum queue depths across all platforms
                    total_queue_depth = sum(sample['value'] for sample in queue_samples)
                    normalized['queue_depth'] = total_queue_depth
            
            # Extract duration from Prometheus metrics
            if 'audio_extraction_duration_seconds' in prometheus_metrics:
                duration_samples = prometheus_metrics['audio_extraction_duration_seconds'].get('samples', [])
                if duration_samples:
                    # Calculate average duration in milliseconds
                    avg_duration_seconds = sum(sample['value'] for sample in duration_samples) / len(duration_samples)
                    normalized['avg_duration_ms'] = avg_duration_seconds * 1000
        
        # Handle flat metrics (direct format)
        else:
            # Copy flat metrics directly
            for key, value in metrics.items():
                if key in ['error_rate', 'queue_depth', 'avg_duration_ms', 'memory_usage', 'cpu_usage']:
                    normalized[key] = value
        
        # Handle health check metrics (convert from nested format)
        if 'resources' in metrics and isinstance(metrics['resources'], dict):
            resources = metrics['resources']
            if 'memory' in resources and 'percent' in resources['memory']:
                normalized['memory_usage'] = resources['memory']['percent'] / 100.0
            if 'cpu' in resources and 'percent' in resources['cpu']:
                normalized['cpu_usage'] = resources['cpu']['percent'] / 100.0
        
        return normalized
    
    def _send_alert(self, alert: Dict[str, Any]) -> None:
        """Send alert through configured channels"""
        # Structured logging (always enabled)
        logger.error(
            f"ALERT: {alert['type']} - {alert['message']}",
            extra={
                "alert_type": alert["type"],
                "severity": alert["severity"],
                "threshold": alert["threshold"],
                "current_value": alert["current_value"],
                "timestamp": alert["timestamp"]
            }
        )
        
        # Send to PagerDuty
        if self.alert_channels['pagerduty']['enabled']:
            self._send_pagerduty_alert(alert)
        
        # Send to Slack
        if self.alert_channels['slack']['enabled']:
            self._send_slack_alert(alert)
        
        # Send to webhook
        if self.alert_channels['webhook']['enabled']:
            self._send_webhook_alert(alert)
    
    def _send_pagerduty_alert(self, alert: Dict[str, Any]) -> None:
        """Send alert to PagerDuty"""
        try:
            import requests
            
            integration_key = self.alert_channels['pagerduty']['integration_key']
            if not integration_key:
                logger.warning("PagerDuty integration key not configured")
                return
            
            severity = self.alert_channels['pagerduty']['severity_mapping'].get(
                alert['severity'], 'warning'
            )
            
            payload = {
                "routing_key": integration_key,
                "event_action": "trigger",
                "payload": {
                    "summary": f"AudioExtractor Alert: {alert['type']}",
                    "source": "audio_extractor",
                    "severity": severity,
                    "timestamp": alert['timestamp'],
                    "custom_details": {
                        "alert_type": alert['type'],
                        "message": alert['message'],
                        "threshold": alert['threshold'],
                        "current_value": alert['current_value'],
                        "severity": alert['severity']
                    }
                }
            }
            
            response = requests.post(
                "https://events.pagerduty.com/v2/enqueue",
                json=payload,
                timeout=10
            )
            
            if response.status_code == 202:
                logger.info(f"PagerDuty alert sent successfully: {alert['type']}")
            else:
                logger.error(f"Failed to send PagerDuty alert: {response.status_code} - {response.text}")
                
        except Exception as e:
            logger.error(f"Error sending PagerDuty alert: {e}")
    
    def _send_slack_alert(self, alert: Dict[str, Any]) -> None:
        """Send alert to Slack"""
        try:
            import requests
            
            webhook_url = self.alert_channels['slack']['webhook_url']
            if not webhook_url:
                logger.warning("Slack webhook URL not configured")
                return
            
            # Color based on severity
            color_map = {
                'critical': 'danger',
                'warning': 'warning',
                'info': 'good'
            }
            color = color_map.get(alert['severity'], 'warning')
            
            payload = {
                "channel": self.alert_channels['slack']['channel'],
                "username": self.alert_channels['slack']['username'],
                "attachments": [{
                    "color": color,
                    "title": f"AudioExtractor Alert: {alert['type']}",
                    "text": alert['message'],
                    "fields": [
                        {
                            "title": "Severity",
                            "value": alert['severity'],
                            "short": True
                        },
                        {
                            "title": "Threshold",
                            "value": str(alert['threshold']),
                            "short": True
                        },
                        {
                            "title": "Current Value",
                            "value": str(alert['current_value']),
                            "short": True
                        },
                        {
                            "title": "Timestamp",
                            "value": alert['timestamp'],
                            "short": True
                        }
                    ],
                    "timestamp": alert['timestamp']
                }]
            }
            
            response = requests.post(webhook_url, json=payload, timeout=10)
            
            if response.status_code == 200:
                logger.info(f"Slack alert sent successfully: {alert['type']}")
            else:
                logger.error(f"Failed to send Slack alert: {response.status_code} - {response.text}")
                
        except Exception as e:
            logger.error(f"Error sending Slack alert: {e}")
    
    def _send_webhook_alert(self, alert: Dict[str, Any]) -> None:
        """Send alert to generic webhook"""
        try:
            import requests
            
            webhook_url = self.alert_channels['webhook']['url']
            if not webhook_url:
                logger.warning("Webhook URL not configured")
                return
            
            timeout = self.alert_channels['webhook']['timeout']
            
            payload = {
                "alert": alert,
                "service": "audio_extractor",
                "timestamp": alert['timestamp']
            }
            
            response = requests.post(webhook_url, json=payload, timeout=timeout)
            
            if response.status_code == 200:
                logger.info(f"Webhook alert sent successfully: {alert['type']}")
            else:
                logger.error(f"Failed to send webhook alert: {response.status_code} - {response.text}")
                
        except Exception as e:
            logger.error(f"Error sending webhook alert: {e}")
    
    def get_alert_history(self, limit: int = 100) -> List[Dict[str, Any]]:
        """Get recent alert history"""
        return list(self.alert_history)[-limit:]
    
    def get_alert_stats(self) -> Dict[str, Any]:
        """Get alert statistics"""
        if not self.alert_history:
            return {"total_alerts": 0}
        
        # Count alerts by type and severity
        alert_counts = {}
        severity_counts = {}
        
        for alert in self.alert_history:
            alert_type = alert["type"]
            severity = alert["severity"]
            
            alert_counts[alert_type] = alert_counts.get(alert_type, 0) + 1
            severity_counts[severity] = severity_counts.get(severity, 0) + 1
        
        return {
            "total_alerts": len(self.alert_history),
            "alert_types": alert_counts,
            "severity_distribution": severity_counts,
            "latest_alert": self.alert_history[-1] if self.alert_history else None
        }

