            frame_count=kwargs["frame_count"],
            frame_rate=metadata.fps,
            channel_map=DEFAULT_STEREO_CHANNEL_MAP if kwargs["channels"] == 2 else DEFAULT_MONO_CHANNEL_MAP,
            sample_rate_actual=float(kwargs["sample_rate"]),
            
            # Beat and rhythm metrics
            first_beat_time_ms=kwargs["beat_metrics"].get("first_beat_time_ms", 0.0),
