def main():
    """
    Example CLI for testing and manual runs.
    
    Production usage would integrate with scaling_controller.py
    """
    import argparse
    
    parser = argparse.ArgumentParser(description="Audio Extraction Pipeline")
    parser.add_argument("--data-root", required=True, help="Root data directory")
    parser.add_argument("--video-id", required=True, help="Video ID to process")
    parser.add_argument("--platform", required=True, choices=["tiktok", "youtube_shorts", "instagram_reels"])
    parser.add_argument("--duration", type=float, required=True, help="Video duration (seconds)")
    parser.add_argument("--fps", type=float, default=30.0, help="Video FPS")
    parser.add_argument("--container", default="mp4", help="Container format")
    parser.add_argument("--mode", choices=["live", "backfill"], default="live")
    parser.add_argument("--force", action="store_true", help="Force re-extraction")
    parser.add_argument("--dry-run", action="store_true", help="Dry run mode")
    
    args = parser.parse_args()
    
    # Create metadata
    metadata = VideoMetadata(
        video_id=args.video_id,
        platform=args.platform,
        container_format=args.container,
        duration_seconds=args.duration,
        fps=args.fps
    )
    
    # Initialize extractor
    extractor = AudioExtractor(
        data_root=Path(args.data_root),
        run_mode=RunMode(args.mode)
    )
    
    # Process
    result = extractor.process_video(metadata, force_reextract=args.force)
    
    if result.success:
        print(f"âœ“ Success: {result.audio_path}")
        if result.manifest:
            print(f"  Duration: {result.manifest.duration_seconds:.2f}s")
            print(f"  Channels: {result.manifest.channels}")
            print(f"  Sample Rate: {result.manifest.sample_rate}Hz")
            print(f"  Loudness: {result.manifest.loudness_lufs:.1f} LUFS")
            print(f"  Silence: {result.manifest.silence_ratio * 100:.1f}%")
    else:
        print(f"âœ— Failed: {result.error}")
        exit(1)
    
    extractor.shutdown()

# TESTABILITY CONTRACT (MANDATORY)
# ============================================================================

def extract_audio(
    video_path: Path,
    output_path: Path,
    dry_run: bool = False,
    ffmpeg_client = None,
    metadata: Optional[VideoMetadata] = None,
    data_root: Optional[Path] = None
) -> ExtractionResult:
    """
    TESTABILITY HOOK - Required for comprehensive testing
    
    Test mode must support:
    - Mock ffmpeg: Use injected ffmpeg_client for testing
    - Fixed timestamps: Deterministic timestamps for reproducible tests
    - No filesystem writes: Dry run mode prevents actual file operations
    - Deterministic manifests: Predictable manifest generation for tests
    
    Args:
        video_path: Path to input video file
        output_path: Path for output audio file
        dry_run: If True, no actual filesystem writes
        ffmpeg_client: Optional mock ffmpeg client for testing
        metadata: Optional VideoMetadata (required for non-dry-run mode)
        data_root: Optional data root path (defaults to /tmp/test_data)
        
    Returns:
        ExtractionResult: Success/failure result with metadata
    """
    # CRITICAL: Non-dry-run mode requires valid metadata from video_downloader.py
    if not dry_run and metadata is None:
        raise CorruptedInputError(
            "HARD FAIL: Non-dry-run mode requires valid VideoMetadata from video_downloader.py"
        )
    
    # CRITICAL: Validate metadata meets input contract
    if metadata is not None:
        metadata.validate()
    
    # Use provided data_root or default for testing
    if data_root is None:
        data_root = Path("/tmp/test_data")
    else:
        data_root = Path(data_root)
    
    # Normal extraction mode - create extractor with mock client if provided
    extractor = AudioExtractor(data_root=data_root, ffmpeg_client=ffmpeg_client)
    
    return extractor.extract_audio(video_path, output_path, metadata, dry_run=dry_run)


